// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 응시
// ==========================================
// 응시 — 무엇이 진짜 무엇인지 보는 눈. 약점, 저주, 봉인.
// scholar 학자 · hexer 주술사 · exorcist 퇴마사 · physiog 관상가 · detective 탐정
// S1 『표본실 — 착륙 이후』 · S2 『백악기 정원』

// ── 학자 (자원 없음)
kJob('scholar', 'S', [

{ at:'S', t:'발자국 — 보폭',
  x:`젖은 바닥에 발자국이 찍혔다. 발가락이 셋. 깊다.<br><br>
    학자는 발자국으로 몸을 세운다. 보폭이 걸음을 말하고 깊이가 무게를 말한다.<br>
    보폭을 쟀다. 이쪽 다섯 걸음이다. 걷는 자국이 그렇다.<br><br>
    뛰면 더 벌어진다.`,
  o:[
    { l:'① 보폭과 깊이로 그것의 걸음을 계산한다.', k:'gaze', dc:24, wake:1,
      ok:`앞발 자국만 유난히 깊은 자리가 있다. 달리다 멈춘 자국이다.<br><br>멈춘 자국의 발끝이 전부 한쪽을 향한다. 이쪽이 가려던 길이다. 그것은 거기 서서 기다려 본 적이 있다. 기다려서 먹어 본 적이 있다는 뜻이다.<br>그 길을 버리고 돌았다. 돌아가며 보니 원래 길목 바위에 턱 높이로 긁힌 자국이 나 있었다. 기다리며 간 자국이다.<br><br>책의 도표는 여기 짐승을 모른다. 이제 제 걸음이 자다. 학자는 제 몸으로 재는 법을 얻었다.`,
      ng:`재는 동안 자국 바닥에 물이 차오르는 걸 봤다.<br><br>오래된 자국에는 물이 벌써 차 있다. 이건 아직 차는 중이다.<br>방금 지나갔다는 뜻이다. 고개를 들자 어둠 저쪽에서 물 밟는 소리가 멎었다. 이쪽도 멎었다. 둘 다 오래 멎어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 자국이 오래된 쪽으로 길을 잡는다.', k:'sense', dc:23,
      ok:`가장자리가 무너진 자국이 오래된 자국이다. 가장자리가 선 자국이 새것이다.<br><br>오래된 자국만 이어지는 길을 골랐다. 그것이 요즘 안 다니는 길이다.<br>한참을 갔다. 새 자국이 하나도 없었다. 숨이 처음으로 끝까지 쉬어졌다.`,
      ng:`무너진 자국과 선 자국이 섞여서 헷갈렸다.<br><br>고른 길이 하필 제일 새 길이었다. 모퉁이에서 긴 숨소리가 났다.<br>왔던 만큼을 뛰어서 돌아왔다. 숨소리는 따라오지 않았다. 배가 불렀던 것뿐이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'사체 — 이빨 간격',
  x:`큰 짐승이 쓰러져 있다. 몸의 반이 없다. 한 입이다.<br><br>
    학자는 상처로 입을 복원한다. 이빨 자국의 간격이 두 뼘. 자국 수를 셌다.<br>
    세다가 멈췄다. 자국이 두 벌이다. 간격이 다르다.<br><br>
    한 마리가 아니다.`,
  o:[
    { l:'① 이빨 간격으로 턱의 폭을 계산한다.', k:'gaze', dc:24,
      ok:`큰 쪽 자국으로 턱을 세웠다. 벌린 폭이 이쪽 키만 하다.<br><br>그 턱은 좁은 틈으로 못 들어온다. 몸이 머리보다 좁은 짐승은 없다.<br>어깨가 겨우 지나는 틈새 길을 골라 걸었다. 넓은 쪽 어둠에서 긴 숨이 한 번 지나갔다. 틈으로는 숨만 들어왔다.`,
      ng:`작은 쪽 자국을 재다가 손끝에 온기가 닿았다.<br><br>상처가 아직 따뜻하다. 방금이다.<br>작은 쪽이 아직 근처에 있다. 큰 쪽에게 뺏기고 물러난 것이 이쪽을 본다. 뺏긴 몫을 채울 것을 찾는 눈으로. 바위 뒤에 한참 엎드려 있었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 남은 살을 빠르게 거둔다.', k:'break', dc:23,
      ok:`망설이면 냄새만 퍼진다. 단숨에 끊어 거뒀다.<br><br>먹다 남긴 것을 먹는 건 이런 데의 법이다. 살은 성했다.<br>자리를 뜨고 한참 뒤에 그쪽에서 뼈 부러지는 소리가 났다. 그것이 돌아와 제 몫을 세는 소리다. 모자란 걸 알아도 이쪽은 이미 멀다.`,
      ng:`끊는 데 오래 걸렸다. 피 냄새가 바람을 탔다.<br><br>어둠 두 군데서 동시에 기척이 일었다. 고기를 버리고 뛰었다.<br>빈손이다. 냄새는 손에 남았다. 밤새 손이 신경 쓰였다.`,
      win:{ exp:15, item:'짐승 고기' }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S', t:'수첩 — 앞선 탐사대',
  x:`바위 틈에 배낭이 끼어 있다. 주인은 없다.<br><br>
    수첩이 나왔다. 앞 장은 또박또박하고 뒤로 갈수록 글씨가 급해진다.<br>
    마지막 장은 한 줄이다.<br><br>
    「그것은 불빛을 센다.」`,
  o:[
    { l:'① 급해진 글씨에서 닷새를 다시 세운다.', k:'gaze', dc:25, wake:1,
      ok:`날짜와 글씨를 맞춰 읽었다. 그들은 닷새를 버텼다.<br><br>버틴 방법이 흩어져 적혀 있다. 불을 하나로 줄였다. 등을 벽에 붙이고 잤다. 묻는 말에 답하지 않았다.<br>마지막 줄의 뜻도 풀렸다. 불이 둘이면 둘로 센다. 사람 수를 세는 것이다. 등불을 하나로 모았다.<br><br>죽은 사람의 닷새를 하룻밤에 읽어 제 것으로 만들었다. 기록은 두 번 산다. 학자의 손에서 두 번째로.`,
      ng:`마지막 장 다음에 찢긴 자리가 있다.<br><br>찢긴 결이 바깥을 향해 있다. 넣은 쪽에서 찢어 갔다는 뜻이다.<br>수첩 주인은 배낭을 틈에 끼우고 어디로 갔나. 찢어 간 장에는 무엇이 적혔었나. 생각이 거기서 안 넘어갔다. 밤새.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 배낭 바닥을 뒤진다.', k:'luck', dc:23,
      ok:`바닥에 기름 먹인 천 뭉치가 있다. 비상식이다.<br><br>말린 고기가 손바닥만큼 나왔다. 주인이 아껴 둔 몫이다.<br>천은 도로 접어 배낭에 넣었다. 다음 사람 것도 남겨 두는 게 이 수첩에 적힌 법이었다.`,
      ng:`배낭이 틈에 왜 끼었는지 꺼내다가 알았다.<br><br>당기는 순간 틈 위쪽에서 돌가루가 쏟아졌다. 틈 위에 다녀간 자국이 있다. 배낭은 거기 걸려 있던 게 아니라 놓여 있던 것이다.<br>미끼라는 말이 머리를 스쳤다. 빈손으로 물러났다.`,
      win:{ exp:14, item:'말린 고기' }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'둥지 가장자리 — 껍데기 셈',
  x:`움푹한 자리에 껍데기가 흩어져 있다. 알이었던 것들이다.<br><br>
    깨진 결이 두 가지다. 안에서 민 것과 밖에서 깨 먹힌 것.<br>
    학자는 쪼그려 앉아 셌다.<br><br>
    안에서 민 것 아홉. 먹힌 것 셋.`,
  o:[
    { l:'① 껍데기로 머릿수를 확정한다.', k:'gaze', dc:24,
      ok:`아홉이 깨고 나와 자랐다. 아홉이 지금 어딘가에 있다.<br><br>아홉이라는 수를 알고 걷는 것과 모르고 걷는 것은 다르다.<br>그 뒤로 길목에서 기척을 만날 때마다 아홉에서 하나씩 지웠다. 수가 남아 있는 동안은 마음을 안 놓았다.`,
      ng:`세다가 손이 멎었다. 껍데기 하나가 아직 축축하다.<br><br>안쪽 막이 마르지 않았다. 오늘 깬 것이다.<br>열째가 있다. 갓 깬 것은 멀리 못 간다. 그 말은, 아주 가까이 있다는 말이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 둥지 가운데를 가로질러 시간을 아낀다.', k:'hide', dc:25,
      doom:{ title:'알 자리', what:'둥지 주인에게 물려 어둠 속으로 끌려갑니다', dc:19, sec:45,
        text:`반쯤 건넜을 때 등 뒤에서 껍데기 눌리는 소리가 났다.<br><br>이쪽은 밟지 않았다. 밟은 건 다른 발이다.<br>돌아보기 전에 목덜미 옷깃이 들렸다. 발이 바닥에서 떨어진다. 껍데기들이 아래로 멀어진다.<br><br>둥지 주인은 제 자리를 가로지른 것을 문 채 어둠으로 걸어 들어간다.`,
        dieText:`둥지에 껍데기가 그대로 흩어져 있다.<br><br>셈이 하나 틀리게 됐다. 먹힌 쪽이 하나 늘어서.<br>다음에 세는 사람은 그걸 모르고 셀 것이다.` },
      ok:`디딜 자리를 눈으로 먼저 다 정했다. 그다음에 걸었다.<br><br>껍데기를 하나도 울리지 않고 건넜다.<br>건너고 나서야 숨을 쉬었다. 멀리서 둥지로 돌아오는 발소리가 났다. 셈이 맞는 발소리였다. 아홉 중 하나.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'울음 — 마디',
  x:`어둠 저쪽에서 운다. 셋이다. 짧게, 길게, 짧게.<br><br>
    학자는 반복을 듣는다. 같은 마디가 자꾸 돌아온다.<br>
    돌아오는 것에는 규칙이 있다. 규칙이 있으면 말이다.<br><br>
    이건 울음이 아니라 말이다.`,
  o:[
    { l:'① 마디를 받아 적어 규칙을 찾는다.', k:'gaze', dc:25, wake:1,
      ok:`숯으로 받아 적었다. 마디가 셋으로 나뉜다.<br><br>첫 마디는 늘 같다. 자리다. 둘째 마디는 이쪽 사람 수가 바뀔 때 같이 바뀌었다. 수다. 셋째 마디는 끝내 모르겠다.<br>그것들은 이쪽을 세고 있다. 일행을 바짝 붙여 한 덩이로 걷게 했다. 둘째 마디가 흔들리기 시작했다. 셈이 안 되는 먹이는 함부로 못 문다.<br><br>책에 없는 말을 받아 적는 손이 생겼다. 학자의 책은 이제 제가 쓴다.`,
      ng:`받아 적는 데 정신이 팔렸다.<br><br>셋째 마디가 바로 등 뒤에서 났다.<br>가까이 온 걸 몰랐다. 자리를 버리고 뛰었다. 수첩은 챙겼다. 적던 줄이 길게 그어져 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 일행에게 흉내 금지를 돌린다.', k:'fix', dc:23,
      ok:`하나가 입술을 모으고 있었다. 휘파람으로 따라 해 볼 참이었다.<br><br>손으로 입을 막았다. 흉내는 대답이다. 대답하면 자리가 밝혀진다.<br>울음이 한참 더 오가다 멀어졌다. 묻는 쪽만 있고 답하는 쪽이 없으면 거기엔 아무도 없는 것이다.`,
      ng:`한발 늦었다. 하나가 이미 두 마디를 따라 했다.<br><br>울음이 뚝 멎었다.<br>멎은 쪽이 더 무섭다. 밤새 두 번 자리를 옮겼다. 흉내 낸 일행은 제 입을 제 손으로 때렸다.`,
      win:{ exp:16, mind:5 }, lose:{ spirit:-18, mind:-14 } }
  ] },

{ at:'S', t:'뼈 무더기 — 남긴 것',
  x:`뼈가 사람 키만큼 쌓였다. 여러 짐승 것이 섞였다.<br><br>
    학자는 쌓인 것에서 순서를 본다. 배 쪽 뼈는 다 바스러졌고 머리뼈는 성하다.<br>
    배부터 먹고 머리는 버린다는 뜻이다.<br><br>
    사람 뼈는 없다. 하나도.`,
  o:[
    { l:'① 사람 뼈가 없는 이유를 끝까지 따진다.', k:'gaze', dc:24,
      ok:`여기서 사람이 안 죽었을 리는 없다. 배낭이 세 개나 섞여 있다.<br><br>그러니 답은 하나다. 사람은 여기서 안 먹는다. 가져간다.<br>무더기 가장자리에 끌린 자국이 한 방향으로 나 있다. 가져가는 길이다. 그 방향을 지도에 검게 칠하고 반대로 돌았다. 왜 사람만 가져가는지는 칠하지 않았다. 적을 필요도 없이 안 잊힐 것이다.`,
      ng:`따지려고 뼈 하나를 뽑았다.<br><br>무더기가 쏟아졌다. 소리가 길게 났다.<br>소리가 멎기 전에 어둠 저쪽에서 다른 소리가 일었다. 뼈를 버리고 피했다. 뼈들이 왜 저렇게 아슬하게 쌓였는지 그제야 알았다. 방울 대신이다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-25, spirit:-16 } },
    { l:'② 뼈 틈에 낀 짐을 뒤진다.', k:'luck', dc:23,
      ok:`배낭 하나가 뼈 사이에 눌려 있다. 허리춤 주머니가 성하다.<br><br>약초 뭉치가 나왔다. 기름종이에 싸서 마른 그대로다.<br>주머니 주인 몫의 셈은 못 치른다. 대신 이름 모를 뼈 하나를 바로 뉘었다.`,
      ng:`집은 것이 뼈가 아니었다.<br><br>아직 덜 마른 것이었다. 손을 뺐다.<br>무더기 맨 위가 제일 새것이라는 걸 늦게 알았다. 이 무더기는 끝난 자리가 아니라 쓰는 중인 자리다.`,
      win:{ exp:14, item:'약초 뭉치' }, lose:{ spirit:-17, mind:-14 } }
  ] },

{ at:'S', t:'배설물 — 목록',
  x:`길 가운데 무더기가 있다. 마르다 말았다.<br><br>
    학자는 코를 막고 나뭇가지로 갈랐다. 안 녹는 것들이 남는다.<br>
    쇠 단추 넷. 혁대 고리 하나. 부싯돌 하나.<br><br>
    단추 하나는 일행 외투의 단추와 같은 것이다.`,
  o:[
    { l:'① 남은 것들로 목록을 만든다.', k:'gaze', dc:24,
      ok:`단추 넷, 고리 하나. 적어도 네 사람 몫이다.<br><br>삭은 정도가 다 다르다. 한꺼번에가 아니라 하나씩, 사이를 두고.<br>서두르지 않는 사냥이라는 뜻이다. 서두르지 않는 것이 제일 무섭다. 쫓기는 게 아니라 길러지는 것이니까.<br><br>마지막 단추는 아직 녹이 하나도 안 슬었다. 어제나 그제다. 일행의 외투 단추를 전부 안쪽으로 달아 감췄다.`,
      ng:`목록을 만들다 손가락을 베였다.<br><br>안 녹은 것 중에 뼈바늘이 있었다. 피가 한 방울 무더기에 떨어졌다.<br>냄새 위에 냄새를 얹었다. 그 자리를 급히 떴다. 목록은 머릿속으로만 챙겼다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 목록 대신 단추들을 거둬 묻는다.', k:'steady', dc:23,
      ok:`단추와 고리를 주워 흙을 파고 묻었다. 돌을 얹었다.<br><br>이름은 모른다. 자리는 생겼다.<br>일행이 말없이 둘러섰다. 제 외투 단추를 만지작거리는 손이 몇 있었다. 다들 같은 셈을 한 것이다.`,
      ng:`파는데 밑에서 단추가 또 나왔다.<br><br>더 오래된 것들이다. 또 나왔다.<br>세는 걸 멈추고 도로 덮었다. 이 자리는 이미 누가 쓰던 자리였다. 같은 용도로.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-18, mind:-14 } }
  ] },

{ at:'S', t:'허물 — 치수',
  x:`벗은 껍질이 길 가운데 걸려 있다. 속이 비었고 모양은 그대로다.<br><br>
    학자는 치수를 잰다. 머리부터 꼬리까지 이쪽 키의 세 배.<br>
    안쪽에 지난 허물이 한 겹 더 붙어 있다. 두 번 벗었다.<br><br>
    두 겹의 치수가 다르다. 한 번에 반씩 커졌다.`,
  o:[
    { l:'① 두 허물로 지금 크기를 계산한다.', k:'gaze', dc:25, wake:1,
      ok:`벗을 때마다 반씩 큰다. 가장자리 마른 정도로 보아 이 허물은 벗은 지 보름.<br><br>지금 그것은 이 허물의 반이 더 크다. 그 몸은 이 좁은 길로 못 다닌다.<br>그래서 허물이 여기 걸려 있는 것이다. 제가 더는 못 들어오는 길에. 좁은 길만 골라 걸었다. 넓은 길과 만나는 어귀마다 빠르게 지났다.<br><br>책에 없는 생물의 도감이 학자의 수첩에서 시작됐다. 첫 장이 치수다. 치수는 거짓말을 안 한다.`,
      ng:`재는데 허물이 움직였다. 바람은 없었다.<br><br>속을 들여다봤다. 빠져나가다 만 마지막 한 겹이 아직 안쪽에 붙어 마르고 있었다. 그게 오그라들며 당긴 것이다.<br>그렇게 정리했다. 정리한 대로 믿기로 했다. 믿어지기까지 오래 걸렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 허물 속에 들어가 냄새를 가린다.', k:'hide', dc:25,
      doom:{ title:'빈 껍질', what:'허물째 물려 둥지로 끌려갑니다', dc:19, sec:40,
        text:`허물 속은 마른 가죽 냄새뿐이다. 제 냄새가 덮였다.<br><br>발소리가 다가와 바로 옆에서 멎었다. 됐다고 생각했다.<br>허물이 통째로 들렸다. 그것은 제 허물을 거둬 간다. 둥지 바닥에 깔려고.<br><br>허물째 물린 채 끌려간다. 가죽 틈으로 바닥이 흘러간다.`,
        dieText:`길에서 허물이 사라졌다.<br><br>둥지 바닥에 새 깔개가 깔렸다.<br>이번 허물은 속이 차 있다.` },
      ok:`허물 속에서 숨을 죽였다. 발소리가 와서 허물을 한 번 건드리고 지나갔다.<br><br>제 껍질 냄새는 공격하지 않는다. 지난 제 몸을 무는 짐승은 없다.<br>발소리가 멀어지고도 백을 센 다음에 나왔다. 한참 걷고 나서야 숨을 크게 쉬었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'지도 — 줄어드는 길',
  x:`학자는 걸음으로 지도를 그린다. 갈 때 삼백 걸음이었다.<br><br>
    돌아오는 길이 이백아흔이다. 지난번에도 열이 모자랐다.<br>
    길이 줄 리는 없다.<br><br>
    그럼 느는 건 뭔가.`,
  o:[
    { l:'① 걸음 대신 줄을 끊어 다시 잰다.', k:'gaze', dc:25,
      ok:`끈을 열 걸음 길이로 끊어 길을 쟀다. 끈은 서른 번. 길은 그대로였다.<br><br>주는 건 길이 아니라 이쪽 보폭이 는 것이다. 무서우면 걸음이 커진다. 저도 모르게 서두른다.<br>서두르는 걸음은 소리도 커진다. 일행 모두 보폭을 끈에 맞췄다. 걸음 소리가 반으로 줄었다.<br><br>틀린 건 지도가 아니라 다리였다. 학자는 제 몸부터 의심하는 법을 적어 두었다.`,
      ng:`끈으로 재는 사이 등불 기름이 반으로 줄었다.<br><br>시간을 길에 다 썼다.<br>남은 불빛을 아끼느라 어둠에 눈을 혹사했다. 머리가 지끈거렸다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-15, hp:-25 } },
    { l:'② 세기를 멈추고 길목마다 돌을 쌓는다.', k:'steady', dc:23,
      ok:`수는 틀려도 돌은 안 틀린다. 갈림목마다 세 개씩 쌓았다.<br><br>돌아오는 길에 돌들이 그대로 있었다. 수를 안 세니 걸음이 편했다.<br>마지막 돌무더기만 두 걸음 옆에 옮겨져 있었다. 쌓은 모양 그대로. 무언가가 이쪽 표식을 보고 배운다. 그 생각은 혼자만 했다.`,
      ng:`쌓은 돌을 못 찾았다. 흩어져 있었다.<br><br>바람이 없는 데서 돌이 저절로 흩어지지는 않는다.<br>길을 두 번 돌았다. 두 번째 돌 때 흩어진 돌들이 처음과 다르게 흩어져 있었다.`,
      win:{ exp:16, mind:5 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 주기',
  x:`쉬어야 한다. 학자는 쉬기 전에 센다.<br><br>
    아까 멀리서 큰 사냥 소리가 났다. 비명이 짧았고 그다음은 긴 식사 소리였다.<br>
    사냥, 포식, 잠. 순서가 있는 짐승은 시계다.<br><br>
    지금이 포식이면 다음은 잠이다.`,
  o:[
    { l:'① 소리로 그것들의 잠을 계산한다.', k:'gaze', dc:24, wake:1,
      ok:`식사 소리의 길이로 먹이 크기를 쟀다. 큰 먹이였다. 큰 먹이 뒤의 잠은 길다.<br><br>두 시간으로 계산하고 일행을 재웠다. 이쪽은 수를 세며 깨어 있었다.<br>두 시간이 되기 전에 다 깨웠다. 짐을 다 쌌을 때 멀리서 첫 울음이 났다. 일행이 전부 학자를 돌아봤다.<br><br>시계 없이 시간을 소리로 재는 법이 생겼다. 이 바닥의 시계는 남의 배 속이다.`,
      ng:`계산보다 일찍 울음이 났다.<br><br>먹이가 생각보다 작았거나, 그것들이 생각보다 많았거나.<br>덜 잔 일행을 끌고 자리를 떴다. 짐 하나를 두고 왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, hp:-25 } },
    { l:'② 둘씩 등을 맞대는 불침번을 짠다.', k:'bond', dc:23,
      ok:`둘씩 묶고 등을 맞대게 했다. 한 사람은 늘 어둠의 반대쪽을 본다.<br><br>눈 네 개가 쉬는 눈 여섯을 지켰다.<br>밤에 두 번 기척이 왔다가 두 번 그냥 갔다. 보고 있는 먹이는 비싸다.`,
      ng:`순번이 엉켰다. 빈 시간이 한 식경 생겼다.<br><br>그 시간에 등불 하나가 사라졌다. 소리도 없이.<br>물고 간 자국만 남았다. 불을 무는 짐승은 불이 안 무섭다는 걸 아는 짐승이다.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-16, mind:-14 } },
    { l:'③ 눕기 전에 둘레를 한 바퀴 돈다.', k:'luck', dc:23,
      ok:`반 바퀴쯤에서 바위 틈에 고인 물을 찾았다.<br><br>위에서 배어 나온 물이다. 맑다.<br>물통을 채우고 마저 돌았다. 남은 반 바퀴는 아무 일 없었다. 아무 일 없는 반 바퀴가 그날 제일 큰 소득이었다.`,
      ng:`한 바퀴를 다 돌고 보니 이슬 내린 풀이 쓸려 있었다.<br><br>쉬는 자리에서 열 걸음 자리다. 자국이 새것이다.<br>자리를 옮겼다. 옮긴 자리에서 다들 설쳤다. 안 옮겼으면 더 설쳤을 것이다.`,
      win:{ exp:13, item:'맑은 물' }, lose:{ spirit:-15, mind:-14 } }
  ] },

{ at:'S', t:'긁힌 자국 — 더 위',
  x:`바위벽에 발톱 자국이 줄줄이 나 있다. 사냥꾼들의 높이다.<br><br>
    그 위에 자국이 또 있다. 네 줄. 폭이 손바닥 넷.<br>
    아래 작은 자국들은 그 네 줄 밑에서 전부 끊겨 있다.<br><br>
    그것들도 피하는 것이 있다.`,
  o:[
    { l:'① 작은 자국들이 도는 길을 읽는다.', k:'gaze', dc:26,
      ok:`작은 자국들은 네 줄 자국을 크게 돌아서 다닌다. 도는 길이 정해져 있다.<br><br>그 우회로는 사냥꾼들에게 안전한 길이다. 큰 것에게서. 그리고 우회로를 다니는 동안 그것들은 사냥을 안 한다. 저도 지나가는 중이니까.<br>우회로를 따라 걸었다. 어귀에 뜯다 만 먹이가 놓여 있었다. 흘린 게 아니라 놓고 간 것처럼 가지런했다. 공물이라는 말은 수첩에 안 적었다.`,
      ng:`네 줄 자국의 폭을 재다가 고개를 들었다.<br><br>자국이 벽에서 끝나지 않는다. 천장으로 이어진다.<br>그 폭 그대로. 위를 보지 말 걸 그랬다. 그날 밤 천장 있는 데서는 잠이 안 왔다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-19, mind:-15 } },
    { l:'② 네 줄 자국의 길을 지름길로 쓴다.', k:'sense', dc:24,
      doom:{ title:'네 줄 자국', what:'큰 것에게 채여 어둠 위로 끌려 올라갑니다', dc:20, sec:40,
        text:`큰 것의 길은 곧고 빨랐다. 곧은 길에는 주인이 있다.<br><br>바람이 위에서 내려왔다. 바람에 온기가 섞여 있다.<br>몸이 들린다. 등에 폭이 손바닥 넷인 것이 닿는다.<br><br>길은 그대로 곧은데 걷는 발만 바닥에서 떨어져 있다.`,
        dieText:`곧은 길은 그대로 곧다.<br><br>벽의 작은 자국들이 그날부터 조금 더 아래에서 끊긴다.<br>피해야 할 것이 하나 더 늘어서.` },
      ok:`길은 쓰되 때를 골랐다. 자국에 앉은 먼지가 도톰한 쪽, 지나간 지 오랜 때다.<br><br>가장자리로 붙어 빠르게 지났다. 지름길이 맞았다. 반나절 길이 한 식경으로 줄었다.<br>길 끝에서 돌아보니 어귀에 사냥꾼 둘이 서서 이쪽을 보고만 있었다. 따라 들어오지 않았다. 거기부터는 저들 땅이 아니라서.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S1', t:'관측 일지 — 착륙 이후',
  x:`관측실 책상에 일지가 펼쳐져 있다.<br><br>
    착륙 전 기록은 기계로 찍은 듯 반듯하다. 착륙 후는 손글씨다.<br>
    날이 갈수록 줄이 짧아진다. 마지막 몇 장은 하루 한 줄이다.<br><br>
    「오늘도 문은 버텼다.」`,
  o:[
    { l:'① 서른아홉 날을 통째로 읽는다.', k:'gaze', dc:24, wake:1,
      ok:`착륙에서 마지막 장까지 서른아홉 날. 그들이 알아낸 것이 흩어져 적혀 있다.<br><br>그것은 유리를 못 긁는다. 쇠문은 녹여도 관측창은 못 뚫었다. 잘 때는 문 앞이 아니라 창가가 낫다.<br>환풍구를 등지고 앉지 말 것. 급한 글씨일수록 같은 말이 반복된다. 반복되는 말이 값진 말이다.<br><br>죽은 사람들의 서른아홉 날을 하룻밤에 읽어 제 것으로 만들었다. 기록은 두 번 산다. 두 번째는 학자의 몫이다.`,
      ng:`마지막 장 다음이 찢겨 있다.<br><br>찢은 결이 바깥쪽이다. 안에서 찢어 갔다.<br>마흔째 날에 무엇이 적혔길래 가져갔나. 누가. 그 두 물음이 번갈아 잠을 깨웠다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 요점만 베껴 일행에게 나눈다.', k:'fix', dc:23,
      ok:`세 줄로 줄였다. 불은 하나. 유리 뒤에서 잔다. 환풍구를 등지지 않는다.<br><br>한 사람에 한 줄씩 외우게 했다. 다섯이 외우면 다섯 번 산다.<br>그날 밤 각자 제 줄을 중얼거리며 자리를 잡는 소리가 들렸다. 일지 주인들이 들었으면 덜 억울했을 소리다.`,
      ng:`베끼다 한 줄을 빠뜨렸다. 하필 환풍구 줄이다.<br><br>일행 하나가 환풍구를 등지고 앉았다. 등 뒤 덮개가 소리 없이 열렸다.<br>끌어낸 건 순전히 운이었다. 어깨에 긴 생채기가 났다. 그날로 세 줄이 네 줄이 됐다. 「베낀 것은 두 번 센다.」`,
      win:{ exp:16, mind:5 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'표본 선반 — 빠진 번호',
  x:`선반 가득 유리병이다. 번호표가 붙어 있다. 일에서 육십까지.<br><br>
    깨진 병과 성한 병이 섞여 있다. 학자는 셌다.<br>
    깨진 것 열하나. 그런데 빈자리는 열셋이다.<br><br>
    둘이 모자란다.`,
  o:[
    { l:'① 모자란 둘의 행방을 셈으로 좁힌다.', k:'gaze', dc:25,
      ok:`깨지지 않고 사라진 병이 둘. 병째 옮겨졌다.<br><br>병째 옮길 수 있는 건 손이 있는 것뿐이다. 선반 아래 먼지에 길고 가는 손가락 자국이 찍혀 있다.<br>그것들은 마음에 드는 것을 둥지로 가져간다. 빠진 번호는 십칠과 십팔. 번호표 대장을 보니 둘 다 「알 — 미부화」다.<br><br>제 종족의 알을 찾아간 것이다. 옮겨 간 방향이 먼지에 남아 있다. 그 방향을 지도에서 지웠다. 둥지 방향이니까.`,
      ng:`세는 사이 성한 병 하나에서 금 가는 소리가 났다.<br><br>금이 안에서 바깥으로 번진다. 민 것이다. 안에서.<br>선반을 등지고 물러났다. 셈은 끝까지 못 맞췄다. 내일이면 깨진 것이 열둘이 될 것이다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-17, mind:-15 } },
    { l:'② 잠긴 보관장을 뒤진다.', k:'luck', dc:23,
      ok:`보관장 안에 연구용 건조 약초 상자가 줄지어 있다.<br><br>라벨이 붙어 있다. 「진정 · 지혈」. 기름종이에 싸인 뭉치가 성하다.<br>하나를 챙겼다. 연구자들은 꼼꼼했다. 꼼꼼한 사람들의 유산은 쓸모가 있다.`,
      ng:`장문이 뻑뻑했다. 당기자 경첩이 길게 울었다.<br><br>복도 끝 어둠이 한 번 출렁였다.<br>장을 그대로 두고 실험대 밑에 숨었다. 한 식경을 숨어 있었다. 빈손으로.`,
      win:{ exp:14, item:'약초 뭉치' }, lose:{ hp:-25, spirit:-15 } }
  ] },

{ at:'S1', t:'급여표 — 줄어드는 수',
  x:`사육 구역 벽에 급여표가 붙어 있다. 날짜와 먹이 양.<br><br>
    양이 날마다 준다. 그러다 영이 된다.<br>
    영 다음 날 기록은 이렇다. 「급여 불필요」.<br><br>
    그다음 날은 이렇다. 「급여 금지」.`,
  o:[
    { l:'① 불필요와 금지 사이의 이틀을 읽는다.', k:'gaze', dc:24,
      ok:`불필요는 안 먹어도 산다는 말이고 금지는 주러 가면 안 된다는 말이다.<br><br>그 사이 이틀 동안 무슨 일이 있었다. 기록한 사람의 글씨가 이틀 사이에 바뀌어 있다. 첫 기록자는 더 못 적게 된 것이다.<br>표 귀퉁이에 급여 시각이 적혀 있다. 그것은 아직 그 시각을 기억한다. 그 시각이면 급여구 앞에서 기다린다는 뜻이다. 시각을 피해 구역 앞을 지났다. 급여구 안쪽에서 숨소리가 시계처럼 규칙적으로 났다.`,
      ng:`표를 읽다가 귀퉁이의 시각을 봤다. 지금이다.<br><br>복도 끝 급여구 쪽에서 철컥, 하는 소리가 났다.<br>기다리던 것이 문을 민 소리다. 들고 있던 등불을 끄고 반대쪽으로 걸었다. 빠르게, 그러나 뛰지는 않고.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 사육 구역 안을 질러간다.', k:'sense', dc:25,
      doom:{ title:'급여 시간', what:'급여구 안쪽으로 물려 끌려갑니다', dc:19, sec:45,
        text:`구역 안은 조용했다. 조용한 건 빈 게 아니라 기다리는 것이었다.<br><br>등 뒤에서 급여구가 철컥 열렸다.<br>발목이 당겨진다. 바닥에 손톱자국을 내며 끌려간다. 급여구 쪽으로.<br><br>오늘 양은 충분하다.`,
        dieText:`급여표에 줄이 하나 늘었다.<br><br>날짜는 오늘. 양은 「충분」.<br>글씨는 사람 것이 아니다.` },
      ok:`바닥의 배수 홈을 따라 걸었다. 홈은 소리를 아래로 삼킨다.<br><br>구역을 다 질렀다. 시간을 반나절 벌었다.<br>나오면서 돌아보니 급여구 안쪽 어둠에서 눈이 이쪽을 끝까지 따라왔다. 열리지는 않았다. 배가 덜 고팠을 뿐이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'녹은 바닥 — 방울 간격',
  x:`복도 바닥에 구멍이 줄지어 났다. 가장자리가 녹아 있다.<br><br>
    피가 돌을 녹이는 생물. 책에는 없다. 이제는 있다. 학자의 수첩에.<br>
    구멍 깊이가 다 다르다. 방울 크기와 떨어진 높이의 문제다.<br><br>
    학자는 그런 문제를 풀 줄 안다.`,
  o:[
    { l:'① 방울 간격으로 그것의 길을 복원한다.', k:'gaze', dc:25,
      ok:`간격이 넓고 방울이 크다. 높은 데서, 빠르게 움직이며 흘렸다.<br><br>천장을 타고 달아나며 흘린 피다. 다쳤다는 뜻이다.<br>다친 짐승이 제일 위험하다. 핏길이 향한 쪽을 버리고 반대로 돌았다. 돌아 나오는데 핏길 끝 쪽에서 쇠가 천천히 녹는 소리가 아직 나고 있었다. 피가 멎지 않은 것이다.`,
      ng:`간격을 재느라 쭈그린 사이 위에서 한 방울이 떨어졌다.<br><br>소매 끝이 하얀 연기를 냈다.<br>외투를 벗어 던졌다. 천장에 아직 있는 것이다. 다친 채로, 조용히.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, spirit:-15 } },
    { l:'② 구멍 사이로 일행을 건넨다.', k:'steady', dc:23,
      ok:`디딜 자리에 번호를 매겨 하나씩 불러 줬다.<br><br>여섯이 다 건넜다. 신 바닥 하나 안 녹이고.<br>건너고 나서 구멍들을 돌아봤다. 삭은 가장자리가 흰 꽃처럼 피어 있었다. 그런 걸 곱다고 느낀 제가 조금 무서웠다.`,
      ng:`하나가 헛디뎠다. 발이 구멍에 빠졌다.<br><br>구멍 밑이 비어 있었다. 아래층까지 녹은 것이다.<br>팔을 붙들어 올렸다. 신 바닥이 반쯤 사라져 있었다. 녹은 게 바닥이라 다행이라는 말은 아무도 안 했다.`,
      win:{ exp:16, hp:5 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S1', t:'해부도 — 끊긴 선',
  x:`연구실 벽에 손으로 그린 해부도가 핀으로 꽂혀 있다.<br><br>
    그 생물의 속이다. 심장이 둘. 피 주머니가 따로 있다.<br>
    마지막 장은 머리다. 선이 중간에 끊겨 있다. 그리다 말았다.<br><br>
    책상 밑에 마른 얼룩이 넓다.`,
  o:[
    { l:'① 앞 장의 규칙으로 끊긴 선을 잇는다.', k:'gaze', dc:25, wake:1,
      ok:`앞 장들은 좌우가 대칭이다. 끊긴 선을 대칭으로 이었다.<br><br>목 뒤에 둘째 심장이 온다. 겉가죽이 제일 얇은 자리도 거기다. 그림 귀퉁이에 작게 적혀 있다. 「창은 여기」.<br>일행의 창잡이 손등에 그 자리를 그려 줬다. 창잡이가 손등을 오래 들여다봤다.<br><br>남의 미완성을 완성하는 법이 생겼다. 아는 것 열로 모르는 것 서른을 메운다. 그리다 만 사람 몫까지 그리는 것이 학자의 일이다.`,
      ng:`선을 잇다 보니 머리 안에 빈 방이 하나 더 그려졌다.<br><br>뇌 옆의 빈 공간. 무엇이 들어앉는 자리인지 앞 장 어디에도 없다.<br>그리다 만 게 아니라 그리기 싫었던 것이다. 책상 밑 얼룩이 그 답인 것 같아 더 묻지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 그림을 전부 떼어 챙긴다.', k:'break', dc:23,
      ok:`핀을 하나씩 뽑고 그림을 말아 품에 넣었다.<br><br>종이는 가볍고 아는 것은 무겁다. 이 두루마리가 이 건물에서 제일 비싼 물건이다.<br>연구자의 이름이 귀퉁이에 있었다. 수첩에 옮겨 적었다. 그린 사람은 남아야 한다.`,
      ng:`마지막 핀이 안 빠졌다. 당기자 종이가 찢어졌다.<br><br>하필 급소를 그린 장이다. 반만 남았다.<br>반쪽 지식은 반쪽 무기다. 나머지 반은 이제 몸으로 배워야 한다.`,
      win:{ exp:15, mind:5 }, lose:{ mind:-14, hp:-25 } }
  ] },

{ at:'S1', t:'배관도 — 없는 관',
  x:`벽에 환풍 배관도가 걸려 있다. 관이 거미줄처럼 얽혀 있다.<br><br>
    학자는 도면과 실물을 대조한다. 그게 버릇이다.<br>
    실물에 관이 하나 더 있다. 도면에 없는 관이다.<br><br>
    이음매가 용접이 아니다. 녹았다 굳은 자국이다.`,
  o:[
    { l:'① 없는 관이 지나는 방을 전부 짚는다.', k:'gaze', dc:24,
      ok:`없는 관은 사람이 낸 길이 아니다. 그것들이 녹여 뚫고 길들인 길이다.<br><br>관의 기울기를 따라 도면 위에 선을 그었다. 그 선이 지나는 방이 일곱.<br>그 일곱 방을 피해서 경로를 다시 짰다. 도면째 일행에게 넘겼다. 종이에 그어진 선 하나가 일곱 방의 천장을 미리 보여 준 셈이다.`,
      ng:`대조하는 사이 그 관에서 바람이 나왔다.<br><br>바람이 아니었다. 간격이 있었다. 들숨과 날숨.<br>관 속에서 자는 것이다. 도면을 말아 쥐고 그 방을 나왔다. 발끝으로.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 좁은 관으로 질러간다.', k:'hide', dc:25,
      doom:{ title:'도면에 없는 관', what:'관 안쪽 어둠으로 끌려 들어갑니다', dc:20, sec:40,
        text:`반쯤 기었을 때 관이 울렸다. 뒤가 아니라 앞에서.<br><br>마주 온다. 돌아서기엔 좁다.<br>뒤로 물러나는데 발목이 잡혔다. 뒤에도 있었다. 둘이었다.<br><br>아래로 끌려 내려간다. 관이 미끄럼틀처럼 기울어 있다. 기울기의 끝은 도면에 없다.`,
        dieText:`관은 다시 조용하다.<br><br>도면에 없는 관은 이제 한 사람 몫만큼 덜 비어 있다.<br>도면은 끝내 고쳐지지 않았다.` },
      ok:`들기 전에 돌멩이를 굴려 넣었다. 소리가 끝까지 굴러갔다. 마중 나오는 소리는 없었다.<br><br>빈 시간이다. 숨 한 번에 다섯 발씩 나아갔다.<br>빠져나와서 도면의 그 관 위에 연필로 적었다. 「한 번은 비었다. 두 번은 모른다.」`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S1', t:'어미 방 — 알의 나선',
  x:`가장 깊은 방이다. 따뜻하다. 바닥 가득 알이다.<br><br>
    아무렇게나 놓인 게 아니다. 가운데에서 바깥으로 나선을 그린다.<br>
    학자는 눈으로 센다. 한 바퀴에 몇 개씩 느는지.<br><br>
    바깥 줄에 빈자리가 둘 있다.`,
  o:[
    { l:'① 나선의 규칙을 읽는다.', k:'gaze', dc:26,
      ok:`안쪽이 오래고 바깥이 새것이다. 빈자리 둘은 바깥 줄. 갓 나간 것들이다.<br><br>갓 나간 것은 어리고, 어린 것은 겁이 없고, 겁 없는 것은 돌아온다. 먹이를 물고. 들어온 길로.<br>들어온 길을 버리고 벽을 따라 돌았다. 지나는데 목덜미에 물방울이 떨어졌다. 물이 아니었다. 데웠다.<br><br>위를 보지 않았다. 어미는 알 위에 있다. 세는 눈을 어미는 안다. 세기를 멈추고 걷기만 했다.`,
      ng:`세는 사이 알 하나가 이쪽으로 기울었다.<br><br>안에서 민 것이다.<br>그 순간 나선 전체가 한 번 크게 일렁였다. 알들이 아니라 바닥이. 바닥이 아니라, 방 전체가 숨을 쉰 것이다. 세던 수를 전부 잊었다.`,
      win:{ exp:25, dream:4 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 알을 보지 않고 벽만 보고 물러난다.', k:'steady', dc:24,
      ok:`새끼를 세는 눈을 어미는 안다. 눈을 내리깔고 벽만 봤다.<br><br>벽을 짚으며 걸었다. 방을 나올 때까지 위쪽 숨소리의 간격이 변하지 않았다.<br>그게 성공이라는 뜻이다. 문턱을 넘고 나서야 무릎이 떨렸다.`,
      ng:`반쯤에서 발밑 껍데기가 바스락했다.<br><br>위쪽 숨이 멎었다.<br>멎은 숨이 다시 쉬어질 때까지가 평생 같았다. 다시 쉬어지자마자 뛰었다. 문턱에 정강이를 찧은 줄도 몰랐다.`,
      win:{ exp:18, spirit:6 }, lose:{ hp:-30, spirit:-18 } },
    { l:'③ 빈자리의 껍데기 조각을 표본으로 집는다.', k:'luck', dc:25,
      doom:{ title:'어미의 눈', what:'어미에게 들려 나선 가운데로 끌려갑니다', dc:20, sec:35,
        text:`조각에 손이 닿는 순간 방의 온기가 움직였다.<br><br>온기가 숨이었다. 위에서.<br>몸이 들린다. 알들 위를 지나 나선 가운데로 옮겨진다.<br><br>빈자리 중 하나에 내려놓인다. 맞춤하다.`,
        dieText:`나선의 빈자리가 하나 줄었다.<br><br>배열은 다시 규칙대로다.<br>학자가 좋아하던 규칙대로.` },
      ok:`집지 않았다. 눈으로만 쟀다.<br><br>껍질 두께, 결, 안쪽의 마른 막. 전부 머리에 넣었다.<br>빈손으로 나왔다. 표본은 손에 드는 게 아니라 눈에 드는 것이다. 여기서는.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'S2', t:'양치 밭 — 돌에서 본 잎',
  x:`무릎까지 물이다. 양치가 어깨 높이로 우거졌다.<br><br>
    학자는 이 잎을 안다. 돌에 눌린 화석으로. 책장은 돌이었다.<br>
    그 잎이 지금 눈앞에서 젖은 채 흔들린다.<br><br>
    억만 년을 거슬러 온 게 이쪽인지 저쪽인지 잠깐 헷갈렸다.`,
  o:[
    { l:'① 돌의 기억으로 먹을 순을 고른다.', k:'gaze', dc:23,
      ok:`화석으로 본 종에는 독이 없었다. 짐승이 뜯은 자국으로 겹쳐 확인했다.<br><br>뜯긴 쪽 어린 순을 한 아름 땄다. 고사리 순 비슷하게 말리면 먹는다.<br>따다 보니 뜯긴 자국 하나가 이빨이 아니었다. 다섯 손가락이다. 앞서 누가 같은 셈을 하고 갔다. 살아서 갔기를.`,
      ng:`비슷한 순이 둘이었다. 하나를 씹어 봤다.<br><br>혀가 저렸다. 뱉었다.<br>저린 것이 목까지 내려갔다가 한참 만에 가셨다. 억만 년 사이에 독이 생긴 종도 있는 것이다. 책은 돌에서 멈췄고 풀은 계속 자랐다.`,
      win:{ exp:18, item:'산나물' }, lose:{ hp:-25, mind:-14 } },
    { l:'② 뿌리 둔덕을 디뎌 밭을 가로지른다.', k:'sense', dc:24,
      ok:`물 밑 뿌리 둔덕이 징검다리다. 발끝으로 더듬어 건넜다.<br><br>가운데 둔덕 옆에 버섯이 무더기로 올라와 있었다. 썩은 나무 둥치에.<br>한 줌 땄다. 젖지 않은 것만. 밭을 다 건널 때까지 물은 한 번도 일렁이지 않았다.`,
      ng:`둔덕인 줄 알고 디딘 것이 천천히 가라앉았다.<br><br>둔덕이 아니라 등이었다.<br>물이 크게 일렁였다. 남은 거리를 반쯤 헤엄치듯 건넜다. 뒤에서 무엇이 돌아눕는 소리가 났다. 일어나지는 않았다.`,
      win:{ exp:15, item:'야생 버섯' }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S2', t:'울타리 — 전압 일지',
  x:`울타리 기둥의 철함에 일지가 들어 있다. 구간별 전압 기록이다.<br><br>
    숫자가 구간마다 다르다. 몇 구간은 영이다.<br>
    영 옆에 연필로 눌러쓴 글씨가 있다.<br><br>
    「9구간 — 그것들이 안다.」`,
  o:[
    { l:'① 죽은 구간이 번진 순서를 읽는다.', k:'gaze', dc:24,
      ok:`영이 된 날짜를 늘어놓으니 순서가 보인다. 구 구간에서 시작해 양옆으로.<br><br>그것들은 한 구간을 죽이고 다음 구간을 시험한다. 순서대로.<br>다음 죽을 구간이 계산됐다. 십일 구간. 그쪽을 버리고 산 구간 쪽으로 길을 잡았다. 지나며 보니 십일 구간 울타리 밖에 나무 하나가 벌써 반쯤 눕혀져 있었다. 계산이 맞는 건 하나도 안 기뻤다.`,
      ng:`일지의 마지막 날짜가 오래전이다.<br><br>그 뒤로 몇 구간이 더 죽었는지 기록이 없다.<br>산 구간이라 믿은 데서 아무 소리도 안 났다. 손등을 대 보다가 녹슨 가시에 긁혔다. 전기는 없었다. 오래전부터.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 산 구간을 따라 일행의 동선을 짠다.', k:'fix', dc:23,
      ok:`웅웅대는 소리가 나는 구간만 골라 이었다. 울타리를 오른손에 두고 걷는 길이다.<br><br>일행이 그 선을 따라 움직였다.<br>울타리 너머에서 셋이 나란히 따라 걸었다. 풀 흔들리는 간격이 일정했다. 들어오지는 못했다. 아직 산 구간이라서.`,
      ng:`동선이 한 군데 꼬였다. 하나가 죽은 구간 앞을 지났다.<br><br>울타리 틈으로 발톱이 들어왔다.<br>외투 자락이 네 갈래로 찢겼다. 살은 안 닿았다. 한 뼘 차이였다.`,
      win:{ exp:16, hp:5 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S2', t:'말뚝 — 빠진 번호',
  x:`구획 말뚝이 줄지어 섰다. 일, 이, 삼.<br><br>
    칠 다음이 구다. 팔이 없다.<br>
    학자는 빠진 수를 못 지나친다. 안내판 지도를 봤다.<br><br>
    팔 구획 자리가 긁혀 지워져 있다. 칼로.`,
  o:[
    { l:'① 말뚝 간격으로 8구획을 복원한다.', k:'gaze', dc:25,
      ok:`칠과 구 사이가 다른 간격의 두 배다. 팔 구획은 넓다.<br><br>지운 건 사람이다. 들어가지 말라는 게 아니라 찾지 말라는 뜻이다. 숨긴 것이 있다.<br>구획 가장자리를 더듬어 반쯤 묻힌 창고를 찾았다. 급이용 비축 창고다. 기름종이에 싼 육포가 선반째 남아 있었다.<br><br>문 안쪽에 긁힌 자국이 있었다. 안에서 긁은 자국. 그건 못 본 걸로 했다.`,
      ng:`간격 계산이 어긋났다. 팔 구획 깊숙이 들어섰다.<br><br>울타리가 이상했다. 가시가 안쪽을 향해 있다.<br>못 나가게 하는 울타리다. 가두는 구획이었다. 온 길을 되밟아 나왔다. 빠르게.`,
      win:{ exp:20, item:'말린 고기' }, lose:{ spirit:-17, mind:-15 } },
    { l:'② 9구획 사육사 함을 연다.', k:'luck', dc:23,
      ok:`함 안에 소금 포대가 있다. 짐승 핥으라고 둔 덩이소금이다.<br><br>주먹만 한 덩이를 하나 챙겼다.<br>소금은 억만 년 전에도 소금이다. 변하지 않는 것이 하나라도 있어 다행이다.`,
      ng:`함 바닥이 삭아 있었다. 드는 순간 쏟아졌다.<br><br>쇳소리가 벌판을 건너갔다.<br>먼 데서 풀 갈라지는 소리가 답했다. 챙기지 못하고 자리를 떴다.`,
      win:{ exp:13, item:'소금 덩이' }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S2', t:'발톱 자국 — 높이',
  x:`울타리 기둥에 발톱 자국이 켜켜이 나 있다.<br><br>
    아래 자국은 거멓게 삭았고 위로 갈수록 새것이다.<br>
    학자는 높이를 쟀다. 해마다 한 뼘씩 올라왔다.<br><br>
    맨 위 자국은 울타리 꼭대기다. 그 위로는 자국이 없다. 필요가 없어진 것이다.`,
  o:[
    { l:'① 자국의 나이테를 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`자국은 시험의 기록이다. 해마다 더 높이 뛰었고 올해 울타리를 이겼다.<br><br>꼭대기 자국 아래 땅을 봤다. 안쪽 풀이 길처럼 다져져 있다. 드나든 지 오래라는 뜻이다.<br>울타리는 이제 벽이 아니라 길목이다. 넘는 자리가 정해져 있다는 것. 그 자리만 피하면 나머지 울타리는 아직 벽이다. 다져진 길에서 먼 쪽으로 붙어 걸었다.<br><br>벽 하나에서 십 년 치 사냥 일지를 읽었다. 높이로 세월을 읽는 눈이 생겼다.`,
      ng:`맨 위 자국에 손끝이 닿았다. 긁힌 속이 아직 생나무 색이다.<br><br>오늘 자국이다.<br>위를 올려다봤다. 꼭대기 너머는 보이지 않았다. 보이지 않는 게 본 것보다 오래 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-19, hp:-26 } },
    { l:'② 울타리에서 다섯 걸음 띄워 걷게 한다.', k:'steady', dc:24,
      ok:`울타리를 믿지 않기로 했다. 안쪽에서도 다섯 걸음 띄웠다.<br><br>그날 밤 울타리 꼭대기에 그림자 둘이 앉았다. 내려오지는 않았다.<br>이쪽을 내려다보기만 했다. 다섯 걸음이 있어 닿지 않는 거리였다. 거리는 학자가 잰 것이다.`,
      ng:`하나가 지쳐서 울타리에 기댔다.<br><br>너머에서 기다리던 숨이 훅 끼쳤다.<br>머리카락 한 줌이 울타리 틈으로 딸려 들어갔다. 비명에 그쪽이 더 놀라 물러났다. 어린 것이었다. 어린 것도 그 크기였다.`,
      win:{ exp:16, spirit:5 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'물웅덩이 — 서른 걸음',
  x:`큰 웅덩이가 벌판에 줄지어 있다. 간격이 일정하다.<br><br>
    웅덩이가 아니다. 발자국이다.<br>
    학자는 간격을 쟀다. 서른 걸음.<br><br>
    웅덩이 물이 가늘게 떨린다. 떨렸다가, 멎었다가.`,
  o:[
    { l:'① 떨림으로 거리와 때를 계산한다.', k:'gaze', dc:26, wake:1,
      ok:`떨림의 세기와 간격으로 거리를 쟀다. 멀어지는 중이다.<br><br>그리고 이 발자국 줄은 물가로 가는 길이다. 짐승은 마시는 때가 정해져 있다. 하루 두 번.<br>다음 떨림이 돌아올 때까지의 틈을 계산했다. 그 틈에 전원이 발자국 줄을 건넜다. 마지막 사람이 건널 때 물이 다시 떨리기 시작했다. 계산 안에서.<br><br>땅을 종이로, 떨림을 글자로 읽는 법이 생겼다. 이 벌판 전체가 한 권이다.`,
      ng:`계산하는 중에 떨림이 갑자기 커졌다.<br><br>멀어지던 것이 방향을 돌렸다. 계산에 없던 일이다.<br>뛰었다. 웅덩이 하나에 빠져 허리까지 젖었다. 발자국 속에 빠진 것이다. 그 생각이 제일 오래 남았다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 떨림이 멎은 틈에 물을 건넌다.', k:'evade', dc:25,
      doom:{ title:'서른 걸음', what:'큰 것에게 물려 물 밑으로 끌려 들어갑니다', dc:20, sec:35,
        text:`물 가운데서 떨림이 다시 왔다. 센 것이 아니라 가까웠다.<br><br>물이 산처럼 일어섰다.<br>물째 물렸다. 아래로. 빛이 수면 저쪽으로 멀어진다.<br><br>서른 걸음짜리가 물속에서는 소리가 없다는 걸 아무도 안 적어 놨다.`,
        dieText:`물이 가라앉았다.<br><br>벌판에 웅덩이가 하나 늘었다.<br>간격은 서른 걸음. 줄에 맞춰서.` },
      ok:`건너는 동안 한 번도 멈추지 않았다. 멈추는 발이 제일 큰 소리를 낸다.<br><br>건너고 나서야 물을 돌아봤다.<br>긴 그림자가 방금 이쪽이 디딘 자리 밑을 천천히 지나가고 있었다. 물 위로는 잔주름 하나 없이.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'민물 — 비늘 책장',
  x:`잠긴 양치 사이에 물 맑은 목이 있다. 고기 떼가 지난다.<br><br>
    학자는 저 비늘을 돌로만 봤다. 지층에 눌린 화석으로.<br>
    그게 지금 헤엄친다.<br><br>
    침이 고였다. 학자로서도, 배고픈 사람으로서도.`,
  o:[
    { l:'① 물길을 읽어 좁은 목으로 몬다.', k:'gaze', dc:23,
      ok:`물풀이 눕는 방향으로 물길을 읽었다. 고기는 물길을 거슬러 좁은 목으로 모인다.<br><br>목을 지키고 섰다가 두 손으로 두 마리를 건졌다.<br>비늘 한 장을 벗겨 수첩에 붙였다. 표본과 저녁을 한 번에 얻는 날은 드물다.`,
      ng:`몰다가 물을 너무 휘저었다.<br><br>고기 대신 긴 것이 물풀 사이로 미끄러져 왔다.<br>물에서 뛰쳐나왔다. 정강이에 물풀이 감겨 있었다. 물풀이기를 바랐다.`,
      win:{ exp:15, item:'민물고기' }, lose:{ hp:-25, spirit:-15 } },
    { l:'② 사육사의 낡은 통발을 손본다.', k:'luck', dc:23,
      ok:`물가 말뚝에 통발이 매여 있었다. 삭은 데를 풀줄기로 기웠다.<br><br>하룻밤 담가 두니 아침에 한 마리 들어 있었다.<br>옛 도구가 아직 일한다. 만든 사람은 없는데.`,
      ng:`통발이 손안에서 삭아 터졌다.<br><br>댓가지에 손바닥이 긁혔다. 피가 물에 번졌다.<br>이 물에 피를 풀면 안 된다. 그건 책 없이도 안다. 물가에서 빠르게 물러났다.`,
      win:{ exp:13, item:'민물고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 고기 대신 물만 긷는다.', k:'steady', dc:24,
      ok:`흐르는 목 위쪽에서 물을 길었다. 맑은 물이 한 통.<br><br>긷는데 고기 떼가 한순간에 한 방향으로 쏠렸다. 손을 멈추고 같이 멎었다.<br>큰 것이 벌판 저쪽을 지나갔다. 고기가 사람보다 먼저 안다. 그 뒤로 고기 떼를 시계로 썼다.`,
      ng:`긷다 보니 물에 고기가 한 마리도 없었다. 언제부터인지 모른다.<br><br>신호를 놓친 것이다.<br>물가 건너편에서 숨 하나가 이쪽을 보고 있었다. 물통을 들고 뒷걸음으로 물러났다. 반 통은 쏟았다.`,
      win:{ exp:16, item:'맑은 물' }, lose:{ spirit:-17, mind:-14 } }
  ] },

{ at:'S2', t:'승강기 — 낡은 조감도',
  x:`안내판에 정원 조감도가 남아 있다. 한가운데 승강기 표시.<br><br>
    경로가 셋 그려져 있다. 그 아래 글귀. 「비상 시 승강기는 최하층에 머묾」.<br>
    조감도는 낡았다. 그려진 뒤로 물이 번졌다.<br><br>
    지도의 땅 절반이 지금은 물밑이다.`,
  o:[
    { l:'① 조감도를 지금 지형으로 고쳐 읽는다.', k:'gaze', dc:26, wake:1,
      ok:`물에 잠긴 구역을 머릿속에서 지우고 다시 그렸다.<br><br>세 경로 중 둘이 물밑으로 사라졌다. 남은 하나는 급이 창고 지붕을 타고 넘는 길이다.<br>지붕 길로 일행을 이끌었다. 마지막 지붕에서 승강기 쇠문이 보였다. 조감도에 그려진 그대로, 그려지지 않은 물 한가운데에.<br><br>지도는 믿는 것이 아니라 고치는 것이다. 틀린 지도를 고쳐 읽는 눈이 생겼다. 그 눈이면 백지도 지도다.`,
      ng:`물 번진 자리를 잘못 지웠다. 살아 있는 길 하나를 버렸다.<br><br>크게 돌았다. 도는 동안 등 뒤 양치가 두 번 갈라졌다.<br>두 번 다 돌아봤고 두 번 다 아무것도 없었다. 양치만 천천히 도로 섰다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 호출 전선을 이어 승강기를 부른다.', k:'break', dc:25,
      doom:{ title:'호출 종', what:'종소리에 모인 것들에게 물려 수풀로 끌려갑니다', dc:19, sec:40,
        text:`전선을 이었다. 종이 울렸다. 정원 전체에.<br><br>승강기보다 그것들이 빨랐다. 사방의 양치가 일제히 눕는다.<br>발목이, 어깨가, 거의 동시에 물린다. 셋이 한꺼번에.<br><br>수풀 속으로 끌려 들어간다. 승강기 쇠문이 보이는 자리에서.`,
        dieText:`종은 한참 더 울었다.<br><br>승강기가 내려왔다. 비어 있다.<br>문이 열렸다 닫혔다. 탈 사람이 없어서.` },
      ok:`전선을 잇기 전에 종 망치를 천으로 감았다.<br><br>종은 울지 않고 떨기만 했다. 떨림만으로도 신호는 간다.<br>승강기가 내려오는 소리가 정원에서 제일 조용한 소리였다. 쇠문이 열렸다. 안의 먼지가 수십 년 치였다.`,
      win:{ exp:24, dream:4 } }
  ] }
]);
// ── 주술사 (마력)
kJob('hexer', 'S', [

{ at:'S', t:'핏자국 — 흘린 길',
  x:`일행 하나가 다쳤다. 걸을 때마다 핏방울이 떨어진다.<br><br>
    뒤에서 그걸 읽으며 오는 것이 있다. 간격이 줄고 있다.<br>
    주술사는 안다. 피는 이름이다.<br><br>
    이름이 길에 적히고 있다.`,
  o:[
    { l:'① 핏방울마다 흙을 덮고 매듭을 묶는다.', k:'gaze', dc:24, wake:1,
      ok:`방울마다 흙을 덮고 그 위에 풀 매듭을 하나씩 놓았다. 이름을 덮는 매듭이다.<br><br>뒤따르던 기척이 어느 방울에선가 길을 잃었다. 같은 자리를 도는 소리가 났다.<br>짐승에게 주술이 통하느냐고 일행이 물었다. 통한다. 코에 거는 주술은.<br><br>이름 없는 것에게도 걸 자리는 있다. 코, 눈, 발. 주술사의 책에 짐승 장이 생겼다.`,
      ng:`매듭 지을 풀이 중간에 떨어졌다.<br><br>덮다 만 길은 더 또렷한 길이다. 끊긴 데서부터 다시 또렷해지니까.<br>기척이 도로 붙었다. 다친 일행을 업고 걸음을 서둘렀다. 업은 등으로 피가 배었다. 이번엔 이쪽 옷에 적힌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 피 한 방울로 가짜 길을 놓는다.', k:'gaze', dc:24, cost:{ mana:30 },
      ok:`천에 받은 피 한 방울에 마력을 실었다. 백 방울 냄새가 나게.<br><br>그 천을 갈림길 반대쪽에 던졌다. 기척이 그쪽으로 꺾였다.<br>한참 뒤 그쪽에서 짧은 비명이 났다. 사람 것이 아니었다. 가짜 길 끝에 다른 짐승이 있었던 것이다. 길은 가짜여도 끝은 진짜였다.`,
      ng:`마력이 피에 붙다 말았다. 냄새가 반쪽이다.<br><br>기척이 갈림길에서 오래 머뭇거렸다. 그러더니 둘로 갈라졌다.<br>혼자가 아니었던 것이다. 하나는 가짜 길로, 하나는 이쪽으로. 반은 번 셈 치기로 했다.`,
      win:{ exp:21, dream:3 }, lose:{ spirit:-18, hp:-25 } }
  ] },

{ at:'S', t:'인형 — 이름 없는 것',
  x:`주술사는 쫓는 것의 인형을 깎는다. 나무토막에 그 윤곽을.<br><br>
    인형에는 이름을 넣어야 한다. 이름이 매듭이다.<br>
    그것에는 이름이 없다. 아무도 지어 준 적 없다.<br><br>
    이름 없는 것은 어떻게 매나.`,
  o:[
    { l:'① 이름 대신 발자국 흙을 채워 넣는다.', k:'gaze', dc:25,
      ok:`그것이 디딘 자국의 흙을 파서 인형 배에 채웠다. 이름이 없으면 자취로 맨다.<br><br>인형이 묵직해졌다. 맺힌 것이다.<br>인형 다리에 실을 감았다. 멀리서 걸음이 흐트러지는 소리가 났다. 오래는 못 간다. 넘어뜨리는 건 한 번이다. 그 한 번을 길목에서 썼다.`,
      ng:`자국 흙을 퍼 담다가 제 발자국 흙이 섞였다.<br><br>인형이 양쪽으로 맺혔다. 다리에 실을 감자 이쪽 다리가 저렸다.<br>인형을 태웠다. 타는 동안 다리가 계속 저렸다. 반은 제 인형이었으니까.`,
      win:{ exp:20, dream:3 }, lose:{ spirit:-19, mind:-15 } },
    { l:'② 인형을 길에 세워 미끼로 쓰고 지나간다.', k:'hide', dc:25,
      doom:{ title:'깎은 인형', what:'인형을 살피던 것에게 물려 끌려갑니다', dc:19, sec:45,
        text:`인형이 너무 잘 깎였다.<br><br>그것이 인형 앞에 멈춰 오래 들여다본다. 그 틈에 지나가려 했다.<br>그것이 고개를 들었다. 인형과 이쪽을 번갈아 본다. 깎은 손을 찾은 것이다.<br><br>인형은 그대로 두고 깎은 쪽을 문다. 끌려가며 보니 인형이 길에 반듯이 서 있다.`,
        dieText:`길 가운데 인형이 서 있다.<br><br>그 옆에 무언가 하나 더 세워져 있다.<br>나무는 아니다.` },
      ok:`인형을 길 가운데 세우고 덤불로 돌았다.<br><br>그것이 인형 앞에 멈췄다. 처음 보는 제 모습이다. 오래 들여다봤다.<br>그 시간에 길목을 다 빠져나왔다. 뒤에서 나무 쪼개지는 소리가 한 번 났다. 거울값이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'소금 선 — 짐승의 선',
  x:`쉬는 자리 둘레에 소금 선을 그었다.<br><br>
    혼에게는 벽이다. 짐승에게는 아니다. 짐승은 선을 모른다.<br>
    주술사는 그래도 긋는다. 긋고 나서 생각한다.<br><br>
    못 막는 선이면 뜻을 바꾸면 된다.`,
  o:[
    { l:'① 선의 뜻을 벽에서 경보로 바꾼다.', k:'gaze', dc:24,
      ok:`소금에 마른 잎과 잔가지를 섞어 다시 둘렀다. 밟으면 소리 나는 선이다.<br><br>막는 선이 아니라 알리는 선. 주술은 쓰임을 바꾸면 산다.<br>밤에 두 번 바스락 소리가 났고 두 번 다 모두가 깼다. 깬 기척에 두 번 다 물러갔다. 선은 한 번도 안 뚫렸다. 뚫릴 필요가 없었다.`,
      ng:`밤이슬에 잎이 눅었다. 소리가 죽었다.<br><br>아침에 보니 선 안쪽에 발자국이 하나 찍혀 있었다.<br>선은 끊기지 않았다. 넘은 게 아니라 위로 지나간 것이다. 발자국은 들어온 것 하나뿐이고 나간 것이 없었다. 그 셈은 아무에게도 말하지 않았다.`,
      win:{ exp:19, dream:2 }, lose:{ spirit:-19, mind:-15 } },
    { l:'② 일행의 손목을 실로 잇는다.', k:'bond', dc:23,
      ok:`다섯 손목을 한 실로 느슨하게 이었다. 하나가 끌려가면 넷이 안다.<br><br>밤중에 실이 한 번 팽팽해졌다. 넷이 한꺼번에 당겼다.<br>실 끝에 일행이 있었다. 자면서 걷고 있었다. 어둠 쪽으로. 깨우자 어디 가던 길이냐고 되물었다. 모르는 얼굴로.`,
      ng:`실이 자다가 엉켰다. 뒤척인 팔에 감겨서.<br><br>새벽에 하나가 일어나다 실에 걸려 넘어졌다. 소리가 났다.<br>소리에 어둠이 한 번 출렁했다. 실을 풀고 다시 맬 때까지 아무도 못 잤다.`,
      win:{ exp:16, spirit:5 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'죽은 탐사대 — 고인 미련',
  x:`앞선 팀이다. 셋. 자세가 제각각이고 끝은 같다.<br><br>
    주술사는 죽은 자리의 미련을 본다. 여기 고여 있다. 짙게.<br>
    짐승에게는 원한이 안 붙는다. 붙을 데가 없다.<br><br>
    갈 곳 없는 미련이 자리에만 고인다.`,
  o:[
    { l:'① 미련이 흐르지 않는 쪽을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`미련은 제가 죽은 길을 다시 가지 않는다. 고인 것이 한쪽으로만 출렁이고 한쪽은 잔잔하다.<br><br>잔잔한 쪽. 그들이 끝내 못 간 길이다. 가려던 길. 살 길이었을 길.<br>그쪽으로 일행을 돌렸다. 길이 맞았다. 반나절 뒤 물 냄새가 났다.<br><br>저주 아닌 것을 읽고 빌리는 법이 생겼다. 값은 정했다. 나가서 이 셋의 자리를 밖에 알리는 것. 미련은 그걸로 치러진다.`,
      ng:`읽는 사이 고인 것이 이쪽 어깨에 얹혔다.<br><br>무겁다. 벗으려 해도 손에 안 잡힌다.<br>한나절을 지고 걸었다. 물가에서 어깨를 씻자 그제야 흘러갔다. 흘러가며 한 번, 고맙다는 건지 미안하다는 건지 모를 무게로 꾹 눌렀다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-20, mind:-15 } },
    { l:'② 셋을 바로 눕히고 눈을 감긴다.', k:'steady', dc:23,
      ok:`하나씩 바로 눕히고 눈을 감겼다. 돌을 주워 머리맡에 하나씩.<br><br>고인 것이 조금 묽어졌다. 자리가 자리다워졌다.<br>일행이 말없이 거들었다. 마지막 돌을 놓자 바람이 한 번 지나갔다. 바람이 없는 데였다.`,
      ng:`둘째를 눕히다 멈췄다. 가슴팍이 비어 있었다. 안쪽으로.<br><br>겉은 성한데 속이 없다. 꺼내 간 것이다. 골라서.<br>마저 눕히긴 했다. 손이 떨려서 오래 걸렸다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-18, mind:-16 } }
  ] },

{ at:'S', t:'미끼 — 재우는 매듭',
  x:`짐승 고기 한 토막이 남았다. 뒤따르는 것에게 던질 수 있다.<br><br>
    주술사는 그냥 던지지 않는다.<br>
    먹을 것에는 먹은 뒤가 있다.<br><br>
    먹은 뒤를 정하는 것이 주술이다.`,
  o:[
    { l:'① 고기에 재우는 매듭을 심는다.', k:'gaze', dc:24, cost:{ mana:28 },
      ok:`풀을 일곱 매듭으로 엮어 고기 속에 밀어 넣고 마력을 먹였다. 일곱 매듭은 일곱 식경의 잠이다.<br><br>길에 두고 반 식경을 걸었을 때 뒤에서 그것이 먹는 소리가 났다.<br>그다음은 쿵, 눕는 소리. 반나절 거리를 벌었다. 잠든 짐승 옆을 다른 짐승이 지나가 주기를 비는 건 덤이다.`,
      ng:`매듭에 마력이 덜 스몄다. 급해서.<br><br>그것은 고기를 먹고 안 누웠다. 입맛만 다신 셈이다.<br>오히려 걸음이 빨라졌다. 먹이가 앞에 있다는 걸 확인했으니까. 밤새 쉬지 못하고 걸었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-27, spirit:-16 } },
    { l:'② 그냥 던지고 그 틈에 달아난다.', k:'luck', dc:23,
      ok:`토막을 뒤로 던지고 뛰었다.<br><br>먹는 소리가 났다. 먹는 동안은 안 쫓는다.<br>거리를 벌 만큼 벌었다. 주술 없는 미끼도 미끼는 미끼다. 주술사로서는 조금 분했다.`,
      ng:`던진 고기에 둘이 붙었다.<br><br>서로 차지하려는 싸움이 났다. 싸움이 구르며 이쪽으로 왔다.<br>옆길로 몸을 던져 피했다. 어깨가 바위에 쓸렸다. 싸움은 한참 갔다. 이긴 쪽이 마저 쫓아올 것이다. 배를 채우고.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S', t:'허물 — 닮은 것의 법',
  x:`벗은 껍질 한 자락이 바위에 걸려 있다. 그것의 것이다.<br><br>
    주술사의 법은 하나다. 닮은 것은 닮은 것을 움직인다.<br>
    제 몸이었던 것이면 더더욱.<br><br>
    이름 대신 쓸 것이 생겼다.`,
  o:[
    { l:'① 허물 조각을 돌로 눌러 주인을 묶는다.', k:'gaze', dc:25, cost:{ mana:32 }, wake:1,
      ok:`조각을 떼어 길목 바위 밑에 넣고 마력을 먹여 눌렀다. 조각이 눌리면 주인의 걸음도 눌린다.<br><br>그날 밤 그것의 걸음 소리가 눈에 띄게 느렸다. 끌리듯 걸었다.<br>묶인 줄은 모르고 제 몸만 무거운 줄 알 것이다.<br><br>이름 없는 것은 몸으로 맨다. 머리카락 대신 허물, 이름 대신 비늘. 주술 책이 한 장 늘었다.`,
      ng:`조각이 손안에서 바스러졌다. 너무 말랐다.<br><br>마른 허물엔 힘이 조금만 남는다. 가루에도 마력을 먹였다.<br>한 식경쯤 걸음이 무뎌지는 소리가 났고 그걸로 끝이었다. 그래도 한 식경은 한 식경이다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 허물을 뒤집어 걸어 둔다.', k:'fix', dc:23,
      ok:`허물을 안팎을 뒤집어 바위에 도로 걸었다.<br><br>뒤집힌 제 껍질은 짐승에게 틀린 그림이다. 그것이 와서 오래 멈춰 섰다.<br>제 것인데 제 것 같지 않은 것 앞에서 짐승도 생각이라는 걸 한다. 그 생각의 길이만큼 이쪽이 멀어졌다.`,
      ng:`뒤집다가 허물이 찢어졌다. 소리가 마른하늘 천둥 같았다.<br><br>어둠 저쪽이 조용해졌다. 듣는 조용함이다.<br>찢어진 반쪽을 쥔 채 한참을 엎드려 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ spirit:-16, hp:-25 } }
  ] },

{ at:'S', t:'울음 — 끼워 넣는 소리',
  x:`울음이 오간다. 묻고 답하는 간격이 있다.<br><br>
    주술사는 소리에도 주술이 탄다는 걸 안다.<br>
    말을 못 알아들어도 된다.<br><br>
    박자만 알면 끼어들 수 있다.`,
  o:[
    { l:'① 울음 사이 빈 마디에 돌 소리를 끼운다.', k:'gaze', dc:25,
      ok:`묻는 울음과 답하는 울음 사이, 빈 반 박자에 돌 두 개를 부딪었다.<br><br>셈이 흐트러졌다. 울음이 멎었다가 다시 일었는데 이번엔 서로를 향했다.<br>묻는 쪽과 답하는 쪽이 서로 의심하는 소리였다. 저들끼리 어긋나는 동안 그 사이로 빠져나왔다.`,
      ng:`끼워 넣은 박자가 하필 맞아떨어졌다.<br><br>대답이 된 것이다.<br>울음이 일제히 이쪽을 향했다. 돌을 버리고 뛰었다. 등 뒤에서 묻는 소리가 따라왔다. 아까보다 가까이에서.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 끼어들지 않고 울음 지도를 그린다.', k:'steady', dc:23,
      ok:`입을 다물고 귀로만 들었다. 울음 하나하나에 자리를 매겼다.<br><br>셋. 왼쪽 둘, 오른쪽 하나. 오른쪽이 젊다. 소리가 높다.<br>젊은 쪽이 구멍이다. 경험이 없는 쪽으로 길을 잡았다. 지도는 종이에 안 그렸다. 머리에만.`,
      ng:`세다 보니 넷이었다. 다시 세니 다섯.<br><br>늘어나는 게 아니라 이쪽 귀가 어두워지는 것이다. 같은 소리가 메아리로 돈다.<br>세기를 멈췄다. 모르는 수는 제일 큰 수로 친다. 그게 법이다. 걸음이 무거워졌다.`,
      win:{ exp:16, mind:5 }, lose:{ mind:-17, spirit:-15 } }
  ] },

{ at:'S', t:'쉬는 자리 — 꿈을 묶는 점',
  x:`이런 데서는 꿈이 얕다. 얕은 꿈에서는 비명이 샌다.<br><br>
    비명은 자리를 판다.<br>
    주술사는 눕는 일행의 잠부터 묶는다.<br><br>
    재 한 줌이면 된다.`,
  o:[
    { l:'① 다섯 이마에 재로 점을 찍는다.', k:'gaze', dc:24, wake:1,
      ok:`불 꺼진 재를 손끝에 묻혀 이마마다 점 하나씩 찍었다. 꿈을 눌러 두는 점이다.<br><br>밤새 아무도 뒤척이지 않았다. 잠꼬대도, 이 가는 소리도 없었다.<br>숨소리만 낮게 고른 자리는 어둠 속에서 없는 자리나 같다. 기척 하나가 바로 옆을 지나갔다. 그냥 지나갔다.<br><br>거는 주술보다 지키는 주술이 먼저 손에 붙었다. 이 바닥에서는 그게 순서다.`,
      ng:`한 점이 찍다가 번졌다.<br><br>그 하나가 새벽에 꿈에서 소리를 질렀다.<br>입을 막고 깨웠다. 늦었다. 어둠 저쪽에서 자리를 옮기는 소리가 났다. 이쪽도 자리를 옮겼다. 다들 반쪽 잠으로 아침을 맞았다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 불침번 교대에 맞춰 점을 지우고 다시 찍는다.', k:'fix', dc:23,
      ok:`점이 찍힌 채로는 못 깬다. 교대 순서마다 지우고 다시 찍는 당번을 정했다.<br><br>깰 사람은 깨고 잘 사람은 눌렸다.<br>잠과 깸이 톱니처럼 맞물려 돌아갔다. 주술은 혼자 걸면 주술이고 여럿이 돌리면 살림이 된다.`,
      ng:`교대 시간이 어긋났다. 점 지워진 둘이 같이 잤다.<br><br>눌리지 않은 꿈 둘이 겹쳤다. 하나가 끙 소리를 냈다.<br>작은 소리였는데 그 밤 따라 크게 울렸다. 남은 밤은 전원이 뜬눈이었다.`,
      win:{ exp:15, mind:6 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S', t:'발자국 — 못 박기',
  x:`그것의 발자국이 깊게 찍혀 있다. 아직 축축하다.<br><br>
    주술사의 옛 법이 있다. 자국에 못을 박으면 걸음이 저린다.<br>
    사람에게 쓰면 저주다.<br><br>
    여기서는 살 길이다.`,
  o:[
    { l:'① 가장 새 자국에 못을 박는다.', k:'gaze', dc:25,
      ok:`제일 또렷한 자국 한복판에 쇠못을 박았다.<br><br>멀리서 걸음이 무너지는 소리가 났다. 짧은 울음도.<br>하루치 거리를 벌었다. 다음 날 그 길을 되짚다 봤다. 못 박힌 자국 위에 돌이 얹혀 있었다. 그것이 제 자국을 덮기 시작한 것이다. 배운다. 그 말을 수첩에 적는 손이 느렸다.`,
      ng:`박고 보니 오래된 자국이었다. 축축한 건 밤이슬이었다.<br><br>허탕이다. 못만 잃었다.<br>못을 도로 뽑는데 잘 안 빠졌다. 흙이 못을 무는 것 같았다. 그냥 두고 왔다. 그게 자꾸 생각났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-15 } },
    { l:'② 절뚝이는 소리를 따라가 확인한다.', k:'sense', dc:24,
      doom:{ title:'저는 걸음', what:'절뚝이는 소리에 홀려 매복에 물려 끌려갑니다', dc:20, sec:40,
        text:`절뚝, 절뚝. 소리를 따라갔다. 주술이 들었는지 눈으로 봐야 했다.<br><br>소리가 바위 뒤에서 멎었다. 돌아 들어갔다. 아무것도 없다.<br>절뚝이는 소리는 낼 줄 아는 것이 내고 있었다. 다른 자리에서.<br><br>목덜미가 물린다. 끌려가며 들었다. 절뚝이는 소리가 아직도 바위 뒤에서 나고 있었다.`,
        dieText:`절뚝이는 소리가 그쳤다.<br><br>쓸모가 다해서.<br>그 소리는 다음 일행에게도 쓰일 것이다.` },
      ok:`따라가다 멈췄다. 절뚝임이 너무 고르다.<br><br>저는 다리는 박자가 흔들린다. 이건 흔들리지 않는다. 흉내다.<br>소리를 등지고 반대로 걸었다. 한참 뒤 소리가 그쳤다. 미끼는 물지 않으면 그냥 소리다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'눈 — 마주친 문',
  x:`어둠 속에서 눈 둘이 이쪽을 본다. 등불 빛을 되쏘며.<br><br>
    주술사는 배웠다. 눈이 마주치는 것은 문이 열리는 것이다.<br>
    문은 양쪽으로 열린다.<br><br>
    저쪽도 지금 이 문을 쓸 수 있다.`,
  o:[
    { l:'① 깜빡이지 않고 문을 먼저 닫는다.', k:'gaze', dc:26, wake:1,
      ok:`눈을 안 감았다. 마주친 채로 숨을 죽이고 속으로 문을 닫는 말을 왰다.<br><br>먼저 깜빡이는 쪽이 문을 내준다.<br>그 눈이 먼저 감겼다. 다시 떠졌을 때는 이쪽을 안 보고 있었다. 못 보는 것이다. 문이 닫혔으니까.<br><br>눈길도 길이다. 길이면 주술이 탄다. 보는 것으로 거는 법이 생겼다. 응시가 곧 주문이다.`,
      ng:`버티다가 먼저 깜빡였다.<br><br>눈을 뜨니 그 눈이 없었다. 감은 게 아니다. 보이지 않을 만큼 온 것이다.<br>옆으로 구르며 등불을 휘둘렀다. 바람이 얼굴을 스쳤다. 바람에 비린내가 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 등불을 꺼서 눈길을 끊는다.', k:'hide', dc:24,
      ok:`불을 껐다. 문은 양쪽이 보여야 열린다.<br><br>어둠 속에서 그 눈이 헤매는 기척이 났다. 빛을 되쏘던 눈은 빛이 없으면 과녁을 잃는다.<br>벽을 더듬어 자리를 옮겼다. 다시 불을 켰을 때 눈은 엉뚱한 데를 보고 있었다.`,
      ng:`불을 끄자 이쪽이 장님이 됐다.<br><br>저쪽은 아니었다.<br>더듬다 돌부리에 넘어졌다. 소리가 났다. 소리 쪽으로 오는 기척을 들으며 기어서 피했다. 무릎이 다 까졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S', t:'뼈 무더기 — 일곱 매듭 지팡이',
  x:`뼈 무더기 옆에 지팡이가 꽂혀 있다. 주술사의 지팡이다.<br><br>
    매듭이 일곱 묶였던 자국이 있다. 일곱 다 풀려 있다.<br>
    매듭 하나가 주술 하나다.<br><br>
    그는 가진 걸 전부 풀고 갔다.`,
  o:[
    { l:'① 풀린 순서를 읽는다.', k:'gaze', dc:25,
      ok:`풀린 자국의 닳은 정도로 순서를 셌다. 가벼운 것부터 풀었다. 마지막이 목숨 매듭이다.<br><br>전부 풀어 무엇을 샀나. 지팡이 둘레 두 걸음만 뼈가 없다.<br>그 두 걸음을 그것들이 아직 안 디딘다. 마지막 주술이 산 땅이다. 그 안에서 일행을 쉬게 했다. 선 주술사 몫의 셈은, 나가서 치르기로 했다.`,
      ng:`풀린 매듭 끝을 만졌다. 끈이 손가락에 스르르 감겼다.<br><br>마지막 주술이 주인을 찾는 것이다. 이을 사람을.<br>뿌리쳤다. 손가락에 끈 자국이 한동안 남았다. 자국이 없어질 때까지 그 손으로는 매듭을 안 묶었다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-20, mind:-14 } },
    { l:'② 지팡이를 뽑아 챙긴다.', k:'luck', dc:24,
      doom:{ title:'일곱 매듭', what:'지팡이를 등에 꽂은 것에게 물려 끌려갑니다', dc:19, sec:40,
        text:`지팡이는 땅에 꽂힌 게 아니었다.<br><br>뽑는 순간 바닥이 일어섰다. 흙을 뒤집어쓴 등이었다. 지팡이는 그 등에 박혀 있었다.<br>앞선 주술사가 마지막으로 꽂은 자리에.<br><br>그것이 몸을 털며 이쪽을 문다. 뽑은 손부터.`,
        dieText:`지팡이는 다시 그 자리에 꽂혀 있다.<br><br>매듭이 하나 새로 묶여서.<br>묶은 손은 보이지 않는다.` },
      ok:`뽑기 전에 둘레 흙에 물을 부었다. 흙이 숨을 쉬면 거품이 돈다.<br><br>안 돌았다. 그냥 땅이다. 그제야 뽑았다.<br>좋은 지팡이다. 일곱 매듭의 묶는 법이 나무에 결로 남아 있다. 결을 더듬으면 법이 읽힌다. 죽은 주술사의 손이 이쪽 손을 가르친다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S1', t:'표본 병 — 그릇의 미련',
  x:`깨진 표본 병이 선반에 줄지어 있다.<br><br>
    병마다 담겼던 것의 자국이 안벽에 눌어붙어 있다.<br>
    주술사는 그릇에 남는 미련을 안다.<br><br>
    오래 갇힌 것은 그릇을 기억한다. 그릇도 그것을 기억한다.`,
  o:[
    { l:'① 빈 병들의 미련이 쏠린 쪽을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`깨진 병을 하나씩 들어 봤다. 안벽의 자국이 전부 같은 쪽으로 쏠려 있다.<br><br>나간 것들이 간 방향이다. 그릇의 미련은 담겼던 것을 따라 눕는다.<br>그 방향을 지도에서 지웠다. 빈 그릇 서른 개가 서른 개의 나침반이었다.<br><br>그릇으로 담겼던 것을 읽는 법이 생겼다. 빈 것이 더 많이 말한다. 주술사의 셈은 빈 데서 시작한다.`,
      ng:`병 하나가 손안에서 가늘게 떨렸다.<br><br>미련이 아니다. 울림이다. 담겼던 것이 가까이 있으면 그릇이 운다.<br>병을 내려놓고 둘러봤다. 선반 뒤 어둠이 평소보다 깊었다. 그 방은 빠르게 나왔다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-18, mind:-16 } },
    { l:'② 성한 병 하나를 소금으로 채워 둔다.', k:'steady', dc:23,
      ok:`빈 그릇은 부른다. 채워진 그릇은 안 부른다.<br><br>성한 병 하나에 소금을 채워 선반 한가운데 세웠다.<br>밤에 지나던 기척이 선반 앞에서 멎었다가 그냥 갔다. 들어갈 자리가 없는 집은 들여다보지 않는다.`,
      ng:`소금이 반밖에 없었다.<br><br>반만 찬 그릇은 빈 그릇보다 더 부른다. 마저 채워 달라고.<br>밤새 선반 쪽에서 긁는 소리가 났다. 병 안쪽에서 나는 소리 같기도 했다. 아침에 보니 소금이 줄어 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S1', t:'숙주 — 자리를 옮기는 주술',
  x:`일행 하나의 목 뒤가 부었다. 주먹 반만 하게.<br><br>
    숨을 쉴 때 부은 데가 따로 숨 쉰다. 들어앉은 것이다.<br>
    내쫓는 주술은 혼에나 듣는다. 이건 혼이 아니라 몸이다.<br><br>
    몸은 내쫓지 못한다. 옮길 수는 있다.`,
  o:[
    { l:'① 더 좋은 자리를 꾸며 이사시킨다.', k:'gaze', dc:26, cost:{ mana:35 },
      ok:`짐승 고기 토막에 마력으로 온기와 맥박을 심었다. 사람보다 따뜻하게. 사람보다 크게 뛰게.<br><br>그 토막을 부은 데에 맞대었다. 한참 뒤 부기가 꿈틀하더니 고기 쪽으로 흘러 들어갔다.<br>옮겨 가기 직전 한 번 머뭇거렸다. 두 집을 재는 것처럼. 고기째 불에 던졌다. 타는 소리가 길었다.<br><br>일행은 목 뒤에 빈 주름만 남고 살았다. 쫓는 주술은 못 이겨도 속이는 주술은 이긴다.`,
      ng:`심은 맥박이 어설펐다. 박자가 사람과 달랐다.<br><br>그것이 가짜를 알아챘다. 더 깊이 파고들었다.<br>일행이 밤새 앓았다. 식은땀을 짜며. 날이 밝자 부기가 어깨 쪽으로 한 뼘 내려가 있었다. 시간이 줄고 있다.`,
      win:{ exp:24, dream:4 }, lose:{ spirit:-20, hp:-26 } },
    { l:'② 부은 데를 차게 눌러 둔한 것으로 만든다.', k:'heal', dc:24,
      ok:`찬물 적신 천으로 부은 데를 감쌌다. 들어앉은 것은 온기로 산다.<br><br>차게 하자 안의 꿈틀거림이 느려졌다.<br>치유 손 있는 일행이 손쓸 때까지 그걸로 벌었다. 주술사의 일은 이기는 게 아니라 시간을 버는 것일 때가 많다.`,
      ng:`차게 하자 그것이 놀랐다.<br><br>놀란 것은 움직인다. 부기가 목덜미를 타고 옆으로 옮겨 갔다.<br>일행이 비명을 물었다. 천을 뗐다. 어설픈 손은 안 대느니만 못했다.`,
      win:{ exp:16, hp:5 }, lose:{ hp:-28, mind:-15 } },
    { l:'③ 밤새 곁에서 지켜본다.', k:'steady', dc:24,
      ok:`그 일행을 가운데 눕히고 곁에 앉았다. 눈을 안 뗐다.<br><br>밤중에 귀 뒤에서 가는 더듬이가 나왔다. 이쪽과 눈이 마주치자 도로 들어갔다.<br>보는 눈이 묶는다. 밤새 세 번 나왔고 세 번 들어갔다. 아침까지 번 시간이 그 일행의 몫이 됐다.`,
      ng:`새벽에 깜빡 졸았다.<br><br>눈을 뜨니 더듬이가 옆에 자는 일행 쪽으로 길게 기울어 있었다.<br>소리 질러 깨웠다. 더듬이는 들어갔다. 둘 사이에 등불을 놓고 남은 밤을 셌다. 졸음이 제일 무서운 밤이었다.`,
      win:{ exp:17, spirit:5 }, lose:{ spirit:-19, mind:-16 } }
  ] },

{ at:'S1', t:'환풍구 — 바람길 방울',
  x:`바람이 관을 타고 건물을 돈다.<br><br>
    주술사는 바람길에 방울을 건다. 혼을 들으려 걸던 것이다.<br>
    여기서는 다른 것이 걸린다.<br><br>
    방울은 바람에 울고, 몸이 지나면 멎는다.`,
  o:[
    { l:'① 관 어귀마다 방울을 건다.', k:'gaze', dc:24,
      ok:`실에 꿴 방울을 어귀 셋에 걸었다. 바람이 있는 한 운다.<br><br>밤중에 하나가 뚝 멎었다. 바람이 멎은 게 아니다. 바람을 몸이 막은 것이다.<br>그 관 쪽 방을 버리고 반대로 옮겼다. 방울은 울 때보다 멎을 때 더 많이 말한다.`,
      ng:`방울이 밤새 울었다. 고르게, 쉼 없이.<br><br>바람인지 몸인지 가릴 수 없는 울음이었다.<br>결국 아무도 못 잤다. 아침에 방울을 걷었다. 걷은 방울 하나에 가는 침 같은 것이 꽂혀 있었다. 누가 쏜 것인지는 생각 안 하기로 했다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 멎은 방울의 관을 들여다본다.', k:'sense', dc:25,
      doom:{ title:'멎은 방울', what:'관 속에서 나온 것에 감겨 끌려 들어갑니다', dc:20, sec:40,
        text:`왜 멎었는지 눈으로 봐야 했다. 등불을 들고 관에 얼굴을 넣었다.<br><br>방울을 입에 문 것이 기다리고 있었다.<br>방울 소리로 부른 것이다. 이쪽 주술로, 이쪽을.<br><br>긴 것이 목에 감긴다. 관 속으로 끌려 들어간다. 방울이 딸랑, 한 번 운다.`,
        dieText:`방울이 다시 운다.<br><br>바람도 없는 관 속에서. 고르게.<br>다음 사람이 그 소리를 바람 소리로 들을 것이다.` },
      ok:`들여다보기 전에 등불을 비껴 들었다. 제 그림자를 관에 먼저 넣지 않는 법이다.<br><br>빛만 넣어 비췄다. 방울이 관 바닥에 떨어져 있다. 실이 삭아 끊긴 것뿐이다.<br>막대로 당겨 주웠다. 방울은 도로 걸었다. 이번엔 쇠줄로.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'산 자국 — 피는 주인을 못 잊는다',
  x:`복도 바닥이 녹아 구멍이 줄지었다. 그것의 피다.<br><br>
    주술사는 피로 주술을 쓴다. 피는 제일 진한 이름이다.<br>
    돌을 녹이는 피라도 피는 피다.<br><br>
    법이 통하는지는 대 봐야 안다.`,
  o:[
    { l:'① 마른 자국의 기울기로 주인 쪽을 읽는다.', k:'gaze', dc:25,
      ok:`피는 주인을 못 잊는다. 떨어져도 주인 쪽으로 눕는다.<br><br>마른 산 자국의 가장자리가 전부 한쪽으로 가늘게 쏠려 있었다.<br>주인이 있는 방향이다. 그 방향을 버리고 길을 짰다. 피 주술의 법이 여기서도 섰다. 겁나는 건, 이 법이 거꾸로도 선다는 것이다. 이쪽 피도 이쪽으로 눕는다.`,
      ng:`기울기를 보려고 너무 가까이 엎드렸다.<br><br>구멍 가장자리에서 덜 마른 방울이 소매에 닿았다. 천이 연기를 냈다.<br>소매를 찢어 버렸다. 맨팔이 시렸다. 시린 게 데인 것보다 나았다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, spirit:-15 } },
    { l:'② 구멍에 못을 떨어뜨려 깊이를 잰다.', k:'break', dc:24,
      ok:`못을 떨어뜨리고 소리를 셌다. 둘, 셋. 아래층까지 뚫렸다.<br><br>바닥이 꺼질 자리를 알았다. 구멍 둘레 한 걸음씩을 금 긋고 일행을 돌렸다.<br>마지막 사람이 지나고 나서 금 안쪽 바닥이 내려앉았다. 금은 주술이 아니었는데도 지켜 줬다.`,
      ng:`못 소리가 아래에서 되울렸다.<br><br>되울린 소리가 멎고, 다른 소리가 올라왔다. 긁는 소리.<br>아래 것이 들은 것이다. 구멍마다 어둠이 차 있는 복도를 발끝으로 건넜다. 등에 땀이 식었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, hp:-26 } }
  ] },

{ at:'S1', t:'어미의 부름 — 어긋나는 박자',
  x:`벽 너머에서 낮은 울림이 온다. 소리라기보다 소리 밑의 소리다.<br><br>
    알들이 듣는 울림이다. 듣고 있으면 발끝이 그쪽으로 돈다.<br>
    일행 하나는 벌써 반걸음 돌아서 있다.<br><br>
    부름은 박자다. 박자면 손쓸 수 있다.`,
  o:[
    { l:'① 부름을 거스르는 박자를 찾는다.', k:'gaze', dc:26, wake:1,
      ok:`울림의 결을 셌다. 셋에 한 번 당긴다.<br><br>그 사이, 둘째 박에 발을 딛게 했다. 당김과 어긋나는 걸음이다.<br>어긋난 박자로 걷는 동안 발끝이 돌지 않았다. 부름 구간을 그 걸음으로 다 지났다.<br><br>소리는 소리로 막는다. 주술에 꼭 말이 필요한 건 아니다. 박자가 곧 부적이다.`,
      ng:`결을 세다가 이쪽이 먼저 젖었다.<br><br>정신을 차리니 세 걸음 그쪽으로 가 있었다. 일행이 허리를 잡고 있었다.<br>부르는 것을 재는 자는 제일 먼저 불린다. 귀를 틀어막고 구간을 뛰어서 지났다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-21, mind:-16 } },
    { l:'② 마력으로 다섯 귀를 막는다.', k:'gaze', dc:25, cost:{ mana:30 },
      ok:`손끝에 마력을 모아 귀마다 마개를 심었다. 반나절짜리다.<br><br>세상이 솜에 싸인 듯 멀어졌다. 부름도 같이 멀어졌다.<br>구간을 다 지나고 마개를 풀었다. 못 듣던 소리가 한꺼번에 돌아왔다. 그중에 발소리가 하나 섞여 있었다. 멀어지는 발소리인 게 다행이었다.`,
      ng:`마개 하나가 고르지 못했다. 한 귀가 샜다.<br><br>그 일행이 말없이 대열을 벗어났다. 두 사람이 쫓아가 붙들었다.<br>버둥대는 힘이 사람 힘이 아니었다. 구간을 벗어나자 제정신이 돌아왔다. 어디까지 갔었는지는 아무도 말해 주지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, spirit:-18 } }
  ] },

{ at:'S1', t:'격실 문 — 닫힘의 뜻',
  x:`격실 문이 잠겼다. 전기가 죽어 손잡이는 돌지 않는다.<br><br>
    쇠는 주술을 잘 안 듣는다. 차고 무뚝뚝한 물건이다.<br>
    손잡이 옆에 손자국이 있다. 녹아서 눌린 자국이다.<br><br>
    앞서 누가 맨손으로 열려 했던 것이다. 그 손의 피가 산이었을 뿐.`,
  o:[
    { l:'① 문이 아니라 문틀의 닫힘에 건다.', k:'gaze', dc:25,
      ok:`쇠문은 귀가 없다. 그러나 문틀의 「닫힘」은 뜻이다. 뜻에는 걸 수 있다.<br><br>문틀 네 귀에 손끝으로 풀림의 획을 그었다.<br>문이 한 뼘 밀렸다. 사람 하나 지날 만큼. 다 지나고 나서 획을 지웠다. 문이 도로 물렸다. 뒤에 오는 것에게도 문은 문이어야 하니까.`,
      ng:`획이 미끄러졌다. 쇠의 냉기가 뜻을 밀어냈다.<br><br>문은 꿈쩍 않았다. 시간만 한 식경을 썼다.<br>돌아서는데 문 너머에서 쿵, 하고 무엇이 문에 몸을 기대는 소리가 났다. 안 열린 게 다행인지는 끝내 모른다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 녹은 자국에 지렛대를 걸어 비튼다.', k:'break', dc:25,
      doom:{ title:'격실 저쪽', what:'문틈으로 나온 것에게 물려 격실 안으로 끌려갑니다', dc:19, sec:40,
        text:`지렛대를 걸고 체중을 실었다. 문이 갑자기 가벼워졌다.<br><br>이쪽 힘이 아니다. 저쪽에서 당긴 것이다.<br>문틈으로 긴 것이 나와 팔을 감는다.<br><br>격실 안으로 끌려 들어간다. 문이 등 뒤에서 닫힌다. 이번에는 부드럽게.`,
        dieText:`격실 문은 다시 잠겨 있다.<br><br>손잡이 옆에 녹은 손자국이 하나 늘었다.<br>안쪽에.` },
      ok:`비틀기 전에 문에 귀를 댔다. 쇠는 소리를 잘 나른다.<br><br>저쪽은 비어 있었다. 숨도 기척도 없다. 그제야 비틀었다.<br>격실 안은 보급 창고였다. 기름종이에 싼 비상식이 선반에 남아 있었다. 녹은 손자국의 주인이 가려던 데가 여기였을 것이다. 그 몫까지 챙겼다.`,
      win:{ exp:21, dream:3, item:'말린 고기' } }
  ] },

{ at:'S1', t:'냉동고 — 잠든 숙주들',
  x:`냉동고다. 서리 낀 유리 너머로 사람들이 매달려 있다.<br><br>
    가슴마다 멍울이 비친다. 들어앉은 것째 얼린 것이다.<br>
    천장 전등이 깜빡인다. 전기가 죽어 가고 있다.<br><br>
    전기가 죽으면 서리가 녹는다.`,
  o:[
    { l:'① 멍울마다 산 것과 죽은 것을 가린다.', k:'gaze', dc:26,
      ok:`유리 너머로 멍울을 하나씩 읽었다. 언 것, 삭은 것, 그리고 아직 천천히 도는 것 둘.<br><br>도는 둘은 전기가 죽으면 깬다.<br>냉동고 문을 밖에서 걸고 문틈을 걸레로 메웠다. 냉기가 하루는 더 간다. 하루면 이 층을 다 지난다. 그 둘의 아침보다 이쪽 걸음이 빠르면 된다.`,
      ng:`읽는 중에 전등이 나갔다.<br><br>어둠 속에서 유리 두드리는 소리가 났다. 안쪽에서. 천천히, 두 번.<br>전등이 다시 들어왔을 때 매달린 것들은 그대로였다. 두드릴 손이 있는 것은 없었다. 그 방을 나올 때까지 아무도 숨을 크게 못 쉬었다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 언 사람들에게 허리 숙여 예를 한다.', k:'bond', dc:24,
      ok:`보낼 수 있는 자리가 아니어도 예는 예다. 허리를 숙였다.<br><br>일행이 따라 숙였다.<br>숙인 동안 냉동고가 웅, 하고 한 번 크게 돌았다. 죽어 가던 전기가 마지막 힘을 낸 것뿐이다. 그렇게 생각하기로 다들 말없이 정했다.`,
      ng:`숙인 고개를 들다가 봤다.<br><br>매달린 하나의 손가락이 구부러져 있었다. 들어올 때는 펴져 있었다.<br>본 사람이 이쪽뿐이었다. 말하지 않았다. 혼자 무거운 게 다섯이 무거운 것보다 낫다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-19, mind:-15 } },
    { l:'③ 냉동고 안을 질러 반대편 문으로 간다.', k:'hide', dc:25,
      doom:{ title:'서리', what:'언 것들 사이로 끌려 들어갑니다', dc:20, sec:35,
        text:`매달린 것들 사이로 걸었다. 반쯤 갔을 때 등 뒤에서 유리가 안쪽부터 깨졌다.<br><br>서리가 바닥을 타고 이쪽으로 번진다.<br>언 손이 발목을 잡는다. 차다는 느낌보다 무겁다는 느낌이 먼저다.<br><br>매달린 것들 사이로 끌려 들어간다. 서리가 무릎까지 오른다.`,
        dieText:`냉동고에 매달린 것이 하나 늘었다.<br><br>가슴에 멍울은 없다.<br>아직은.` },
      ok:`질러가되 매달린 것들의 발밑 그림자만 밟았다. 그림자 밑은 서리가 얇다. 소리가 안 난다.<br><br>반대편 문까지 숨 네 번이면 됐다.<br>문을 닫고 돌아보니 유리마다 입김 같은 김이 안쪽에서 서려 있었다. 전등 탓이다. 전등 탓으로 해 뒀다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'무리 — 머리 하나',
  x:`울타리 너머를 셋이 오간다. 둘이 울타리를 건드리고 하나는 떨어져 있다.<br><br>
    주술사는 무리에 거는 법을 안다. 전부에게는 못 건다.<br>
    머리 하나면 된다.<br><br>
    누가 머리인가.`,
  o:[
    { l:'① 제일 늦게 움직이는 것을 찾는다.', k:'gaze', dc:25,
      ok:`먼저 움직이는 둘은 손발이다. 떨어져서 보기만 하는 하나, 그게 머리다.<br><br>머리가 디딘 자국의 흙을 한 줌 떠서 주머니에 넣었다. 걸 준비다.<br>건 것은 아직 없다. 그래도 주머니가 묵직한 것만으로 걸음이 가벼워졌다. 패는 쥐고 있을 때 패다.`,
      ng:`울타리를 건드리던 놈을 머리로 짚었다. 틀렸다.<br><br>그 놈 자국의 흙을 뜨는 걸 진짜 머리가 보고 있었다.<br>그날부터 셋의 오가는 길이 바뀌었다. 이쪽 눈이 닿지 않는 쪽으로. 주술 쓰는 먹이로 기억된 것이다.`,
      win:{ exp:21, dream:3 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 셋이 다 보일 때만 움직인다.', k:'hide', dc:24,
      ok:`법을 하나 세웠다. 셋이 다 보이면 걷고, 하나라도 안 보이면 멈춘다.<br><br>안 보이는 놈이 제일 가깝다.<br>그 박자로 한나절을 이동했다. 멈춘 횟수가 걸은 횟수보다 많았지만 긁힌 사람은 없었다.`,
      ng:`하나가 시야에서 빠졌다. 멈추라는 신호가 늦었다.<br><br>바로 옆 수풀에서 숨소리가 났다. 씹는 것처럼 느린 숨.<br>뒷걸음으로 열 걸음, 그다음은 뛰었다. 수풀은 끝내 갈라지지 않았다. 배가 불렀던 모양이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S2', t:'물 밑 길 — 부적 세 장',
  x:`길이 물에 잠겼다. 밑이 안 보인다.<br><br>
    주술사는 부적을 물에 띄운다. 종이는 물을 읽는다.<br>
    뜨는 자리, 도는 자리, 가라앉는 자리.<br><br>
    종이가 먼저 가 본다.`,
  o:[
    { l:'① 부적 세 장으로 물속을 읽는다.', k:'gaze', dc:24,
      ok:`석 장을 띄웠다. 두 장은 곧게 흘러갔다. 한 장이 가운데서 핑 돌더니 섰다.<br><br>도는 자리는 밑에서 물이 치받는 자리다. 치받는 건 숨이다.<br>그 자리를 크게 돌아 얕은 목으로 건넜다. 종이 석 장 값으로 물속 지도를 샀다.`,
      ng:`종이가 삭아 있었다. 석 장이 다 젖어 바로 가라앉았다.<br><br>읽을 게 없어졌다.<br>결국 막대로 더듬으며 건넜다. 허리까지 잠겼다. 막대 끝에 한 번, 단단한 게 아닌 것이 닿았다. 서두르는 바람에 반쯤은 허우적이었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 부적이 뜬 길로 바로 건넌다.', k:'evade', dc:25,
      doom:{ title:'뜬 종이', what:'물 밑에서 올라온 것에게 물려 끌려 내려갑니다', dc:20, sec:35,
        text:`부적이 뜬 길은 얕은 길이다. 얕은 길까지는 맞았다.<br><br>부적은 물을 읽는다. 물 밑에 숨죽인 것까지는 못 읽는다.<br>발목이 잡힌다. 아래로.<br><br>마지막으로 본 것은 얼굴 위로 떠가는 부적 한 장이다. 종이는 끝까지 떠 있었다.`,
        dieText:`부적 석 장이 가라앉았다.<br><br>한 자리에서. 거의 동시에.<br>물은 금세 다시 잔잔해졌다.` },
      ok:`건너되 부적 한 장을 반 걸음 앞에 흘려보내며 갔다.<br><br>종이가 먼저 디디고 이쪽이 반 박자 뒤에 디뎠다.<br>가운데쯤에서 물 밑 그림자가 부적 쪽으로 쏠렸다가 종이인 걸 알고 비껴갔다. 그 반 박자가 산 것이다. 종이 한 장 값으로.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'S2', t:'물가 말뚝 — 삭은 금줄',
  x:`큰 것이 다니는 물가 쪽 말뚝에 삭은 새끼줄이 걸려 있다.<br><br>
    울타리가 아니다. 금줄이다. 사육사들이 쳤다.<br>
    가둘 수 없는 것은 모신다. 그들은 그걸 알았던 것이다.<br><br>
    줄은 삭았지만 뜻은 아직 매여 있다.`,
  o:[
    { l:'① 금줄을 새로 꼬아 다시 건다.', k:'gaze', dc:25, cost:{ mana:27 },
      ok:`마른 풀을 꼬아 새 줄을 내고 마력을 먹여 옛 줄 위에 겹쳐 걸었다.<br><br>금줄은 큰 것에게는 안 들린다. 들리는 건 작은 것들이다.<br>작은 사냥꾼들은 금줄 안쪽을 큰 것의 자리로 안다. 들어오지 않는다. 그 안쪽으로 길을 잡았다. 제일 큰 것의 이름을 빌려 제일 안전한 길을 냈다.`,
      ng:`꼬는 중에 물이 떨렸다. 서둘렀다.<br><br>반만 건 금줄은 반만 일한다.<br>금줄 안쪽으로 걷는데 수풀 저쪽에서 따라 걷는 기척이 반나절 붙었다. 들어오지는 않고, 끊긴 데를 찾으며.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-17, mind:-15 } },
    { l:'② 금줄 아래 제물 자리를 뒤진다.', k:'luck', dc:23,
      ok:`말뚝 앞에 평평한 돌이 묻혀 있었다. 제단이다.<br><br>돌 밑에 소금 덩이가 삭은 천에 싸여 있었다. 제물로 두던 것이다.<br>반을 떼어 챙기고 반은 도로 두었다. 모시던 자리의 몫은 남기는 법이다.`,
      ng:`제단 돌이 미끄러지며 발등을 찍었다.<br><br>소리를 물고 주저앉았다.<br>물가가 조용해졌다. 큰 것 말고도 듣는 것이 많은 물가였다. 절뚝이며 자리를 떴다.`,
      win:{ exp:14, item:'소금 덩이' }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'뿔피리 — 사육사의 유품',
  x:`오두막 벽에 뿔피리가 걸려 있다. 급이 신호용이다.<br><br>
    부는 것은 미친 짓이다. 이 벌판 전부가 듣는다.<br>
    주술사는 소리 말고 쓰는 법을 안다.<br><br>
    물건에는 쓰임이 배어 있다.`,
  o:[
    { l:'① 피리에 밴 신호의 기억을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`주둥이 닳은 각도, 숨이 드나든 자국. 신호는 두 가지였다. 짧게 셋은 밥, 길게 둘은 물러서라.<br><br>물러서라의 박자를 외웠다. 부는 대신 나뭇가지로 말뚝을 두드려 그 박자를 냈다.<br>수풀 가장자리까지 왔던 그림자들이 주춤 물러섰다. 몸이 기억하는 박자다. 사육사는 죽고 박자만 남아서 일한다.<br><br>물건에 밴 쓰임을 읽는 손이 생겼다. 죽은 도구가 산 기술이 된다.`,
      ng:`박자를 거꾸로 외웠다.<br><br>두드리자 수풀이 일제히 이쪽으로 쏠렸다. 밥 신호였다.<br>말뚝을 버리고 뛰었다. 등 뒤로 모여드는 소리를 들으며. 박자 하나가 삶과 밥을 가른다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 불지 않고 챙겨만 둔다.', k:'steady', dc:23,
      ok:`허리춤에 단단히 묶어 챙겼다. 쓸 날이 올 수도 있다. 안 오는 게 최선이다.<br><br>오두막을 나서는데 피리 속에서 마른 벌레 한 마리가 떨어졌다.<br>속에 살던 것이다. 그래서 여태 바람에도 안 울었구나. 빈 피리가 된 걸 아무도 모르게 품었다.`,
      ng:`걷다가 피리가 울었다. 바람이 주둥이를 스친 것이다. 짧게, 한 번.<br><br>벌판이 조용해졌다. 듣는 조용함이었다.<br>피리를 품 안으로 욱여넣고 한참을 엎드려 있었다. 그 뒤로 피리 주둥이는 천으로 막아 뒀다.`,
      win:{ exp:15, dream:2 }, lose:{ spirit:-18, mind:-15 } }
  ] },

{ at:'S2', t:'큰 발소리 — 소리 그늘',
  x:`쿵. 물이 떨린다. 사이를 두고 또 쿵.<br><br>
    큰 것이 이쪽으로 온다. 숨을 데가 없다.<br>
    주술사는 소리에 소리를 숨길 줄 안다.<br><br>
    큰 소리는 작은 소리를 먹는다.`,
  o:[
    { l:'① 발소리에 걸음을 맞춘다.', k:'gaze', dc:26, wake:1,
      ok:`쿵, 할 때만 걷는다. 다섯이 한 덩이로, 한 걸음씩.<br><br>큰 것의 발소리가 이쪽 발소리를 먹었다. 소리의 그늘로 걸은 것이다.<br>큰 것이 벌판을 다 건널 때까지 그 그늘로 따라 걷다가 갈림에서 빠졌다. 큰 것은 끝내 몰랐다.<br><br>세상의 모든 큰 소리가 숨을 자리가 됐다. 천둥도, 무너지는 소리도. 주술사는 그걸 소리 그늘이라 적었다.`,
      ng:`박자를 하나 놓쳤다. 사이에 디딘 걸음이 크게 울렸다.<br><br>발소리가 멎었다. 벌판 전체가 멎었다.<br>영원 같은 사이가 지나고 다시 쿵, 걸음이 이어졌다. 이쪽 걸음은 한참 뒤에야 이어졌다. 무릎이 떨려서.`,
      win:{ exp:25, dream:4 }, lose:{ spirit:-20, mind:-15 } },
    { l:'② 마력으로 다섯의 기척을 눌러 덮는다.', k:'gaze', dc:25, cost:{ mana:38 },
      ok:`숨소리, 발소리, 심장 소리까지 마력 한 겹으로 눌렀다.<br><br>큰 것이 바로 옆을 지나갔다. 콧김에 머리카락이 날렸다.<br>알고도 지나간 게 아니다. 몰라서 지나갔다. 그 차이를 아는 건 이쪽뿐이고, 그거면 충분하다.`,
      ng:`마력이 반에서 바닥났다. 기척이 반만 눌렸다.<br><br>큰 것이 고개를 돌렸다.<br>그때 물새 떼가 날아올랐다. 큰 것의 눈이 그쪽으로 끌렸다. 새 떼에게 평생 갚을 빚을 졌다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, hp:-26 } },
    { l:'③ 전원 엎드려 땅이 된다.', k:'steady', dc:24,
      ok:`진흙에 몸을 붙이고 숨을 죽였다. 움직이는 것만 보는 눈이 있다.<br><br>발이 바로 옆 물웅덩이를 디뎠다. 흙탕이 얼굴까지 튀었다.<br>아무도 닦지 않았다. 큰 것이 멀어지고 나서야 일어났다. 다섯 다 진흙 거푸집 같은 몰골로. 살아 있는 몰골로.`,
      ng:`하나가 숨을 못 참고 고개를 들었다.<br><br>큰 것의 걸음이 느려졌다.<br>그 일행을 도로 눌러 엎드리게 하고 전원이 숨을 멈췄다. 걸음이 다시 빨라질 때까지. 폐가 터지는 줄 알았다.`,
      win:{ exp:17, hp:5 }, lose:{ hp:-27, spirit:-17 } }
  ] },

{ at:'S2', t:'둥지 — 건드리면 안 되는 것',
  x:`수풀 가운데 둥지다. 알이 가지런하다.<br><br>
    주술사의 버릇은 깨기 전의 것에 금줄을 치는 것이다.<br>
    여기 알은 깨면 안 되는 것이 아니다.<br><br>
    건드리면 안 되는 것이다.`,
  o:[
    { l:'① 바람이 둥지로 드는 쪽을 읽고 비켜 간다.', k:'gaze', dc:25,
      ok:`어미는 눈보다 코가 밝다. 풀이 눕는 결로 바람길을 읽었다.<br><br>바람을 등지지 않고 가로질러, 냄새가 둥지에 닿지 않는 호를 그리며 돌았다.<br>둥지의 어미가 끝내 모르는 것. 그것이 이 바닥 최선의 주술이다. 건 것도 푼 것도 없이 이기는 판.`,
      ng:`벌판 바람은 변덕이다. 반쯤 돌았을 때 바람이 돌았다.<br><br>이쪽 냄새가 둥지 쪽으로 쏟아졌다.<br>수풀이 일어서는 소리를 들으며 남은 반을 뛰었다. 호는 무너졌지만 거리는 벌어 둔 게 있었다. 그 거리만큼만 살았다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 둥지 가의 깨진 껍데기를 재료로 줍는다.', k:'luck', dc:25,
      doom:{ title:'비운 척', what:'돌아온 어미에게 물려 둥지 너머로 끌려갑니다', dc:19, sec:40,
        text:`껍데기에 손이 닿는 순간 수풀이 눕는다.<br><br>어미는 둥지를 비우지 않는다. 비운 척할 뿐이다.<br>목덜미가 물린다. 둥지 위를 지나 수풀 너머로 끌려간다.<br><br>새끼들 먹이는 신선해야 하니까.`,
        dieText:`둥지 가장자리의 껍데기들이 가지런해졌다.<br><br>어미가 정리한 것이다.<br>둥지에는 빈 데가 없다.` },
      ok:`맨손으로 집지 않았다. 넓은 잎에 싸서, 제 냄새를 안 묻히고 주웠다.<br><br>물러나 수풀에 엎드렸을 때 어미가 돌아왔다. 둥지를 코로 하나하나 셌다.<br>빈 껍데기는 셈에 없었다. 주머니 속 재료가 온기를 잃어 가는 걸 느끼며 자리를 떴다. 닮은 것의 법에 쓸, 더없는 재료다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'승강기 — 소리를 묶는 매듭',
  x:`낡은 승강기 쇠문 앞이다. 줄이 위로 까마득하다.<br><br>
    도르래가 녹슬었다. 움직이면 운다.<br>
    우는 소리는 벌판 전부를 부른다.<br><br>
    주술사는 소리부터 묶는다.`,
  o:[
    { l:'① 줄에 소리 죽이는 매듭을 묶는다.', k:'gaze', dc:26, wake:1,
      ok:`헝겊을 찢어 줄에 일곱 매듭을 묶었다. 삐걱임이 매듭마다 한 번씩 죽는 법이다.<br><br>승강기가 속삭이듯 내려왔다. 녹슨 쇠가 그렇게 조용한 건 처음 들었다.<br>문이 열리는 동안 벌판은 아무것도 몰랐다.<br><br>일곱 매듭에 소리를 묶는 법이 늘었다. 주술사의 매듭은 이제 여덟 가지다.`,
      ng:`여섯째 매듭이 풀렸다. 삐걱, 한 번.<br><br>한 번이면 충분했다. 벌판이 들었다.<br>문이 열릴 때까지의 시간 동안 수풀 세 군데가 갈라지며 다가왔다. 문이 반 뼘 빨랐다. 반 뼘이 전부였다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-16, hp:-27 } },
    { l:'② 타는 순서를 미리 정해 둔다.', k:'bond', dc:24,
      ok:`짐 먼저, 사람은 둘씩. 마지막은 이쪽.<br><br>순서가 정해진 줄은 출렁이지 않는다.<br>줄이 버텼고 소리도 반으로 줄었다. 질서가 반은 주술이다.`,
      ng:`순서가 엉켰다. 셋이 한꺼번에 몰렸다.<br><br>줄이 출렁이며 삐걱 소리가 크게 두 번 났다.<br>수풀에서 답이 왔다. 문이 닫히는 게 먼저였다. 닫힌 문 바깥을 발톱이 한 번 긁고 갔다. 쇠문이어서 자국만 남았다.`,
      win:{ exp:16, spirit:5 }, lose:{ spirit:-18, hp:-28 } }
  ] }
]);
// ── 퇴마사 (마력)
kJob('exorcist', 'S', [

{ at:'S', t:'사체 곁 — 남은 것',
  x:`앞선 팀의 사체다. 그 곁에 혼이 서 있다.<br><br>
    짐승에게 죽은 혼은 대개 어리둥절해서 남는다. 제 끝을 몰라서.<br>
    이 혼은 어리둥절하지 않다.<br><br>
    어딘가를 뚫어지게 보고 있다.`,
  o:[
    { l:'① 혼이 보는 곳을 따라 본다.', k:'gaze', dc:25, wake:1,
      ok:`혼은 제 몸을 안 본다. 벽 아래 틈을 본다.<br><br>가 보니 몸 하나 들어갈 틈이다. 안쪽이 넓고 입구가 좁다. 그가 닿지 못한 숨을 자리다.<br>일행을 그 틈에 재웠다. 돌아보니 혼이 옅어지고 있었다. 알려 주고 나서야 간 것이다.<br><br>죽은 눈이 보는 곳이 유언이다. 혼의 눈길을 읽는 법이 생겼다. 말보다 정확한 유언이다.`,
      ng:`눈길을 쫓다가 혼과 눈이 마주쳤다.<br><br>혼이 이쪽으로 쏠렸다. 업히려는 것이다. 제 발로는 못 가는 데를 남의 등으로.<br>한 발 물러서며 떼어 냈다. 어깨가 한참 시렸다. 혼은 도로 제자리에 서서 다시 벽을 봤다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, mind:-15 } },
    { l:'② 짧게 염을 하고 보낸다.', k:'bond', dc:23,
      ok:`몸을 바로 눕히고 낮게 염을 했다. 소리는 입술 안에만 머물게.<br><br>혼이 한 번 이쪽을 보고 흩어졌다.<br>자리가 가벼워졌다. 일행도 그걸 느꼈는지 어깨를 폈다. 무거운 데서는 걸음도 무거워지는 법이다.`,
      ng:`염 중간에 어둠 저쪽에서 기척이 일었다.<br><br>끊고 일행을 물렸다. 끊긴 염은 혼에게 빚이다.<br>그날 내내 등 뒤가 무거웠다. 혼이 따라와서가 아니다. 두고 와서다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-17, mind:-14 } }
  ] },

{ at:'S', t:'어둠 — 굶주림과 악의',
  x:`어둠 속에서 기척이 이쪽을 살핀다.<br><br>
    퇴마사는 가르는 것부터 한다.<br>
    악의는 퇴마가 듣는다. 굶주림은 안 듣는다.<br><br>
    경을 꺼내기 전에 알아야 한다. 이게 어느 쪽인지.`,
  o:[
    { l:'① 기척의 결을 읽어 가른다.', k:'gaze', dc:25,
      ok:`악의는 사람을 고른다. 하나를 정해 두고 그 하나만 따라온다.<br><br>이 기척은 안 고른다. 다섯을 번갈아 잰다. 무게를 재듯.<br>굶주림이다. 굶주림에게 경은 소음이다. 경을 도로 넣고 거리를 벌렸다. 굶주림의 퇴마는 멀어지는 것뿐이다.`,
      ng:`가르지 못한 채 버릇으로 경을 한 줄 왰다.<br><br>기척이 멈칫했다. 들은 것이다. 그리고 그대로 다가왔다.<br>물러나지 않는 것은 굶주림이다. 경으로 자리만 판 셈이다. 등불을 쥐고 밤새 뒷걸음질 쳤다.`,
      win:{ exp:21, dream:3 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 가르기 전에 몸부터 숨긴다.', k:'hide', dc:24,
      ok:`바위 그늘로 다섯을 몰아넣고 숨을 죽였다.<br><br>기척이 비어 버린 자리를 오래 맴돌았다.<br>악의든 굶주림이든 못 찾는 먹이는 못 문다. 가르는 건 살아남은 다음에 해도 된다.`,
      ng:`그늘이 얕았다. 등불 끄는 게 반 박자 늦었다.<br><br>기척이 곧장 그늘로 왔다.<br>그늘을 버리고 흩어졌다가 다시 모였다. 하나가 무릎을 깼다. 모이는 자리를 미리 안 정한 값이다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'기도문 — 다섯 심장',
  x:`그것들은 어둠 속에서 심장 소리를 듣는다.<br><br>
    다섯 심장이 제각각 뛰면 다섯 개의 과녁이다.<br>
    퇴마사의 기도문은 본래 떨리는 혼을 재우는 것이다.<br><br>
    산 심장이라고 못 재울 것 없다.`,
  o:[
    { l:'① 기도문으로 다섯 박동을 하나로 맞춘다.', k:'gaze', dc:25, cost:{ mana:28 }, wake:1,
      ok:`낮게 읊었다. 마력을 가락에 실어서. 숨이 먼저 맞고 심장이 따라 맞았다.<br><br>다섯이 하나의 크고 느린 심장이 됐다.<br>짐승 귀에는 큰 것 하나가 쉬는 소리로 들렸을 것이다. 작은 기척들이 밤새 멀리로만 돌았다. 큰 것은 건드리지 않는 법이니까.<br><br>기도문의 새 쓰임이 생겼다. 혼이 아니라 산 사람을 고르는 법. 경전에 없는 장을 몸으로 썼다.`,
      ng:`하나가 박자를 놓쳤다. 겁이 많은 심장이었다.<br><br>넷이 고른 소리 속에서 어긋난 하나가 오히려 또렷해졌다.<br>기척이 그쪽으로 쏠리는 게 느껴졌다. 기도를 끊고 자리를 옮겼다. 그 일행은 제 심장을 원망했다. 심장 탓이 아니라고 말해 줬다. 밤 탓이다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-18, hp:-25 } },
    { l:'② 숨 고르는 법만 가르친다.', k:'fix', dc:23,
      ok:`넷 셀 동안 들이쉬고 여섯 셀 동안 내쉰다. 그것만 가르쳤다.<br><br>마력 없이도 숨은 숨을 따라간다.<br>반 식경 뒤 다섯 숨이 얼추 맞았다. 완벽하진 않아도 과녁 다섯이 과녁 둘쯤으로는 줄었다.`,
      ng:`가르치는 목소리가 너무 컸다.<br><br>숨을 고르기 전에 소리부터 샜다.<br>어둠이 한 번 출렁했다. 가르침을 끊고 전원 입을 닫았다. 숨은 각자 알아서 골랐다. 겁이 선생 노릇을 했다.`,
      win:{ exp:15, mind:5 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S', t:'소금 — 쓰임을 바꾼다',
  x:`소금 한 줌이 남았다.<br><br>
    소금 선은 혼에게 벽이다. 짐승은 그냥 넘는다.<br>
    여기서 혼의 벽은 쓸모가 없다.<br><br>
    그러면 쓰임을 바꾸면 된다.`,
  o:[
    { l:'① 지나온 길에 뿌려 냄새를 끊는다.', k:'gaze', dc:24,
      ok:`소금은 냄새를 먹는다. 발자국 위에 가늘게, 끊기지 않게 뿌렸다.<br><br>뒤따르던 코가 그 자리에서 길을 잃었다. 킁킁대며 도는 소리가 한참 났다.<br>혼을 막던 것이 코를 막았다. 퇴마의 도구는 퇴마사보다 유연했다.`,
      ng:`아까워서 띄엄띄엄 뿌렸다.<br><br>끊기다 만 냄새 길은 수수께끼일 뿐 벽이 아니다.<br>뒤따르는 기척이 조금 느려지기만 했다. 느려진 만큼만 벌었다. 소금은 다 썼다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-15, spirit:-15 } },
    { l:'② 바위 틈에서 소금을 더 찾는다.', k:'luck', dc:23,
      ok:`물기 마른 바위 틈에 허연 결정이 앉아 있었다. 암염이다.<br><br>주먹만 한 덩이를 캤다.<br>이 어둠에도 소금은 있다. 소금이 있는 데는 짐승이 핥으러 온다는 것까지 생각이 미쳐, 캐자마자 자리를 떴다.`,
      ng:`틈에 손을 깊이 넣다가 긁혔다.<br><br>마른 틈이 아니었다. 안쪽이 축축했다.<br>축축한 데 사는 것에게 물리기 전에 손을 뺐다. 손등의 긁힌 자국이 소금 값이 됐다. 소금은 못 캤다.`,
      win:{ exp:14, item:'소금 덩이' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S', t:'빈 자리 — 그것들도 피하는 곳',
  x:`발자국들이 한 자리를 크게 돌아서 피해 다닌다.<br><br>
    가운데에 검은 바위가 하나 있다.<br>
    퇴마사는 안다. 짐승이 피하는 자리에는 짐승보다 오랜 것이 있다.<br><br>
    여기 무언가 눌려 있다.`,
  o:[
    { l:'① 눌린 것의 내력을 읽는다.', k:'gaze', dc:26,
      ok:`바위 둘레의 땅이 눌린 지 오래다. 그리고 눌림이 아직 살아 있다.<br><br>그 눌림이 짐승들을 쫓는 것이다. 발자국이 피해 도는 호의 가장자리, 거기가 이 어둠에서 제일 안전한 잠자리다.<br>가장자리에 일행을 재웠다. 짐승은 안 왔다. 새벽에 바위 쪽에서 낮은 울림이 한 번 왔다. 고맙다는 것도 가라는 것도 아닌, 그냥 안다는 울림이었다.`,
      ng:`읽는 중에 눌린 것이 이쪽을 알아챘다.<br><br>바위가 식은땀처럼 번들거리기 시작했다.<br>읽기를 그만두고 물러났다. 눌린 것은 읽는 눈을 싫어한다. 오래 눌린 것일수록. 그 밤은 호 바깥 멀리서 잤다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-21, mind:-15 } },
    { l:'② 검은 바위를 들춰 본다.', k:'break', dc:25,
      doom:{ title:'눌린 것', what:'바위 밑에서 올라온 것에 감겨 끌려 들어갑니다', dc:20, sec:40,
        text:`바위가 생각보다 가벼웠다. 그게 답이었다.<br><br>눌림은 무게가 아니었다. 바위는 뚜껑이었을 뿐.<br>들춘 손목에 검은 것이 감긴다. 차지도 뜨겁지도 않다. 그냥 아래로 당긴다.<br><br>짐승들이 왜 이 자리를 돌아다녔는지, 내려가면서 알게 된다.`,
        dieText:`바위는 제자리에 놓여 있다.<br><br>발자국들이 그 자리를 전보다 더 크게 돌기 시작했다.<br>짐승은 셈이 빠르다.` },
      ok:`들추지 않았다. 대신 바위 둘레 흙에 누름 획을 하나 덧그었다.<br><br>오래 눌린 것은 눌림이 헐거워진다. 한 획이 백 년을 번다.<br>퇴마사의 일은 여는 것보다 닫아 두는 것이 많다. 여기서는 전부다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'향 — 연기의 눈',
  x:`향이 세 대 남았다.<br><br>
    피우면 냄새가 퍼진다. 이런 데서는 미친 짓처럼 들린다.<br>
    퇴마사는 향으로 보는 법을 안다.<br><br>
    연기는 거짓말을 안 한다.`,
  o:[
    { l:'① 향 한 대로 어둠의 숨을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`한 대를 피워 들었다. 연기가 흘러가다 한 자리에서 비껴 돌았다.<br><br>바람이 아니다. 숨이다. 들숨이 연기를 당기고 날숨이 민다.<br>그 자리에 엎드린 것이 있다. 연기가 가리킨 자리를 피해 길을 냈다. 향내가 이쪽 냄새까지 덮어 준 건 덤이다.<br><br>연기가 보는 것을 같이 보는 법이 생겼다. 향 한 대가 등불보다 멀리 본다.`,
      ng:`바람이 변덕을 부렸다.<br><br>연기가 이쪽을 휘감았다. 다섯이 향내 표식이 됐다.<br>향을 끄고 급히 자리를 옮겼다. 반나절을 걸어도 옷에서 향내가 났다. 절에서라면 좋은 냄새였을 것이다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-17, hp:-26 } },
    { l:'② 향을 아끼고 제 코로만 살핀다.', k:'steady', dc:23,
      ok:`코로 공기를 갈랐다. 흙냄새, 물냄새, 그리고 비린내 한 줄.<br><br>비린내가 오는 쪽을 버리고 걸었다.<br>향은 품에 그대로다. 세 대가 세 번의 눈이다. 아낀 눈은 나중에 밝다.`,
      ng:`코가 둔해져 있었다. 며칠 내 맡은 피비린내 탓이다.<br><br>비린내 한 줄을 놓쳤다.<br>모퉁이에서 기척과 정면으로 마주쳐 되돌아 뛰었다. 향보다 코가 먼저 닳는 줄은 몰랐다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'염주 알 — 한 알씩',
  x:`길에 염주 알이 떨어져 있다. 한 알, 또 한 알. 간격을 두고.<br><br>
    끊어져 흩어진 게 아니다. 뿌린 것이다.<br>
    앞선 퇴마사가 길을 남겼다.<br><br>
    어디로든 이어진다. 좋은 데로든, 아닌 데로든.`,
  o:[
    { l:'① 알이 놓인 간격을 읽는다.', k:'gaze', dc:25,
      ok:`간격이 일정하다. 침착한 손이다. 도망치며 흘린 게 아니라 걸으며 놓은 것이다.<br><br>인도다. 알을 따라가니 바위 밑 피신처가 나왔다.<br>그의 가방이 남아 있었다. 약초 뭉치가 성하다. 벽에는 숯으로 한 줄. 「따라온 사람은 여기서 쉬어라. 나는 더 간다.」 그 말대로 쉬었다. 더 간 사람 몫으로 염주 알 하나를 벽 밑에 놓아두었다.`,
      ng:`간격이 뒤로 갈수록 벌어졌다.<br><br>걷다가, 서두르다가, 뛰었다는 뜻이다.<br>마지막 알 너머에는 끌린 자국만 있었다. 거기서 멈췄다. 알들을 주워 모아 주머니에 넣었다. 무거웠다. 알 무게가 아니었다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 알을 주우며 끝까지 따라간다.', k:'sense', dc:24,
      doom:{ title:'놓인 알', what:'알을 놓아 둔 것에게 물려 끌려갑니다', dc:19, sec:40,
        text:`알을 줍다가 손이 멎었다. 이 간격은 사람 걸음이 아니다.<br><br>너무 고르다. 자로 잰 듯이. 사람은 이렇게 못 걷는다.<br>알을 주워 온 길을 돌아봤다. 어둠이 길을 닫고 있었다.<br><br>주운 알들이 주머니에서 달그락거린다. 미끼를 주머니에 넣고 걸은 것이다.`,
        dieText:`길에 염주 알이 다시 놓인다.<br><br>한 알씩. 간격을 두고.<br>간격은 아까보다 더 고르다.` },
      ok:`주우며 수를 셌다. 퇴마사의 버릇이다. 백팔이어야 한다.<br><br>스물을 넘기며 간격이 변하는 걸 느꼈다. 사람 걸음의 흔들림이 없다.<br>수를 세는 버릇이 발을 세웠다. 알을 전부 길에 도로 놓고 물러났다. 누가 놓았든, 수가 안 맞는 염주는 염주가 아니다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'불침번 — 소리 없는 경',
  x:`불침번 차례다. 등불 하나, 어둠 전부.<br><br>
    퇴마사는 밤이면 경을 왼다. 버릇이다.<br>
    여기서 소리를 내면 안 된다.<br><br>
    속으로 외는 경은 더 빨리 돈다.`,
  o:[
    { l:'① 속으로 경을 돌리며 어둠의 결을 살핀다.', k:'gaze', dc:24, wake:1,
      ok:`경이 안에서 도는 동안 눈이 어둠에 익었다.<br><br>어둠에도 결이 있다. 고른 결이 흐트러지는 자리, 거기가 움직이는 것이다.<br>밤새 결이 두 번 흐트러졌고 두 번 다 일행을 조용히 깨워 등을 맞댔다. 두 번 다 그냥 지나갔다. 대비한 밤에는 아무 일도 일어나지 않는다. 그게 대비의 일이다.<br><br>소리를 잃은 경이 눈으로 옮겨 갔다. 외는 것이 아니라 보는 경이 됐다.`,
      ng:`속엣 경이 자꾸 끊겼다.<br><br>끊긴 자리로 잠이 밀고 들어왔다.<br>고개를 떨구다 깼다. 등불이 반으로 줄어 있었다. 줄어든 반 동안 무엇이 다녀갔는지는 모른다. 발자국은 없었다. 그게 더 싫었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 교대마다 경을 한 구절씩 넘긴다.', k:'bond', dc:23,
      ok:`교대하며 다음 사람 귀에 경 한 구절을 넘겼다. 속으로만 외라고.<br><br>구절이 밤새 사람에서 사람으로 돌았다.<br>아침에 마지막 사람이 첫 구절을 이쪽에 돌려줬다. 경 한 바퀴가 밤 한 바퀴였다. 끊기지 않은 밤이었다.`,
      ng:`한 사람이 구절을 잊어버렸다.<br><br>경이 거기서 끊겼다. 끊긴 걸 아침에야 알았다.<br>경 탓은 아니겠지만 그 사람 차례의 밤에 짐 하나가 물어 뜯겨 있었다. 다들 말은 안 했다.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-16, mind:-15 } }
  ] },

{ at:'S', t:'들린 귀 — 걸린 소리',
  x:`일행 하나가 자꾸 뒤를 돌아본다.<br><br>
    아무 소리도 없는데 부른다고 한다. 씐 게 아니다.<br>
    들린 것이다. 귀에 들어온 소리가 나가지 않는 것.<br><br>
    울음 한 토막이 귓속에 걸려 돌고 있다.`,
  o:[
    { l:'① 귀에 대고 경 한 구절로 밀어낸다.', k:'gaze', dc:25, cost:{ mana:26 },
      ok:`걸린 소리는 소리로 민다. 귀에 입을 대고 경 한 구절을 마력에 실어 또박또박 넣었다.<br><br>걸려 돌던 울음이 밀려 나왔다. 그 일행이 제 귀를 틀어막고 주저앉았다.<br>그리고 울었다. 시원해서 우는 울음이었다. 그 뒤로 그는 뒤를 안 돌아봤다.`,
      ng:`구절이 걸린 소리와 섞였다.<br><br>울음 반, 경 반이 함께 돌기 시작했다. 더 복잡한 것이 됐다.<br>한나절을 더 고생하고서야 저절로 풀렸다. 그 일행은 그 뒤로 퇴마사가 입을 열면 한 발 물러섰다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-18, mind:-16 } },
    { l:'② 부른다는 쪽의 반대로 급히 돈다.', k:'evade', dc:24,
      doom:{ title:'몰이', what:'소리 반대편에 기다리던 것에게 물려 끌려갑니다', dc:20, sec:40,
        text:`부르는 쪽을 피해 반대로 꺾었다. 그게 몰이였다.<br><br>소리는 개가 짖는 쪽이고 그물은 그 반대에 쳐 있다.<br>수풀이 좌우에서 일제히 닫힌다. 기다리던 것들이다.<br><br>맨 뒤가 물려 끌려간다. 부르던 소리가 그제야 그친다. 일을 다 해서.`,
        dieText:`부르는 소리가 그쳤다.<br><br>그 일행의 귀도 조용해졌다.<br>몰이가 끝나면 개도 쉰다.` },
      ok:`반대로 돌려다 멈췄다. 소리로 몬다면 반대쪽이 그물이다.<br><br>옆으로 비스듬히 빠졌다. 소리에게도 그물에게도 등을 안 주고.<br>빠져나온 뒤에 원래 가려던 반대쪽에서 수풀 눕는 소리가 길게 났다. 빈 그물 걷는 소리였다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'죽어 가는 일행 — 아직 아니다',
  x:`일행이 크게 물렸다. 피가 멎지 않는다.<br><br>
    치유 손이 상처에 붙어 있다. 그 눈이 퇴마사를 찾는다.<br>
    죽음 곁의 눈은 퇴마사를 알아본다.<br><br>
    혼이 몸에서 반 뼘 떠 있다.`,
  o:[
    { l:'① 뜨는 혼을 눌러 앉힌다.', k:'gaze', dc:26, wake:1,
      ok:`혼은 아픈 몸을 떠나고 싶어 한다. 아픈 건 몸이 다 받으니까.<br><br>가슴에 손을 얹고 혼을 바로 봤다. 아직 아니다. 그 한마디를 눈으로 눌렀다.<br>혼이 몸에 도로 앉았다. 앉으니 아픔이 돌아왔고, 아픔이 돌아오니 숨이 돌아왔다. 치유 손이 그 숨을 붙들어 살렸다.<br><br>내치는 손이 붙드는 손이 됐다. 산 사람의 혼을 앉히는 법, 퇴마의 반대 방향이 트였다.`,
      ng:`누르는 손이 반 박자 늦었다.<br><br>혼이 반 넘게 떴다가 치유 손의 고함에 놀라 돌아왔다.<br>살기는 살았다. 그 사람은 한동안 제 이름이 설다고 했다. 떴던 반만큼 설은 것이다. 시간이 메울 것이다.`,
      win:{ exp:24, dream:4 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 치유 손 곁에서 지혈을 거든다.', k:'heal', dc:24,
      ok:`천을 찢어 대 주고 누르는 자리를 바꿔 가며 거들었다.<br><br>피가 멎었다.<br>퇴마사의 손도 손이다. 경 못지않게 압박이 사람을 살리는 날이 있다.`,
      ng:`누르는 자리가 어긋났다.<br><br>피가 한 번 더 크게 비쳤다. 치유 손이 이쪽 손을 밀어냈다.<br>물러나서 할 수 있는 일을 했다. 길게 비는 일. 그 일행은 살았다. 이쪽 덕은 아니었다.`,
      win:{ exp:15, hp:5 }, lose:{ hp:-25, mind:-15 } },
    { l:'③ 귀에 대고 길을 일러 둔다.', k:'steady', dc:24,
      ok:`만약을 위해서다. 귀에 대고 낮게 일렀다. 가게 되면 빛 말고 바람을 따라가라. 바람은 밖으로 분다.<br><br>그 사람이 피 묻은 입으로 웃었다. 안 갈 건데요.<br>안 갔다. 말은 그래도 남는다. 언젠가 누구에게든 쓰일 것이다.`,
      ng:`이르는 말이 유언처럼 들렸던 모양이다.<br><br>그 사람 눈에 겁이 확 찼다. 맥이 흔들렸다.<br>치유 손이 이쪽을 노려봤다. 입을 닫고 손만 잡아 줬다. 말은 약이기도 하고 칼이기도 하다.`,
      win:{ exp:15, spirit:5 }, lose:{ spirit:-17, mind:-15 } }
  ] },

{ at:'S', t:'빈 몸 — 없는 혼',
  x:`사체가 하나 있다. 혼이 없다. 아예.<br><br>
    이런 죽음에는 혼이 남는 게 정상이다. 억울하니까.<br>
    퇴마사는 없는 것에서 더 많이 읽는다.<br><br>
    여기, 혼을 먹는 것도 있다.`,
  o:[
    { l:'① 혼이 사라진 자리를 읽는다.', k:'gaze', dc:26,
      ok:`끌려간 자국이 아니다. 뜯긴 자국이다. 몸 위 반 뼘, 혼이 앉는 자리가 비어 있다. 빛이 빠진 것처럼.<br><br>몸을 먹는 짐승들 틈에 혼을 먹는 것이 하나 섞여 있다.<br>그것이 지나간 자리는 그늘이 유난히 깊다. 해도 불도 없는 데서 지는 그늘은 그늘이 아니다. 그날부터 깊은 그늘을 피하는 기준이 하나 늘었다. 일행에게는 축축한 데를 피하자고만 했다. 그 말이 더 쉽게 들으니까.`,
      ng:`없음을 들여다보는데 그 없음이 이쪽을 쟀다.<br><br>혼의 무게를 재는 눈이었다.<br>눈을 내리깔고 물러났다. 그날 밤 꿈에서 제 몸 위 반 뼘이 자꾸 시렸다. 깨서 만져 봤다. 있었다. 아직.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-22, mind:-16 } },
    { l:'② 사체의 짐을 거둔다.', k:'luck', dc:24,
      doom:{ title:'깊은 그늘', what:'그늘 속으로 끌려 들어갑니다', dc:20, sec:38,
        text:`짐을 뒤지는 사이 사체의 그늘이 길어졌다.<br><br>해도 불도 그대로인데 그늘만 이쪽으로 자란다.<br>그늘이 발에 닿자 소리가 사라졌다. 제 비명도 들리지 않는다.<br><br>그늘 속으로 끌려 들어간다. 춥지도 않다. 그냥 조용하다.`,
        dieText:`사체가 둘이 됐다.<br><br>둘 다 혼이 없다.<br>그늘은 제 길이로 돌아갔다.` },
      ok:`거두기 전에 그늘부터 봤다. 등불은 이쪽에 있는데 그늘이 저쪽으로 져 있다.<br><br>틀린 그늘이다. 그늘을 등지지 않는 각도로 돌아 짐만 집었다.<br>비상식 꾸러미가 손에 들어왔다. 그늘이 한 뼘 자라는 걸 보며 물러났다. 늦게 거두는 손은 같이 거둬진다.`,
      win:{ exp:20, dream:3, item:'말린 고기' } }
  ] },

{ at:'S1', t:'관찰실 — 일하는 혼들',
  x:`유리 너머 관찰실에서 혼들이 일하고 있다.<br><br>
    기록하고, 재고, 들여다본다. 제 죽음을 모르는 채.<br>
    혼은 마지막 동작을 돈다.<br><br>
    한 혼이 같은 서랍을 열고 닫기를 반복한다.`,
  o:[
    { l:'① 반복되는 동작에서 유언을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`같은 서랍만 여닫는 혼. 거기 못 끝낸 일이 있다.<br><br>서랍을 열었다. 보고서 한 장. 「환풍 7번 관, 즉시 용접 요망. 그 길로 들어온다.」 끝내 못 올라간 보고다.<br>대신 받았다. 7번 관이 지나는 복도를 전부 피해 길을 짰다. 혼이 서랍 앞에서 멈췄다. 일이 끝난 것이다. 옅어지는 어깨가 홀가분해 보였다.<br><br>혼의 반복은 고장이 아니라 유언이다. 그걸 받아 주는 것도 퇴마다.`,
      ng:`유리를 가볍게 두드렸다. 알려 주고 싶었다. 끝났다고.<br><br>혼들이 일제히 고개를 들어 이쪽을 봤다.<br>보면 안 되는 걸 본 얼굴들이었다. 이쪽이 그들의 유령이었던 것이다. 유리에서 물러났다. 혼들은 다시 일로 돌아갔다. 아주 천천히.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 방해하지 않고 창가로 돌아간다.', k:'steady', dc:23,
      ok:`일하는 자리는 돌아가 주는 게 예의다. 산 사람의 일터든 아니든.<br><br>유리에서 비켜 벽을 따라 돌았다.<br>지나며 보니 칠판에 수식이 적혀 있었다. 끝 줄이 미완성이었다. 그건 어쩔 수 없다. 모든 일터에는 끝나지 않은 줄이 있다.`,
      ng:`돌아가는 복도가 생각보다 길었다.<br><br>반 바퀴를 돌아 제자리 비슷한 데로 나왔다.<br>유리 너머 혼 하나가 이쪽을 보고 있었다. 아까는 안 보던 혼이었다. 걸음을 빨리했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'S1', t:'숙주 — 밀려난 혼',
  x:`목 뒤가 부은 일행. 들어앉은 것은 몸이라 내쫓지 못한다.<br><br>
    퇴마사의 눈에는 하나가 더 보인다.<br>
    그 일행의 혼이 몸 가장자리로 밀려나 있다.<br><br>
    집에 세 든 것이 주인을 문간으로 민 꼴이다.`,
  o:[
    { l:'① 밀려난 혼을 가운데로 당겨 앉힌다.', k:'gaze', dc:26, cost:{ mana:33 },
      ok:`벌레는 못 빼도 혼의 자리는 지킬 수 있다.<br><br>밤새 낮은 경에 마력을 실어 혼을 가운데로 당겼다. 혼이 제자리를 되찾자 들어앉은 것이 더 깊이 들지 못했다.<br>부기가 밤새 한 치도 안 늘었다. 집은 주인이 가운데 있어야 집이다. 시간을 벌었다. 버는 것이 이기는 것이다. 여기서는.`,
      ng:`당기는 중에 혼이 크게 출렁였다.<br><br>그 일행이 벌떡 일어나 제 몸을 내려다봤다. 제 것이 아닌 것처럼.<br>달래서 다시 눕히는 데 반 밤이 갔다. 혼은 제자리 근처로 돌아왔다. 근처까지만.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 이름을 자꾸 불러 준다.', k:'bond', dc:24,
      ok:`이름은 혼의 닻이다. 손을 잡고 수시로 이름을 불렀다.<br><br>부를 때마다 그 사람 눈의 초점이 또렷해졌다.<br>들어앉은 것은 이름이 없다. 이름 싸움에서는 사람이 이긴다. 밤새 불렀고 아침에 그 사람이 먼저 이쪽 이름을 불렀다.`,
      ng:`밤중에 이름을 불렀는데 대답 대신 다른 목소리가 났다.<br><br>그 사람 목에서 나온, 그 사람 것이 아닌 울림이었다.<br>손을 놓칠 뻔했다. 안 놓았다. 아침까지 쥔 손에 손톱자국이 났다. 이쪽 손톱이 아니다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-21, mind:-16 } }
  ] },

{ at:'S1', t:'수조 — 떠 있는 것',
  x:`깨진 수조들 사이에 성한 수조가 하나 있다.<br><br>
    안에 무언가 웅크린 채 떠 있다.<br>
    유리에 금이 하나 가 있다.<br><br>
    산 것인지 죽은 것인지부터 갈라야 한다.`,
  o:[
    { l:'① 혼의 유무로 생사를 가린다.', k:'gaze', dc:25,
      ok:`혼이 없다. 몸의 김도 없다. 죽었다.<br><br>다만 배가 비어 있지 않다. 죽기 전에 삼킨 것이 있다.<br>삼켜진 것이 산 것일 수 있다. 수조에 손대지 않기로 했다. 방을 나서는데 등 뒤에서 톡, 금 가는 소리가 한 번 났다. 안에서 민 소리인지 유리가 삭는 소리인지 가리지 않고 걸음만 빨리했다.`,
      ng:`가리느라 등불을 유리에 바짝 댔다.<br><br>안의 것이 빛 쪽으로 반 뼘 돌았다.<br>죽은 것은 돌지 않는다. 등불을 내리고 소리 없이 물러났다. 생사를 가리는 데 등불을 쓰면 안 된다는 걸 몸으로 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-19, mind:-15 } },
    { l:'② 수조 앞에 선반을 눕혀 둔다.', k:'fix', dc:24,
      ok:`쇠 선반을 수조 앞에 눕히고 유리 파편을 흩어 두었다.<br><br>터져 나와도 한 박자 늦는다. 그 한 박자가 사람 목숨이다.<br>떠나며 돌아보니 금이 아까보다 손가락 하나만큼 길어 보였다. 기분 탓이기를 빌었다. 비는 것도 일이다.`,
      ng:`선반을 눕히다 모서리가 수조를 쳤다.<br><br>금이 소리 내며 한 뼘 자랐다.<br>전원이 방을 뛰쳐나왔다. 문을 닫고 귀를 댔다. 물소리는 안 났다. 아직은.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-25, mind:-15 } },
    { l:'③ 금 간 데를 마저 깨서 확인한다.', k:'break', dc:25,
      doom:{ title:'죽은 척', what:'수조에서 쏟아진 것에 감겨 끌려갑니다', dc:20, sec:38,
        text:`금을 건드리자 유리가 통째로 주저앉았다.<br><br>물과 함께 쏟아진 것이 바닥에서 웅크림을 풀었다.<br>죽은 척은 그것들의 첫 번째 기술이다. 떠 있던 건 기다린 것이다.<br><br>긴 것이 다리를 감는다. 젖은 바닥 위로 끌려간다. 복도 어둠 쪽으로.`,
        dieText:`수조가 비었다.<br><br>바닥의 물 자국이 복도 어둠까지 길게 이어져 있다.<br>돌아 나온 자국은 없다.` },
      ok:`깨기 전에 유리에 귀를 댔다. 물속의 소리는 유리가 나른다.<br><br>가늘고 느린 맥이 있었다. 산 것이다.<br>망치를 내렸다. 깨는 것은 확인이 아니라 개봉이다. 그 방 문을 밖에서 걸어 잠그고 떠났다. 자물쇠가 경이었다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'정화수 — 산을 씻는 물',
  x:`복도 바닥이 산 핏자국으로 녹아 있다. 지나야 하는 복도다.<br><br>
    허리춤에 정화수 한 병. 부정을 씻는 물이다.<br>
    산도 부정이라면 부정이다.<br><br>
    대 보기 전엔 모른다.`,
  o:[
    { l:'① 정화수를 조금씩 떨궈 시험한다.', k:'gaze', dc:25,
      ok:`한 방울을 자국 가장자리에 떨궜다. 김이 가늘게 오르고 자국이 묽어졌다.<br><br>묽어진 자국은 밟아도 된다. 신 바닥이 버틴다.<br>반 병을 길게 부어 한 사람 폭의 길을 냈다. 다섯이 그 길로 건넜다. 물은 반 병 썼다. 아깝지만 발바닥보다 싸다.`,
      ng:`급해서 한꺼번에 부었다.<br><br>김이 확 올라 얼굴을 덮쳤다. 기침이 터졌다.<br>기침 소리가 복도를 타고 멀리 갔다. 길은 반쯤 나다 말았고, 남은 반은 뛰어 건넜다. 신 바닥이 뜨끈했다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 코로 산기가 옅은 길을 고른다.', k:'sense', dc:23,
      ok:`산내는 쇠가 삭는 냄새와 닮았다. 옅은 쪽을 골라 벽에 붙어 걸었다.<br><br>자국이 성긴 길이 벽 쪽에 나 있었다.<br>흘린 것도 벽은 피해 다녔다는 뜻이다. 벽 쪽은 천장이 낮아서다. 그 생각은 다 건넌 다음에 했다.`,
      ng:`코가 금세 산내에 절었다.<br><br>옅고 짙은 구분이 사라졌다.<br>한 발이 자국 가장자리를 디뎠다. 신 밑창이 얇아진 채로 남은 길을 걸었다. 발바닥이 종일 뜨거웠다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'환풍구 — 관을 타는 경',
  x:`관이 건물의 소리를 다 나른다.<br><br>
    퇴마사의 경도 나를 것이다.<br>
    관 속의 것들에게 경이 닿으면 어찌 되는지는 아무 경전에도 없다.<br><br>
    시험해 볼 관이 눈앞에 있다.`,
  o:[
    { l:'① 관에 대고 낮게 경을 흘려 본다.', k:'gaze', dc:26, wake:1,
      ok:`경을 한 소절 흘렸다. 돌아온 것은 메아리였다.<br><br>메아리의 간격이 자리마다 다르다. 빈 관은 길게 울고 막힌 자리는 짧게 끊긴다.<br>막힘 둘. 몸이다. 그 두 관이 지나는 길을 버렸다. 경이 측량줄이 됐다.<br><br>소리를 보내 어둠을 재는 법이 생겼다. 경이 등불보다 멀리 간다. 빛이 못 도는 모퉁이를 소리는 돈다.`,
      ng:`경에 답이 왔다.<br><br>따라 하는 소리였다. 서툴게, 그러나 두 번째는 덜 서툴게.<br>경을 끊었다. 외워 온 것을 도둑맞는 기분이었다. 그 관 근처에서는 입을 다물었다. 경은 속으로만 돌렸다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 관 어귀의 어둠에 봉인 획을 긋는다.', k:'gaze', dc:25, cost:{ mana:30 },
      ok:`쇠에는 획이 안 선다. 관 속 어둠에는 선다.<br><br>어귀의 어둠에 마력으로 획을 긋자 어둠이 한 겹 굳었다.<br>하룻밤짜리 마개다. 그 밤 그 어귀로는 바람 소리도 안 났다. 아침에 걷힐 때 안쪽에서 무언가 마개를 두드린 자국처럼 획이 패어 있었다. 하룻밤 값은 했다.`,
      ng:`긋던 마력이 관 안쪽으로 빨려 들어갔다.<br><br>빈 관이 아니었다. 마시는 것이 있었다.<br>손을 떼고 물러났다. 관 속에서 입맛 다시는 것 같은 소리가 났다. 그 복도에서는 더 아무것도 긋지 않았다.`,
      win:{ exp:21, dream:3 }, lose:{ spirit:-19, hp:-26 } }
  ] },

{ at:'S1', t:'어미 방 — 의식은 노래로 들린다',
  x:`어미의 방을 지나야 한다.<br><br>
    큰 악 앞에서 의식을 벌이는 것이 퇴마사의 본능이다.<br>
    여기서 그 본능이 맞는지부터 따져야 한다.<br><br>
    어미에게 경은 어떻게 들릴까.`,
  o:[
    { l:'① 의식을 접고 어미가 보는 법을 읽는다.', k:'gaze', dc:26,
      ok:`어미는 눈으로 안 본다. 바닥 떨림으로 본다. 알을 품는 것들이 그렇다.<br><br>발꿈치를 들고 발볼로만 디뎠다. 떨림 없는 걸음으로 벽을 따라 돌았다.<br>방을 다 지날 때까지 어미의 숨 간격이 변하지 않았다. 의식 없이 지나가는 것이 이 방 최고의 의식이었다. 경전에는 없는 법문이다.`,
      ng:`버릇이 손을 움직였다. 수인이 반쯤 맺히며 소매가 스쳤다.<br><br>천 스치는 소리 하나에 어미의 숨이 멎었다.<br>전원이 얼어붙었다. 숨이 다시 이어질 때까지 아무도 눈을 깜빡이지 않았다. 손은 그 뒤로 허리띠에 묶어 뒀다. 농담이 아니라 정말로.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-21, mind:-16 } },
    { l:'② 정면에서 축귀 의식을 벌인다.', k:'gaze', dc:26, cost:{ mana:40 },
      doom:{ title:'자장가', what:'노래를 들으려는 어미에게 들려 알 자리로 끌려갑니다', dc:20, sec:35,
        text:`경이 방에 퍼졌다. 어미가 고개를 들었다.<br><br>물러나지 않는다. 귀를 기울인다.<br>축귀의 경이 어미에게는 노래로 들린 것이다. 새끼들 곁에서 듣고 싶은 노래로.<br><br>들려 올라간다. 알 한가운데로. 경은 끊기지 않는다. 끊으면 안 될 것 같아서.`,
        dieText:`방에 낮은 울림이 남았다.<br><br>경의 가락을 닮은 울림이다.<br>어미가 새끼들에게 들려주고 있다.` },
      ok:`축귀의 경 대신 재우는 경을 골랐다. 떨리는 혼을 누이던 가락이다.<br><br>마력을 실어 바닥으로 깔았다. 알들이 고요해지고 어미의 숨이 길어졌다.<br>반쯤 잠든 틈에 방을 가로질렀다. 평생 벌인 의식 중 제일 이상한 의식이었다. 괴물의 방에서 괴물을 재우고 나온.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'S1', t:'표본 병 — 지키는 혼',
  x:`안 깨진 병 하나에 혼이 붙어 서 있다.<br><br>
    연구자다. 제가 담당하던 병 옆을 못 떠난다.<br>
    병 라벨에 이렇게 적혀 있다.<br><br>
    「위험 — 부화 임박」.`,
  o:[
    { l:'① 혼의 책임을 끝내 준다.', k:'gaze', dc:25,
      ok:`혼을 묶은 것은 미련이 아니라 책임이다. 책임은 일이 끝나야 풀린다.<br><br>병을 조심히 들어 냉동고 얼음 틈에 깊이 묻었다. 부화는 냉기 속에서 멎는다.<br>혼에게 고개 숙여 말했다. 당신 일은 끝났다. 혼이 처음으로 병에서 눈을 떼고, 복도 하나를 가리키고, 흩어졌다. 가리킨 복도는 비상계단으로 이어져 있었다. 마지막까지 안내가 일이었던 사람이다.`,
      ng:`말보다 손이 먼저 병에 닿았다.<br><br>혼이 막아섰다. 차가운 벽에 손을 짚은 것 같았다.<br>손을 거두고 한참을 마주 서 있었다. 신뢰는 혼에게도 순서가 있다. 말이 먼저였어야 했다.`,
      win:{ exp:23, dream:4 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 혼 곁에서 한 식경 같이 서 있는다.', k:'steady', dc:23,
      ok:`교대처럼 옆에 섰다. 혼이 흘깃 이쪽을 봤다.<br><br>한 식경을 같이 지키고 허리 숙여 인사했다.<br>떠나는 등 뒤로 혼이 비켜서 길을 내주는 기척이 있었다. 지키는 자들끼리의 예다.`,
      ng:`같이 서 있는데 병 안에서 무언가 뒤챘다.<br><br>혼이 유리에 바짝 붙었다. 이쪽은 할 수 있는 게 없었다.<br>그 무력감을 들고 물러났다. 혼은 밤새 혼자 지킬 것이다. 늘 그랬듯이.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-17, mind:-15 } }
  ] },

{ at:'S2', t:'뼈 벌판 — 깨끗한 고요',
  x:`오래된 뼈들이 땅에 반쯤 묻혀 있다. 억만 년 전의 죽음이다.<br><br>
    퇴마사가 아는 죽음에는 혼이 남는다.<br>
    여기는 아무것도 없다. 다 닳아 없어졌다.<br><br>
    이 고요가 이상하게 깨끗하다.`,
  o:[
    { l:'① 깨끗한 고요의 쓸모를 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`뼈 틈의 움푹한 자리는 소리를 먹는다. 바람도 갈라져 지나간다.<br><br>갈빗대 하나에 구멍이 나 바람 불면 낮게 운다. 우는 쪽이 바람 드는 쪽, 곧 냄새가 흘러가는 쪽이다.<br>그 뼈 곁에 야영했다. 소리는 먹히고 바람은 읽히는 자리. 뼈가 울 때마다 바람 방향을 고쳐 앉았다.<br><br>아무것도 없는 데서 쓸모를 읽는 눈이 생겼다. 빈 것이 더는 무섭지 않다. 빈 것은 그냥 조용한 도구다.`,
      ng:`고요가 너무 깊었다.<br><br>일행의 숨소리, 침 삼키는 소리까지 크게 들렸다.<br>서로의 소리에 다들 예민해졌다. 누가 뒤척일 때마다 다섯이 깼다. 고요도 지나치면 흉기다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 뼈 틈에 낀 철궤를 뒤진다.', k:'luck', dc:23,
      ok:`갈빗대 사이에 사육사의 철궤가 끼어 있었다.<br><br>비상식이 기름종이째 성하다.<br>궤 뚜껑 안쪽에 가족사진이 붙어 있었다. 떼지 않고 그대로 닫아 뼈 틈에 도로 밀어 넣었다. 먹을 것만 받았다.`,
      ng:`궤를 당기자 괴어 있던 뼈가 무너졌다.<br><br>뼈 무너지는 소리가 벌판에 길게 울렸다.<br>엎드려 숨을 죽였다. 벌판 저쪽에서 긴 그림자 하나가 소리의 끝을 밟고 지나갔다. 궤는 뼈 밑에 다시 묻혔다.`,
      win:{ exp:14, item:'말린 고기' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'사육사의 혼 — 급이 시간',
  x:`혼 하나가 벌판을 가로질러 걷는다. 빈 양동이를 들고.<br><br>
    급이 시간이다. 죽고 나서도 지킨다.<br>
    수풀의 그림자들이 그 길만은 비워 준다.<br><br>
    밥 주는 사람을 기억하는 것이다.`,
  o:[
    { l:'① 혼의 동선을 읽고 그 뒤를 따른다.', k:'gaze', dc:25,
      ok:`혼의 길은 짐승들이 비워 두는 길이다. 밥이 오는 길목에서는 사냥하지 않는다.<br><br>혼의 열 걸음 뒤를 따라 걸었다. 수풀의 그림자들이 길 양옆에서 기다리기만 했다.<br>벌판 반을 그렇게 건넜다. 혼이 빈 양동이를 기울이는 자리에서 그림자들이 모여들었고, 이쪽은 그 틈에 빠졌다. 몇십 년 전에 죽은 사람이 오늘도 다섯을 먹여 살렸다.`,
      ng:`혼이 어느 수풀 앞에서 문득 사라졌다. 급이가 끝난 것이다.<br><br>수풀 한가운데 다섯이 남았다.<br>그림자들이 흩어지기 전에 왔던 길을 되밟았다. 식은땀이 등을 다 적셨다. 남의 출근길에 얹혀 가는 건 거기까지만 하기로 했다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, spirit:-16 } },
    { l:'② 혼에게 말을 걸어 길을 묻는다.', k:'bond', dc:24,
      doom:{ title:'늦은 밥', what:'밥을 기다리던 것들에게 물려 끌려갑니다', dc:19, sec:40,
        text:`말을 걸자 혼이 멈춰 섰다. 몇십 년 만에 말을 건 사람이라서.<br><br>양동이가 멈추자 수풀이 술렁인다. 밥이 늦는 것이다.<br>밥이 안 오면 밥을 가지러 온다.<br><br>수풀이 일어선다. 혼이 미안한 얼굴로 이쪽을 본다. 늦은 밥 대신 이쪽이 끌려간다.`,
        dieText:`혼은 다시 걷는다. 양동이를 들고.<br><br>시간은 전처럼 지켜진다.<br>수풀은 전처럼 그 길을 비워 준다.` },
      ok:`말을 걸되 나란히 걸으며 걸었다. 급이를 끊지 않고.<br><br>혼은 대답 대신 걸으며 턱으로 한 방향을 가리켰다.<br>급이 길에서 갈라지는 샛길, 낡은 승강기 쪽 지름길이었다. 고맙다는 말에는 빈 양동이만 한 번 흔들렸다. 출근길 수다는 그 정도면 충분하다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'울타리 — 결계의 법',
  x:`울타리가 한 구간 끊어져 있다.<br><br>
    퇴마사의 눈에 울타리와 결계는 같은 것이다. 안팎을 가르는 뜻.<br>
    쇠가 끊겼으면 뜻으로 잇는다.<br><br>
    하룻밤이면 된다. 오늘 밤만.`,
  o:[
    { l:'① 끊긴 구간에 결계 한 겹을 세운다.', k:'gaze', dc:25, cost:{ mana:32 },
      ok:`끊긴 양 끝 기둥에 마력을 걸고 사이에 뜻을 팽팽히 당겼다. 막혀 있다, 는 뜻 하나를.<br><br>짐승 눈에는 없는 울타리가 어린다.<br>밤새 그 구간 밖에서 서성이는 소리가 났다. 발톱이 허공을 두 번 긁었다. 들어오지는 못했다. 아침에 결계를 걷으며 보니 기둥에 발톱 자국이 결계 높이까지만 나 있었다. 뜻도 쇠만큼 긁힌다.`,
      ng:`밤중에 그것들이 결계를 시험했다. 돌을 물어다 던진 것이다.<br><br>돌은 뜻을 모른다. 그대로 지나왔다.<br>뜻이 크게 흔들려 밤새 두 번을 다시 세웠다. 아침까지 마력이 바닥났다. 그것들은 돌 던지는 법을 어디서 배웠을까. 그 생각이 제일 무서웠다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 가시덤불을 끌어다 틈을 메운다.', k:'fix', dc:23,
      ok:`마른 가시덤불을 끌어다 끊긴 폭에 세 겹으로 쌓았다.<br><br>뜻보다 가시가 정직할 때도 있다.<br>밤에 덤불 흔들리는 소리가 두 번 나고 두 번 다 짧은 비명이 따랐다. 가시는 마력이 안 든다. 그게 가시의 미덕이다.`,
      ng:`덤불이 모자랐다. 한 겹은 성겼다.<br><br>새벽에 성긴 데가 반쯤 파헤쳐져 있었다.<br>들어오다 만 것이다. 왜 말았는지는 모른다. 그 모름이 종일 따라다녔다.`,
      win:{ exp:15, hp:5 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'물 — 숨을 재우는 의식',
  x:`물을 건너야 한다. 폭이 서른 걸음.<br><br>
    물속에서 심장은 빨라진다. 큰 것은 물의 떨림으로 듣는다.<br>
    다섯 심장이 물을 두드리며 건너는 셈이다.<br><br>
    퇴마사는 몸을 재우는 의식을 안다.`,
  o:[
    { l:'① 입수 전에 다섯의 숨을 재운다.', k:'gaze', dc:26, wake:1,
      ok:`물가에 둘러앉혀 숨 의식을 치렀다. 심장이 반 박자 느려질 때까지.<br><br>물에 들어가서도 물결이 거의 일지 않았다. 떠내려가는 나무토막 다섯처럼 건넜다.<br>물 밑으로 긴 그림자가 한 번 지나갔다. 나무로 알았는지 스치고 갔다.<br><br>몸을 재우는 의식이 짐승을 물리쳤다. 퇴마사의 상대가 혼만이 아니게 된 날이다.`,
      ng:`가운데쯤에서 하나가 참았던 숨을 터뜨렸다.<br><br>첨벙 소리가 물을 갈랐다.<br>전원 전력으로 헤엄쳤다. 물가에 오르는 마지막 발뒤꿈치 뒤로 물이 크게 갈라졌다 닫혔다. 젖은 채로 한참을 뛰었다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-28, spirit:-17 } },
    { l:'② 제일 좁은 목을 골라 빠르게 건넌다.', k:'evade', dc:24,
      ok:`폭이 열 걸음으로 주는 목을 찾아 하나씩 빠르게 건넜다.<br><br>짧은 소란 다섯 번이 긴 소란 한 번보다 낫다.<br>다 건너고 보니 넓은 쪽 물 가운데가 한 번 부풀었다 가라앉았다. 소란이 길었으면 만났을 것이다.`,
      ng:`좁은 목은 바닥이 뻘이었다.<br><br>셋째가 허벅지까지 빠졌다. 빼내느라 소란이 길어졌다.<br>물 저쪽에서 떨림이 다가오는 게 발바닥으로 느껴졌다. 마지막 둘은 거의 집어던지듯 건넸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

{ at:'S2', t:'큰 것 — 악이 아닌 것',
  x:`양치 너머에서 큰 것과 정면으로 마주쳤다. 눈이 등불만 하다.<br><br>
    퇴마사는 큰 악 앞에 서 본 적이 있다.<br>
    이것은 악이 아니다. 그냥 크다.<br><br>
    악이 아니면 퇴마사의 법은 하나다. 읽는 것.`,
  o:[
    { l:'① 그 눈에서 굶주림을 읽는다.', k:'gaze', dc:26,
      ok:`눈에 사냥의 조임이 없다. 배부른 눈이다. 남은 건 호기심.<br><br>호기심은 움직이는 것에만 붙는다. 바위가 되기로 했다.<br>다섯이 바위처럼 섰다. 큰 것이 코를 내려 하나씩 냄새 맡았다. 콧김에 외투가 펄럭였다. 그리고 지나갔다. 악이 아닌 것은 읽으면 산다.`,
      ng:`눈을 너무 오래 마주 봤다.<br><br>큰 것이 그걸 겨룸으로 받았다.<br>앞발이 땅을 굴렀다. 벌판이 한 번 뛰었고 다섯이 다 넘어졌다. 넘어진 것들에게는 흥미가 없는지 콧김만 뿜고 돌아섰다. 귀가 한나절 멍멍했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 시선을 내리고 옆으로 비켜 걷는다.', k:'steady', dc:25,
      ok:`눈을 내리깔고 옆으로 한 발씩 비켰다. 등을 안 보이고, 달아나는 꼴도 안 만들고.<br><br>큰 것의 시야에서 비스듬히 빠져나갔다.<br>다 빠져나가자 큰 것은 애초에 보던 데로 고개를 돌렸다. 이쪽은 풍경의 일부였다. 풍경으로 사는 것도 기술이다.`,
      ng:`비켜 걷다 하나가 발을 헛디뎌 주저앉았다.<br><br>주저앉는 움직임이 눈길을 당겼다.<br>큰 머리가 바로 위까지 내려왔다. 전원이 숨을 멈춘 채로 코 검사를 받았다. 지나갔다. 주저앉았던 일행은 한동안 일어나지 못했다. 다리가 풀려서.`,
      win:{ exp:17, dream:2 }, lose:{ spirit:-18, hp:-26 } },
    { l:'③ 뒤의 일행부터 하나씩 물린다.', k:'bond', dc:24,
      ok:`손짓으로 맨 뒤부터 한 사람씩 물렸다. 이쪽이 마지막.<br><br>큰 것의 눈은 무리가 줄어드는 걸 셈하지 못했다.<br>혼자 남았을 때가 제일 길었다. 마지막 한 발을 물러서자 양치가 시야를 닫아 줬다. 그제야 숨을 쉬었다.`,
      ng:`물리던 중에 하나가 마른 가지를 밟았다.<br><br>큰 것이 성큼 한 걸음을 디뎠다. 땅이 울렸다.<br>순서고 뭐고 없이 흩어졌다가 한참 뒤에 모였다. 수는 맞았다. 수를 세는 손이 떨렸다.`,
      win:{ exp:16, spirit:5 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S2', t:'옛 제단 — 바치던 자리',
  x:`정원 구석에 돌을 쌓은 제단이 있다. 사육사들이 만든 것이다.<br><br>
    큰 것에게 바치던 자리다. 가둘 수 없으면 모신다.<br>
    제단 뒤 바위에 금이 수십 줄 그어져 있다.<br><br>
    바친 횟수다.`,
  o:[
    { l:'① 금의 간격을 읽는다.', k:'gaze', dc:25,
      ok:`금의 간격이 뒤로 갈수록 좁아진다. 점점 자주 바쳐야 했던 것이다.<br><br>마지막 금 이후는 길게 비어 있다. 바칠 사람이 없어진 날부터.<br>빈 제단에는 큰 것이 제 발로 수금을 온다. 그러니 제단 근처가 이 정원에서 제일 위험한 자리다. 경건해 보이는 자리일수록 멀리 돌았다. 수십 줄 금이 그렇게 가르쳐 줬다.`,
      ng:`금을 세느라 제단 돌에 손을 짚었다.<br><br>돌이 미지근했다. 볕 탓이 아니었다.<br>발바닥으로 떨림이 올라왔다. 멀리서, 규칙적으로. 세던 금을 버리고 물러났다. 마지막 몇 줄은 끝내 못 셌다. 셀 필요도 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 제단의 제물 단지를 뒤진다.', k:'luck', dc:25,
      doom:{ title:'수금', what:'제단으로 온 큰 것에게 물려 끌려갑니다', dc:20, sec:36,
        text:`단지에 손을 넣었을 때 물그릇의 물이 떨렸다.<br><br>제단은 큰 것의 밥상이다. 밥상 위에 올라와 있는 것은 밥이다.<br>그림자가 해를 가린다.<br><br>물려 올라간다. 제단 위 하늘이 입 안으로 바뀐다.`,
        dieText:`제단 뒤 바위에 금이 하나 새로 그어졌다.<br><br>누가 그었는지는 모른다.<br>간격은 다시 벌어질 것이다. 당분간은.` },
      ok:`뒤지되 발바닥으로 땅울림을 재면서 했다.<br><br>단지 하나에 굳은 꿀이 반 넘게 남아 있었다. 바치던 것이다. 한 줌만 떴다.<br>울림이 커지기 전에 물러났다. 멀리서 돌아보니 큰 것이 제단에 머리를 숙이고 있었다. 반쯤 빈 단지에. 다 안 뜬 것이 다행이었다.`,
      win:{ exp:21, dream:3, item:'꿀 한 줌' } }
  ] },

{ at:'S2', t:'승강기 — 마지막 교대',
  x:`낡은 승강기 쇠문 앞에 혼이 서 있다. 사육사 복장이다.<br><br>
    문에 등을 대고, 기다린다. 마지막 교대를.<br>
    교대가 와야 자리를 뜨는 사람이다.<br><br>
    그의 발치에 수첩이 떨어져 있다.`,
  o:[
    { l:'① 수첩의 교대 문답을 찾아 치러 준다.', k:'gaze', dc:26, wake:1,
      ok:`수첩에 교대 수칙이 적혀 있었다. 문답이다. 구역 이상 없습니까. 이상 없습니다, 수고하셨습니다.<br><br>혼 앞에 똑바로 서서 그 문답을 치렀다.<br>혼이 모자를 벗었다. 수십 년 만의 퇴근이었다. 흩어진 자리에 쥐고 있던 비상 열쇠가 떨어졌다. 열쇠가 승강기 문을 열었다.<br><br>보내는 일이 곧 여는 일이었다. 퇴마사의 천도가 문을 연다. 그런 법이 경전 바깥에 하나 더 생겼다.`,
      ng:`문답 순서를 틀렸다. 수고하셨습니다, 를 먼저 말했다.<br><br>혼이 고개를 저었다. 처음부터.<br>다시 치르는 사이 벌판 어디선가 수풀 갈라지는 소리가 한 번 났다. 두 번째 문답은 떨리는 목소리로 치렀다. 혼은 끝까지 기다려 줬다. 교대는 원래 그렇게 하는 거라는 얼굴로.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 혼을 지나쳐 문을 억지로 연다.', k:'break', dc:25,
      ok:`혼을 비켜 지나 문틈에 지렛대를 걸었다. 문이 열렸다.<br><br>혼은 막지 않았다. 보기만 했다.<br>타고 올라가는 내내 그 눈이 등에 붙어 있었다. 문은 열렸고 마음 하나가 닫히지 않은 채 남았다. 언젠가 누가 저 교대를 치러 주기를. 그 바람을 두고 올라갔다.`,
      ng:`억지로 당긴 문이 길게 비명을 질렀다.<br><br>벌판이 들었다.<br>문을 도로 닫고 숨었다. 수풀 그림자 둘이 문 앞을 한참 서성이다 갔다. 혼은 그 내내 같은 자리에 서 있었다. 교대를 기다리며.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] }
]);
// ── 관상가 (내공)
kJob('physiog', 'S', [

{ at:'S', t:'일행 — 내려앉은 사색',
  x:`관상가는 아침마다 일행의 얼굴부터 본다. 버릇이다.<br><br>
    하나의 인당이 거멓다. 어제는 없던 그늘이다.<br>
    사색이 내려앉기 시작한 낯이다.<br><br>
    본인은 모른다. 그게 사색의 법이다.`,
  o:[
    { l:'① 사색이 어디서 오는지 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`사색은 예언이 아니라 계산이다. 몸이 먼저 아는 셈이 낯에 뜬 것이다.<br><br>그 사람의 자리를 봤다. 행렬 맨 뒤. 뒤가 비는 자리다.<br>자리를 가운데로 바꿨다. 저녁에 맨 뒤를 걷던 바위 옆에 긁힌 자국이 새로 나 있었다. 다음 날 그 사람 인당이 맑아져 있었다.<br><br>상은 정해진 것이 아니라 셈이다. 자리를 바꾸면 셈이 바뀌고 셈이 바뀌면 상이 바뀐다. 상을 고치는 관상가가 되기로 한 날이다.`,
      ng:`걱정이 앞서 사색을 입 밖에 냈다.<br><br>그 사람 낯이 그 자리에서 허옇게 질렸다. 겁이 사색 위에 겹쳤다.<br>상을 읽는 입은 무겁지 않으면 칼이 된다. 밤새 그 사람 곁을 지키며 제 입을 원망했다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-18, mind:-16 } },
    { l:'② 말없이 그 사람 곁에 붙어 걷는다.', k:'bond', dc:23,
      ok:`아무 말 없이 걸음을 맞췄다. 뒤가 비면 이쪽이 뒤를 봤다.<br><br>그 사람이 영문도 모르고 농을 걸어왔다. 받아 줬다.<br>저녁 무렵 인당의 그늘이 반으로 줄어 있었다. 곁이 약인 상도 있다.`,
      ng:`붙어 걷는 걸 그 사람이 눈치챘다.<br><br>왜 자꾸 보느냐고 물었다. 아니라고 하는 얼굴이 어설펐다.<br>그 사람이 제 얼굴을 자꾸 만지기 시작했다. 불안은 그렇게 옮는다. 그늘이 둘로 늘 뻔했다.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-16, mind:-15 } }
  ] },

{ at:'S', t:'어둠의 눈 — 조임',
  x:`어둠 속에서 눈 한 쌍이 이쪽을 보고 있다.<br><br>
    짐승의 눈에도 상이 있다.<br>
    사냥 전의 눈은 조여 있고 배부른 눈은 풀려 있다.<br><br>
    저 눈은 어느 쪽인가.`,
  o:[
    { l:'① 눈의 조임을 읽는다.', k:'gaze', dc:25,
      ok:`등불을 반 뼘 올려 빛을 더했다. 눈동자가 빛에 늦게 좁혀진다.<br><br>풀린 눈이다. 배가 부르다. 지금은 구경이다.<br>등만 보이지 않으면 안 쫓는다. 얼굴을 그쪽에 둔 채 게걸음으로 비켜 지나갔다. 눈은 끝까지 따라왔지만 몸은 안 따라왔다.`,
      ng:`어두워서 조임이 안 읽혔다.<br><br>못 읽으면 최악으로 치는 게 법이다. 사냥 전으로 쳤다.<br>밤새 번갈아 깨어 경계했다. 아침에 보니 그 자리에 뜯다 만 먹이가 있었다. 배부른 눈이었던 것이다. 밤잠만 잃었다. 잃은 게 잠뿐이라 다행이었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-17, spirit:-15 } },
    { l:'② 등을 돌려 빠르게 벗어난다.', k:'evade', dc:24,
      doom:{ title:'보인 등', what:'달아나는 등을 쫓아온 것에게 물려 끌려갑니다', dc:20, sec:40,
        text:`등을 돌리는 순간 어둠이 움직였다.<br><br>달아나는 등이 방아쇠다. 배가 불러도 도망은 쫓는다. 몸이 그렇게 생겨 먹었다.<br>발소리가 등 뒤에서 순식간에 커진다.<br><br>목덜미가 물린다. 끌려가며 생각한다. 얼굴을 보이고 있을 걸.`,
        dieText:`어둠 속의 눈이 제자리로 돌아갔다.<br><br>풀린 눈으로.<br>이제 정말 배가 부르다.` },
      ok:`돌아서려다 말았다. 등은 패다. 쥐고 있어야 한다.<br><br>얼굴을 보인 채 뒷걸음으로 물러났다.<br>얼굴 보이는 먹이는 비싸다. 눈은 따라왔지만 값을 치르러 오지는 않았다. 모퉁이를 돌고 나서야 등을 돌렸다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'낯빛 — 다섯 개의 등불',
  x:`그것들은 어둠 속에서 기색을 본다.<br><br>
    겁에 질린 낯빛은 등불처럼 밝다. 다섯이 겁에 질리면 등불이 다섯이다.<br>
    관상가는 제 얼굴부터 다스린다.<br><br>
    그다음이 남의 얼굴이다.`,
  o:[
    { l:'① 일행의 낯빛을 하나씩 가라앉힌다.', k:'gaze', dc:25, wake:1,
      ok:`겁의 상은 눈썹 안쪽과 입가에 선다. 한 사람씩 마주 서서 그 자리를 엄지로 문질러 폈다.<br><br>숨을 같이 쉬어 주며. 낯빛이 하나씩 가라앉았다.<br>어둠 속에서 등불 다섯이 꺼진 셈이다. 그 밤 기척들이 이쪽 자리를 영 못 찾았다.<br><br>상을 읽는 손이 상을 고치는 손이 됐다. 얼굴은 읽으라고만 있는 게 아니었다.`,
      ng:`넷은 가라앉았는데 하나가 자꾸 되살아났다.<br><br>겁은 전염이다. 되살아난 하나가 넷을 도로 밝혔다.<br>결국 그 하나를 가운데 세우고 넷이 둘러쌌다. 가려서라도 꺼야 하는 등불이 있다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-17, mind:-16 } },
    { l:'② 내공으로 제 기색을 끈다.', k:'gaze', dc:25, cost:{ qi:30 },
      ok:`내공을 낯 안쪽으로 거둬들였다. 얼굴의 김을 끄는 법이다.<br><br>어둠 속에서 이쪽만 없는 사람이 됐다.<br>그 몸으로 앞길을 정찰하고 왔다. 기척 둘의 자리를 보고도 들키지 않았다. 꺼진 등불은 보이지 않는다.`,
      ng:`기색을 너무 껐다.<br><br>돌아오니 일행이 이쪽을 못 알아보고 무기를 들었다.<br>하마터면 아군 창에 꿰일 뻔했다. 기색을 도로 켜는 데도 시간이 걸렸다. 얼굴이 남처럼 느껴지는 시간이.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-19, hp:-25 } }
  ] },

{ at:'S', t:'사체의 낯 — 마지막 표정',
  x:`앞선 팀의 사체다. 얼굴이 남아 있다.<br><br>
    관상가는 마지막 표정을 기록으로 읽는다.<br>
    놀람, 공포, 체념. 다 다른 정보다.<br><br>
    이 얼굴은 그 어느 쪽도 아니다.`,
  o:[
    { l:'① 마지막 표정을 끝까지 읽는다.', k:'gaze', dc:24,
      ok:`눈가에 놀람이 없다. 눈썹이 익숙하게 찌푸려져 있다. 알아봄의 상이다.<br><br>처음 본 것에게 당한 얼굴이 아니다. 아는 것에게 당한 얼굴이다. 두 번째 만남.<br>그것들은 한 번 본 먹이를 다시 찾아온다. 이쪽도 이미 한 번 눈이 마주친 것이 있다. 그날부터 야영 자리를 이틀 연속 같은 데 잡지 않았다. 다시 찾아올 수 없게.`,
      ng:`표정이 너무 생생했다.<br><br>읽기를 끝내고도 그 얼굴이 눈에 박혀 안 빠졌다.<br>그날 밤 꿈에서 그 얼굴이 이쪽을 보고 눈썹을 찌푸렸다. 아는 얼굴을 보는 눈으로. 식은땀에 깼다.`,
      win:{ exp:21, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 얼굴을 천으로 덮어 준다.', k:'steady', dc:23,
      ok:`읽을 것은 읽었다. 그다음은 사람의 일이다.<br><br>천을 덮고 돌로 눌렀다.<br>표정은 기록이지만 기록에도 덮을 때가 있다. 일행이 그 옆을 지날 때 아무도 얼굴을 안 봐도 되게 했다. 그게 오늘 관상가가 한 일 중 제일 나은 일이었다.`,
      ng:`덮는 손이 떨려 천이 자꾸 흘러내렸다.<br><br>세 번째에 겨우 덮였다.<br>떨린 건 손이 아니라 마음이었다. 그 얼굴의 상이 낯익어서. 누구와 닮았는지는 끝까지 생각 안 하기로 했다.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-17, mind:-15 } }
  ] },

{ at:'S', t:'무리의 낯 — 기우는 순간',
  x:`셋이 거리를 두고 따라온다.<br><br>
    무리에도 상이 있다. 셋의 낯이 제각각일 때는 아직 상의 중이다.<br>
    같은 쪽으로 기우는 순간 덮친다.<br><br>
    그 순간을 읽어야 한다.`,
  o:[
    { l:'① 셋의 머리 기울기를 잰다.', k:'gaze', dc:26,
      ok:`걸으며 곁눈으로 쟀다. 왼쪽 것은 이쪽 다리를, 가운데는 등짐을, 오른쪽은 길 앞을 본다.<br><br>아직 상의 중이다. 그러다 세 머리가 천천히 같은 각도로 기울기 시작했다.<br>기울기가 맞기 반 박자 전에 바위 틈으로 꺾어 들었다. 등 뒤에서 덮침이 허공을 쳤다. 셋의 낯이 다시 제각각이 됐다. 틀린 셈을 다시 하는 낯으로.`,
      ng:`곁눈질이 길었다. 돌아봤을 때는 이미 세 머리가 같은 쪽이었다.<br><br>이쪽이었다.<br>옆으로 몸을 던졌다. 외투 자락이 세 갈래로 찢겼다. 구르며 바위 틈에 끼어 들어 살았다. 셋은 틈 앞을 한참 서성이다 갔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 수풀로 숨어 따돌린다.', k:'hide', dc:24,
      doom:{ title:'세 쌍의 눈', what:'수풀에 미리 돌아가 있던 것에게 물려 끌려갑니다', dc:19, sec:40,
        text:`수풀로 미끄러져 들어갔다. 숨었다고 생각했다.<br><br>둘의 발소리가 수풀 밖을 지나간다. 둘.<br>셋이었다. 하나는 어디로 갔나.<br><br>수풀 안쪽에서 숨이 끼쳐 온다. 미리 와서 기다리고 있었다. 숨는 자리까지 상의가 끝나 있던 것이다.`,
        dieText:`수풀이 한참 흔들리다 멎었다.<br><br>셋의 발소리가 나란히 멀어진다.<br>서두르는 기색도 없이.` },
      ok:`숨기 전에 셋의 눈이 전부 이쪽에 있는 걸 확인했다.<br><br>보이는 데서 사라져야 찾는 데 시간이 든다.<br>세 눈이 다 이쪽을 보는 순간 수풀로 꺾었고, 수풀 속에서 바로 방향을 한 번 더 꺾었다. 셋은 첫 꺾임 자리만 한참 뒤졌다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'자리의 상 — 묵을 곳',
  x:`묵을 자리를 골라야 한다.<br><br>
    관상가는 땅도 얼굴로 본다. 자리에도 상이 있다.<br>
    바람이 고이고 그늘이 반듯한 자리는 좋은 상이다.<br><br>
    좋은 상은, 여기서는 문제다.`,
  o:[
    { l:'① 자리의 상을 읽고 흉상을 고른다.', k:'gaze', dc:25, wake:1,
      ok:`좋은 상의 자리는 짐승도 좋아한다. 길한 자리의 주인은 이미 있다.<br><br>일부러 상이 나쁜 자리를 골랐다. 바람이 갈라지고 바닥이 돌투성이인 자리.<br>불편하게 잤고 아무도 안 왔다. 길상의 자리 쪽에서는 밤새 무언가 드나드는 소리가 났다.<br><br>여기서는 길상이 흉상이고 흉상이 길상이다. 관상 책을 뒤집어 읽는 눈이 생겼다. 책은 사람 사는 땅에서 쓰였으니까.`,
      ng:`버릇대로 좋은 상의 자리를 골랐다.<br><br>밤에 두 번 손님이 왔다. 두 번 다 전원이 깨서 버텼다.<br>세 번째가 오기 전에 자리를 옮겼다. 돌밭으로. 아무도 불평하지 않았다. 잠자리 투정은 목숨값보다 싸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 바위 그늘 아무 데나 몸을 붙인다.', k:'luck', dc:23,
      ok:`고를 힘도 없었다. 제일 가까운 바위 그늘에 붙었다.<br><br>그 바위 틈에서 물이 배어 나오고 있었다. 맑다.<br>운이 상보다 나은 날도 있다. 물통을 채우고 그 자리에서 잤다. 바위가 등 뒤를 막아 준 것도 운이었다.`,
      ng:`붙은 바위 그늘이 하필 길목이었다.<br><br>새벽에 지나가는 발소리가 머리맡을 스쳤다.<br>전원이 숨을 죽인 채 그게 지나가기를 기다렸다. 지나갔다. 운에 기대면 운이 반, 식은땀이 반이다.`,
      win:{ exp:14, item:'맑은 물' }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'S', t:'발자국의 상',
  x:`발자국이 길게 이어져 있다.<br><br>
    걸음에도 상이 있다. 깊이, 간격, 뒤틀림.<br>
    걸음은 얼굴보다 정직하다. 얼굴은 꾸며도 걸음은 못 꾸민다.<br><br>
    이 걸음은 어딘가 한쪽으로 치우쳐 있다.`,
  o:[
    { l:'① 치우침을 읽는다.', k:'gaze', dc:24,
      ok:`자국이 가는 길마다 왼쪽으로 크게 돈다. 왼쪽을 믿지 못하는 걸음이다.<br><br>왼눈이 멀었거나 왼쪽을 다친 것이다.<br>이쪽이 접근하거나 피할 일이 생기면 왼쪽이 답이다. 그 법을 일행 모두에게 외우게 했다. 그것의 왼쪽이 우리의 오른쪽이라는 것까지. 그걸 헷갈리면 큰일 나니까.`,
      ng:`치우침을 거꾸로 읽었다.<br><br>오른쪽으로 돌아 피한다는 게 그것의 성한 눈 쪽으로 돈 셈이 됐다.<br>먼발치에서 정면으로 눈이 마주쳤다. 다행히 거리가 멀었다. 되짚어 달아나며 외웠다. 그것의 왼쪽, 우리의 오른쪽.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 제일 오래된 자국만 골라 따라간다.', k:'sense', dc:23,
      ok:`삭은 자국만 이어지는 길을 골랐다. 요즘 안 다니는 길이다.<br><br>길은 물가로 이어졌다. 예전 물자리다. 물이 마르자 짐승도 버린 길.<br>마른 물자리 웅덩이 바닥에 민물고기 몇이 말라붙어 있었다. 아직 성한 것을 거뒀다.`,
      ng:`삭은 자국 틈에 새 자국 하나가 섞여 있는 걸 놓쳤다.<br><br>버린 길을 요즘 다시 쓰는 것이 있다.<br>길 가운데서 그 새 자국의 주인이 남긴 흔적을 봤다. 아직 김이 나는 흔적이었다. 길을 버리고 둔덕을 탔다.`,
      win:{ exp:15, item:'민물고기' }, lose:{ hp:-25, spirit:-15 } }
  ] },

{ at:'S', t:'무너지는 낯 — 남은 선',
  x:`일행 하나가 무너지고 있다.<br><br>
    낯이 바뀌었다. 겁이 상을 지우고 있다.<br>
    저런 낯은 저 자신도 못 알아본다.<br><br>
    못 알아보는 낯으로는 아무 데도 못 간다.`,
  o:[
    { l:'① 무너진 얼굴에서 남은 선을 찾는다.', k:'gaze', dc:25, wake:1,
      ok:`상이 무너져도 끝까지 남는 선이 있다. 그 사람은 입매였다. 웃으면 왼쪽부터 올라가는 입매.<br><br>그 입매를 손가락으로 짚어 줬다. 너 아직 여기 있다.<br>입매가 떨리더니 왼쪽부터 올라갔다. 반쯤 웃은 것이다. 낯이 그 선을 따라 돌아왔다.<br><br>무너진 얼굴에서 남은 선을 찾는 눈이 생겼다. 사람을 포기하지 않는 관상. 그게 이 바닥에서 관상가가 있는 이유다.`,
      ng:`남은 선을 못 찾았다. 겁이 너무 깊었다.<br><br>낯선 얼굴이 이쪽을 마주 봤다. 아는 사람의 자리에서.<br>억지로 되돌리는 건 포기하고 손만 잡고 걸었다. 반나절 뒤에 저절로 돌아왔다. 시간이 찾은 선이었다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 내공으로 인당을 짚어 데운다.', k:'heal', dc:25, cost:{ qi:28 },
      ok:`식은 인당에 손가락을 대고 내공을 가늘게 흘렸다.<br><br>인당이 데워지자 눈에 초점이 돌아왔다.<br>겁은 이마부터 식는다. 식은 데를 데우면 사람이 돌아온다. 그 사람이 긴 숨을 쉬고 제 뺨을 두 번 쳤다. 돌아온 것이다.`,
      ng:`내공이 너무 셌다.<br><br>그 사람이 코피를 쏟았다. 겁 위에 놀람이 얹혔다.<br>지혈부터 하고 다시 달랬다. 약은 양이 반이다. 급한 손이 양을 잊었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-17 } }
  ] },

{ at:'S', t:'쓰러진 짐승 — 죽은 상, 산 상',
  x:`길 한가운데 짐승이 쓰러져 있다. 꽤 크다.<br><br>
    죽었으면 길이고 고기다. 살았으면 덫이다.<br>
    관상가는 죽은 얼굴과 죽은 척하는 얼굴을 가를 줄 안다.<br><br>
    사람 얼굴이라면.`,
  o:[
    { l:'① 짐승의 죽은 상을 가른다.', k:'gaze', dc:25,
      ok:`죽은 낯은 턱이 풀린다. 사람이든 짐승이든.<br><br>이것은 턱이 물려 있다. 눈꺼풀도 마르지 않았다.<br>산 것이다. 숨을 바닥까지 낮추고 기다리는 중이다. 크게 돌아서 지났다. 한참 뒤에 돌아보니 그것이 일어나 기지개를 켜고 반대쪽으로 갔다. 허탕 친 낚시꾼의 걸음으로.`,
      ng:`어두워서 턱이 안 보였다.<br><br>돌을 던져 봤다. 맞고도 안 움직였다.<br>안심하고 다가가는데 꼬리 끝이 반 뼘 움직였다. 죽은 것은 반 뼘도 안 움직인다. 던질 돌을 쥔 채로 뒷걸음질 쳤다. 그것은 끝까지 눈을 안 떴다. 서로 모른 척한 셈이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 죽었다 치고 다가가 고기를 거둔다.', k:'break', dc:24,
      doom:{ title:'죽은 척', what:'죽은 척하던 것에게 물려 끌려갑니다', dc:20, sec:38,
        text:`칼을 대려고 허리를 숙였다.<br><br>감겨 있던 눈이 떠졌다. 아주 천천히. 서두를 게 없다는 듯이.<br>죽은 척은 사냥의 반이다. 나머지 반이 지금이다.<br><br>팔이 물린다. 쓰러져 있던 몸이 일어나 이쪽을 문 채 수풀로 걸어 들어간다.`,
        dieText:`길 한가운데 짐승이 쓰러져 있다.<br><br>같은 자세로.<br>다음 사람에게도 길이고 고기로 보일 것이다.` },
      ok:`다가가다 멈췄다. 콧구멍 앞 흙이 규칙적으로 아주 얕게 밀리고 있었다.<br><br>숨이다. 죽은 코는 흙을 못 민다.<br>칼을 거두고 소리 없이 물러났다. 고기는 포기했다. 고기가 되는 것보다 낫다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'물에 비친 낯 — 제 상',
  x:`물을 긷다가 수면에 비친 제 얼굴을 봤다.<br><br>
    들어올 때와 다르다.<br>
    이 어둠이 상을 깎고 있다. 매일 조금씩.<br><br>
    남의 상만 보던 눈이 제 상 앞에 섰다.`,
  o:[
    { l:'① 제 상을 정면으로 읽는다.', k:'gaze', dc:26, wake:1,
      ok:`피하지 않고 읽었다. 깎인 데부터. 눈가의 웃음 자리가 깎였다. 볼의 살이 깎였다.<br><br>그리고 남은 데를 읽었다. 인당이 아직 서 있다. 눈의 심지가 아직 박혀 있다.<br>남은 데가 근본이다. 근본을 눈으로 확인한 상은 더 깎이지 않는다. 제가 저를 아는 얼굴은 어둠이 함부로 못 깎는다.<br><br>남의 상만 보던 눈이 제 상을 봤다. 관상가의 마지막 과목이다. 늦게 배웠지만 배웠다.`,
      ng:`깎인 데만 보였다.<br><br>남은 데를 찾기 전에 손으로 물을 흐트러뜨렸다.<br>일렁이는 조각 얼굴이 더 보기 싫었다. 그날 밤 제 얼굴을 만지며 잤다. 손이 기억하는 얼굴과 물이 보여 준 얼굴 사이에서.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-21, mind:-16 } },
    { l:'② 물을 흐리고 얼굴을 안 본다.', k:'steady', dc:24,
      ok:`손으로 물을 저어 흐렸다. 지금 볼 얼굴이 아니다.<br><br>나가서 본다. 해 아래에서, 거울로, 씻은 얼굴로.<br>그렇게 정하고 물만 길었다. 미루는 것도 다스림이다. 빚처럼 적어 두고 갚을 날을 정했으니까.`,
      ng:`흐려도 보였다. 일렁이는 사이사이로.<br><br>조각난 얼굴이 조각난 대로 따라왔다.<br>차라리 똑바로 볼 걸 그랬다. 미룬 빚은 밤에 꿈으로 왔다. 이자까지 붙어서.`,
      win:{ exp:15, mind:5 }, lose:{ spirit:-18, mind:-15 } },
    { l:'③ 서로의 얼굴을 봐 주기로 한다.', k:'bond', dc:23,
      ok:`물가에 다섯이 둘러앉아 서로의 얼굴을 봐 줬다. 남의 눈이 거울보다 정확하다.<br><br>너 아직 너다. 그 말이 다섯 번 돌았다.<br>다섯 낯이 눈에 띄게 펴졌다. 상은 혼자 지키는 것보다 서로 지켜 주는 게 싸다.`,
      ng:`하나가 다른 하나의 얼굴을 보고 멈칫했다.<br><br>숨긴다고 숨긴 멈칫이 다 보였다.<br>그 하나가 제 얼굴을 밤새 만졌다. 서로 보는 건 좋은데 보는 눈이 다 관상가는 아니라는 걸 늦게 생각했다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-17, mind:-15 } }
  ] },

{ at:'S', t:'얼굴 없는 것 — 몸이 얼굴이다',
  x:`그것과 정면으로 마주쳤다.<br><br>
    얼굴이 없다. 눈도, 코도, 읽을 자리가 하나도 없다.<br>
    관상 평생 처음 보는 백지다.<br><br>
    백지 앞에서 눈을 어디에 둬야 하나.`,
  o:[
    { l:'① 몸 전체를 얼굴로 읽는다.', k:'gaze', dc:26,
      ok:`얼굴이 없으면 몸이 얼굴이다. 어깨의 조임이 미간이고 꼬리의 각도가 입매다.<br><br>어깨가 풀려 있다. 꼬리가 낮다. 지금은 아니다, 라는 상이다.<br>숨을 낮추고 벽에 붙어 비켜섰다. 그것이 지나갔다. 지나가며 꼬리가 한 번 이쪽을 향해 섰다가 내려갔다. 알지만 안 문다, 는 뜻으로 읽었다. 맞기를 바랐고, 맞았다.`,
      ng:`읽을 자리를 찾아 눈이 헤매는 사이 그것의 어깨가 조여들기 시작했다.<br><br>백지가 구겨지는 것 같았다.<br>다 조여지기 전에 뒤로 빠졌다. 모퉁이 두 개를 꺾고 나서야 숨을 쉬었다. 백지도 화는 낸다. 그걸 몸으로 배웠다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-20, hp:-26 } },
    { l:'② 눈이 없으니 못 볼 거라 여기고 가까이 숨는다.', k:'hide', dc:25,
      doom:{ title:'백지', what:'얼굴 없는 것에게 물려 끌려갑니다', dc:20, sec:38,
        text:`눈이 없으니 보지 못할 것이다. 바로 옆 틈에 몸을 붙였다.<br><br>그것이 멈췄다. 얼굴 없는 머리가 정확히 이쪽을 향한다.<br>얼굴이 없다고 눈이 없는 게 아니었다. 몸 전체가 눈이었다.<br><br>틈에서 끌려 나온다. 읽을 수 없는 것에게, 다 읽힌 채로.`,
        dieText:`틈은 비었다.<br><br>얼굴 없는 것은 뒤도 안 돌아보고 갔다.<br>뒤를 볼 얼굴이 없기도 하다.` },
      ok:`가까이는 아니었다. 멀리, 바람 아래쪽 틈으로 숨었다.<br><br>얼굴이 없다고 눈이 없는 게 아니다. 어디에 눈이 있는지 모르면 전부가 눈이라고 쳐야 한다.<br>그것은 가까운 틈들을 하나하나 훑고 지나갔다. 먼 틈까지는 안 왔다. 전부가 눈이어도 다리는 하나다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'단체 사진 — 간 순서',
  x:`복도 벽에 연구진 단체 사진이 걸려 있다. 서른 명.<br><br>
    관상가는 사진의 상을 읽는다. 다 간 얼굴들이다.<br>
    그런데 상이 흐려진 정도가 저마다 다르다.<br><br>
    간 순서가 보인다.`,
  o:[
    { l:'① 가장 또렷한 얼굴을 찾는다.', k:'gaze', dc:25, wake:1,
      ok:`상이 흐린 순서가 간 순서다. 제일 또렷한 하나가 제일 오래 버틴 사람이다.<br><br>그 사람의 사진 속 자리를 봤다. 비상구 표시등 바로 아래. 제 자리를 아는 사람은 사진에서도 그 자리에 선다.<br>그가 버틴 길은 비상계단 쪽이라는 뜻이다. 가 보니 비상계단 문이 소화기로 괴어 열려 있었다. 나간 것이다. 어쩌면 끝까지. 괸 소화기는 그대로 두었다. 뒷사람 몫이다.<br><br>사진 속 상에서 시간을 읽는 눈이 생겼다. 멈춘 그림에도 순서는 남는다.`,
      ng:`서른 개의 상이 한꺼번에 눈으로 밀려들었다.<br><br>서른 번의 끝이 겹쳐서.<br>벽을 짚고 한참 서 있었다. 상을 읽는 눈은 양을 조절해야 한다. 한 번에 서른은 체한다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 사진 뒤 벽장을 뒤진다.', k:'luck', dc:23,
      ok:`사진 액자 뒤에 작은 벽장이 있었다. 구급함이다.<br><br>마른 약초 뭉치가 기름종이째 성했다.<br>구급함 위치를 사진으로 가려 둔 건 급할 때 제일 침착한 사람만 찾으라는 뜻이었는지도 모른다. 오늘은 이쪽이 그 사람이었다.`,
      ng:`벽장 문이 떨어지며 요란하게 울렸다.<br><br>복도 끝 어둠이 한 번 꿈틀했다.<br>빈손으로 반대쪽 방에 숨어 한 식경을 보냈다. 벽장 안에 뭐가 있었는지는 끝내 모른다.`,
      win:{ exp:14, item:'약초 뭉치' }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S1', t:'숙주의 낯 — 바뀐 상',
  x:`일행 하나의 얼굴이 그대로인데 상이 바뀌었다.<br><br>
    인당에 설익은 기색이 앉았다. 사람 것이 아닌 기색이다.<br>
    본인은 아무렇지 않다고 한다.<br><br>
    아무렇지 않은 게 제일 급한 신호다.`,
  o:[
    { l:'① 내공을 눈에 모아 기색의 뿌리를 짚는다.', k:'gaze', dc:26, cost:{ qi:32 },
      ok:`내공을 눈으로 끌어올려 기색의 줄기를 따라갔다. 인당에서 목 뒤로 이어진다.<br><br>목 뒤, 옷깃 밑. 아직 얕다. 얕을 때는 식히고 떼어 낼 수 있다.<br>치유 손과 함께 찬물과 칼끝으로 떼어 냈다. 손톱만 한 것이 바닥에 떨어져 꿈틀했다. 신으로 밟았다. 이른 눈이 사람 하나를 살렸다. 늦은 눈은 장례를 치렀을 것이다.`,
      ng:`기색의 줄기를 쫓는데 줄기가 숨었다.<br><br>들여다보는 걸 아는 것이다. 들킨 벌레는 깊이 숨는다.<br>자리를 못 짚었다. 그 일행을 밤새 지켜보는 수밖에 없었다. 내일은 더 깊어져 있을 것이다. 눈치 빠른 것이 제일 나쁘다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-20, hp:-26 } },
    { l:'② 그 사람의 짐을 바꾸고 뒤를 비우지 않는다.', k:'fix', dc:24,
      ok:`무거운 짐을 덜어 주고 행렬 가운데로 옮겼다. 뒤에는 늘 한 사람을 붙였다.<br><br>상이 더 나빠지는 속도가 눈에 띄게 줄었다.<br>들어앉은 것은 지친 몸에서 빨리 자란다. 몸을 아끼게 하는 것도 처치다. 칼만 처치가 아니다.`,
      ng:`짐을 바꾸자 그 사람이 서운해했다. 왜 나만 빼느냐고.<br><br>이유를 말할 수도 없었다.<br>서운함이 상을 한 겹 더 어둡게 했다. 마음의 그늘과 벌레의 그늘이 겹치니 읽기가 더 어려워졌다.`,
      win:{ exp:15, mind:5 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'배양조 유리 — 세 개의 낯',
  x:`배양조가 줄지어 있다. 유리마다 이쪽 얼굴이 비친다.<br><br>
    조마다 다르게 비친다. 하나는 웃는 낯으로, 하나는 자는 낯으로.<br>
    마지막 하나에는 아무것도 안 비친다.<br><br>
    유리는 같은 유리다.`,
  o:[
    { l:'① 상이 다르게 비치는 까닭을 읽는다.', k:'gaze', dc:25,
      ok:`유리가 아니라 안의 물이다. 물의 탁도가 비침을 바꾼다.<br><br>안 비치는 조만 물이 이상하게 맑다. 그리고 그 조만 안쪽에 반투막 같은 것이 드리워 있다.<br>막 뒤에 뭔가 있다. 비침이 없는 게 아니라 비침이 삼켜지는 것이다. 그 조에서 제일 먼 벽을 따라 지나갔다. 등 뒤에서 물 흔들리는 소리가 한 번 났다. 돌아보지 않았다.`,
      ng:`안 비치는 조에 바싹 다가가 들여다봤다.<br><br>맑은 물 안쪽에서 막이 천천히 이쪽으로 밀려 나왔다.<br>유리에 닿기 전에 물러났다. 막에 주름이 잡혀 있었다. 얼굴 자리에 주름이. 그 방을 나올 때까지 어떤 유리도 안 봤다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 유리를 일절 보지 않고 지난다.', k:'steady', dc:24,
      ok:`비치는 것들과 눈싸움할 이유가 없다. 바닥만 보고 걸었다.<br><br>조 사이를 다 지날 때까지 유리 쪽에서 몇 번 물 흔들리는 소리가 났다.<br>안 본 것은 없는 것이다. 적어도 지나가는 동안은. 그 법으로 다 건넜다.`,
      ng:`바닥만 보고 걷는데 바닥이 젖어 있었다.<br><br>젖은 바닥에 조의 유리가 비쳤다. 결국 본 셈이다.<br>비친 조 하나의 물이 일렁이고 있었다. 이쪽 걸음에 맞춰서. 걸음을 흩뜨리고 빠르게 나왔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-17, spirit:-16 } },
    { l:'③ 안 비치는 조를 두드려 확인한다.', k:'break', dc:25,
      doom:{ title:'맑은 물', what:'조를 깨고 나온 것에 감겨 끌려갑니다', dc:20, sec:36,
        text:`손가락을 세워 유리를 두드렸다. 톡.<br><br>맑은 물이 한순간에 탁해졌다. 막이 유리로 달려들었다.<br>유리가 버티지 못했다.<br><br>쏟아진 물과 함께 감겨 올라간다. 마지막으로 본 유리 조각에 이쪽 얼굴이 제대로 비쳤다. 이제야.`,
        dieText:`깨진 조의 물이 바닥에 번져 있다.<br><br>물 자국이 복도로 길게 이어진다.<br>남은 조들의 유리에는 다시 아무도 안 비친다.` },
      ok:`두드리려다 조 아래 배수 밸브를 봤다. 두드리는 것보다 나은 확인법이다.<br><br>밸브를 천천히 돌려 물만 뺐다.<br>물이 빠지자 막이 쪼그라들며 바닥에 내려앉았다. 마른 허물이었다. 속이 빈. 주인은 오래전에 나간 것이다. 어디로 나갔는지는 조 위쪽 뚫린 덮개가 말해 줬다. 천장 쪽이었다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'산 핏자국 — 아픈 걸음',
  x:`복도에 산 핏자국이 점점이 이어진다. 다친 것이 지나갔다.<br><br>
    관상가는 핏자국에서도 걸음의 상을 읽는다.<br>
    아픈 짐승의 걸음에는 표정이 있다.<br><br>
    이 걸음의 표정이 이상하다.`,
  o:[
    { l:'① 핏자국 간격의 표정을 읽는다.', k:'gaze', dc:25,
      ok:`간격이 좁아지다가 어느 지점부터 고르게 넓어진다.<br><br>아픔이 나은 게 아니다. 아픔을 참기로 한 것이다. 참는 걸음은 영리한 걸음이다.<br>영리하고 다친 것은 쫓기를 그만두고 기다리기를 고른다. 핏자국이 향한 직선 길을 버리고 크게 돌았다. 돌아간 길에서 내려다보니 직선 길 끝 그늘에 웅크린 윤곽이 보였다. 기다리고 있었다.`,
      ng:`넓어진 간격을 회복으로 읽었다.<br><br>멀리 갔겠거니 하고 직선 길로 들어섰다.<br>그늘에서 숨소리가 들려 멈췄다. 매복의 가장자리였다. 발끝으로 물러나는 다섯 걸음이 오늘 하루에서 제일 길었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, spirit:-16 } },
    { l:'② 핏자국으로 상처 깊이를 재어 알린다.', k:'heal', dc:23,
      ok:`방울의 크기와 색으로 쟀다. 깊지만 느리게 새는 상처다. 오래간다.<br><br>오래 다친 채 돌아다닌다는 뜻이다. 사나운 채로.<br>일행의 창끝을 그쪽 어깨 높이에 맞추게 했다. 다친 데를 또 맞으면 짐승은 물러난다. 만날 일이 없기를 빌면서 준비는 만날 것처럼 했다.`,
      ng:`색을 잘못 읽었다. 마른 피를 새 피로 봤다.<br><br>바로 근처에 있다고 판단해 반나절을 돌아갔다.<br>허탕이었다. 피는 며칠 전 것이었다. 다리품만 팔았다. 지친 다리가 저녁 내 무거웠다.`,
      win:{ exp:15, hp:5 }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S1', t:'어미의 상 — 서로 읽는다',
  x:`어미의 방이다. 알 위에 그 큰 몸이 엎드려 있다.<br><br>
    어미에게도 낯이 있다. 그리고 어미도 읽는다.<br>
    들어서는 것들의 상을. 하나하나.<br><br>
    읽는 자와 읽는 자가 마주쳤다.`,
  o:[
    { l:'① 어미가 읽는 법을 거꾸로 읽는다.', k:'gaze', dc:26, wake:1,
      ok:`어미의 눈이 다섯을 훑는 순서를 봤다. 손에 든 것, 어깨의 긴장, 그다음이 눈이다.<br><br>겁은 안 본다. 적의만 가린다. 알 품는 때는 먹이보다 위협이 먼저니까.<br>전원 무기를 등 뒤로 돌리고 어깨를 풀게 했다. 적의가 지워진 상으로 벽을 따라 걸었다. 어미는 끝까지 보기만 했다. 읽히는 줄 알면서 읽혔다. 읽을거리를 이쪽이 골라서.<br><br>읽는 자를 읽는 법이 생겼다. 시선의 수 싸움에서 반 수 앞서는 눈이다.`,
      ng:`읽는 중에 일행 하나의 손이 창을 꽉 쥐었다. 저도 모르게.<br><br>어미가 일어섰다. 방이 반쯤 어두워졌다. 그 몸이 빛을 가려서.<br>창을 바닥에 내려놓게 하고 전원 정지했다. 어미가 도로 엎드릴 때까지의 시간을 누구도 재지 못했다. 영원이었다고만 다들 말했다.`,
      win:{ exp:25, dream:4 }, lose:{ spirit:-21, hp:-27 } },
    { l:'② 내공으로 다섯 기색을 바람으로 바꾼다.', k:'gaze', dc:25, cost:{ qi:35 },
      ok:`내공을 다섯에게 나눠 걸어 기색을 지웠다. 사람의 김을 끄고 지나가는 바람의 결만 남겼다.<br><br>어미의 눈이 다섯을 스쳐 지나갔다. 바람을 보는 눈으로.<br>방을 다 건널 때까지 바람이었다. 문턱을 넘고 기색을 돌려받자 다섯이 한꺼번에 식은땀을 쏟았다. 바람은 땀이 없으니까, 참았던 것이다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-19, hp:-26 },
      ng:`기색이 반만 지워졌다. 바람인데 발소리가 있는 바람이 됐다.<br><br>어미가 고개를 갸웃했다. 처음 보는 것을 보는 낯으로.<br>갸웃하는 동안 빠르게 건넜다. 호기심이 경계로 바뀌기 전에. 문턱에서 뒤를 보니 어미가 아직 그 각도로 허공을 보고 있었다.` }
  ] },

{ at:'S1', t:'환풍구 — 어둠의 기색',
  x:`관이 세 갈래다. 어느 쪽이든 질러갈 수는 있다.<br><br>
    관상가는 어둠에도 기색이 있다고 배웠다.<br>
    밝은 어둠과 탁한 어둠.<br><br>
    탁한 어둠에는 숨이 들어 있다.`,
  o:[
    { l:'① 세 관의 기색을 가른다.', k:'gaze', dc:25,
      ok:`들머리에 서서 하나씩 들여다봤다. 왼쪽은 탁하다. 가운데는 더 탁하다.<br><br>오른쪽만 어둠이 맑다. 바람이 통하고 아무것도 숨 쉬지 않는 어둠.<br>오른쪽으로 전원이 기었다. 다 빠져나온 뒤에 가운데 관 쪽에서 쇠 긁는 소리가 길게 났다. 탁한 어둠의 주인이 몸을 뒤집는 소리였다.`,
      ng:`사흘 치 피로가 눈을 흐렸다. 세 어둠이 다 같아 보였다.<br><br>제일 넓은 관을 골랐다. 반쯤 기었을 때 허물 조각이 손에 밟혔다.<br>주인이 쓰는 관이라는 뜻이다. 돌아 나오기엔 늦어 숨을 죽이고 마저 기었다. 출구가 그렇게 반가운 적이 없었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 바람 소리가 시원한 관으로 바로 든다.', k:'sense', dc:25,
      doom:{ title:'고른 숨', what:'관 속의 것에게 발목을 물려 끌려 들어갑니다', dc:20, sec:38,
        text:`바람 소리가 제일 고른 관으로 들었다.<br><br>반쯤 기었을 때 알았다. 바람은 이렇게 고르게 불지 않는다.<br>고른 것은 숨이다. 큰 몸이 느리게 쉬는.<br><br>발목이 물린다. 관 안쪽 어둠으로 끌려 들어간다. 숨소리가 점점 커진다.`,
        dieText:`관에서 바람 소리가 난다.<br><br>고르게. 아까보다 조금 느리게.<br>배부른 숨은 느려진다.` },
      ok:`들기 전에 등불 연기를 관 어귀에 흘렸다.<br><br>연기가 빨려 들면 바람이고 멎으면 숨이다. 한 관에서 연기가 멎었다. 그 고른 소리는 숨이었다.<br>연기가 시원하게 빨려 드는 옆 관으로 들었다. 기는 내내 옆 관에서 고른 소리가 벽 너머로 따라왔다. 숨과 나란히 기어서 지나간 셈이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'기록철 — 표본의 상',
  x:`연구 기록철에 그것들의 사진이 철해져 있다.<br><br>
    산 채로 찍힌 것과 표본이 된 것.<br>
    관상가의 짐승 상 공부가 여기 다 있다.<br><br>
    책상 앞 의자가 아직 따뜻한 것 같은 방에서.`,
  o:[
    { l:'① 사진으로 덮치기 전의 상을 외운다.', k:'gaze', dc:25,
      ok:`연속 촬영된 장이 있었다. 덮치기 직전의 몸.<br><br>목이 낮아지고 어깨가 조이고 꼬리 끝이 선다. 그 순서다. 목이 먼저다.<br>전조 세 가지를 눈에 새겼다. 사흘 뒤 복도에서 실물의 목이 낮아지는 걸 보고 반 박자 먼저 기둥 뒤로 꺾었다. 덮침이 허공을 쳤다. 죽은 연구자들의 공부가 산 사람을 살렸다.`,
      ng:`사진 속 눈과 너무 오래 마주 봤다.<br><br>종이인 걸 아는데도 목덜미가 서늘했다.<br>그날 밤 꿈에 그 눈이 나왔다. 종이 밖으로 반쯤 나온 채로. 공부에도 요령이 필요하다. 눈은 빼고 몸만 볼 것.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 전조를 그림으로 그려 일행에게 돌린다.', k:'fix', dc:23,
      ok:`목, 어깨, 꼬리. 세 전조를 수첩 장에 큼직하게 그려 찢어 돌렸다.<br><br>글 모르는 사람도 그림은 안다.<br>다섯 눈이 같은 전조를 보게 됐다. 관상가 하나의 눈보다 다섯의 눈이 넓다. 이제 어느 방향에서 목이 낮아져도 누군가는 본다.`,
      ng:`그림 솜씨가 문제였다.<br><br>목이 낮아진 그림을 보고 하나가 물었다. 이거 자는 거냐고.<br>말로 다시 설명했다. 그림은 걷고 설명이 돌았다. 늦게나마 다섯이 외우긴 했다. 자는 게 아니라 덮치는 거라고.`,
      win:{ exp:15, mind:5 }, lose:{ mind:-15, spirit:-15 } }
  ] },

{ at:'S2', t:'알 — 때의 기색',
  x:`둥지 가장자리에 알들이 묻혀 있다.<br><br>
    알에도 기색이 있다. 곧 깰 것과 아직 먼 것.<br>
    껍질의 빛, 밑의 흙이 눌린 정도.<br><br>
    관상은 얼굴이 아니라 때를 보는 것이다.`,
  o:[
    { l:'① 알들의 때를 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`셋이 곧 깬다. 껍질 빛이 안에서부터 짙어졌다.<br><br>알이 깨는 날 어미는 평생 제일 사납다.<br>오늘내일이다. 이 구역에 이틀 머물 예정을 반나절로 줄였다. 밤길이 무서워도 깨는 날의 어미보다는 낫다. 떠나는 등 뒤에서 껍질에 금 가는 소리가 들린 것 같았다. 걸음을 더 서둘렀다.<br><br>사람 아닌 것의 때를 읽는 눈이 생겼다. 상은 결국 때를 보는 일이었다. 얼굴은 그 창일 뿐이고.`,
      ng:`기색을 읽는데 알 하나가 흔들렸다. 안에서 도는 소리가 났다.<br><br>알 속의 것이 이쪽 기색을 느낀 것이다. 껍질 너머로.<br>둥지 전체가 웅성이기 시작했다. 어미가 깨기 전에 구역을 빠져나왔다. 뛰어서. 읽는 눈도 읽힌다. 알에게조차.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-19, hp:-26 } },
    { l:'② 둥지의 바람 아래로 크게 돈다.', k:'evade', dc:24,
      ok:`읽을 것도 없이 돌기로 했다. 바람 아래, 냄새가 닿지 않는 호를 그리며.<br><br>반나절이 더 걸렸다.<br>지나고 나서 멀리 둥지 쪽 하늘로 새 떼가 피어오르는 걸 봤다. 깬 것이다. 반나절 값을 제대로 한 우회였다.`,
      ng:`호가 작았다. 바람이 도는 걸 몰랐다.<br><br>둥지 쪽에서 긴 울음이 일었다. 냄새가 닿은 것이다.<br>호를 두 배로 벌려 뛰었다. 울음은 따라오지 않았다. 알 곁을 못 떠나는 게 어미의 약점이자, 이쪽의 운이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S2', t:'무리의 눈 — 서열',
  x:`수풀 끝에서 셋과 대치했다. 거리는 스무 걸음.<br><br>
    셋 다 이쪽을 본다. 하지만 같은 눈이 아니다.<br>
    무리에는 서열이 있고 서열은 눈에 뜬다.<br><br>
    누가 먼저 오는지 읽어야 한다.`,
  o:[
    { l:'① 눈빛의 서열을 읽는다.', k:'gaze', dc:26,
      ok:`가운데가 크다. 큰 것이 머리인 줄 알기 쉽다.<br><br>눈이 먼저 움직이는 건 왼쪽 것이다. 가운데는 왼쪽을 곁눈으로 확인하고서야 움직인다. 왼쪽이 선봉이고 머리다.<br>왼쪽 것만 똑바로 봤다. 선봉이 덤비려다 멈칫했다. 저를 아는 눈을 만난 것이다. 읽히는 먹이는 비싸다. 셋이 값을 포기하고 물러갔다.`,
      ng:`큰 가운데를 머리로 읽고 그쪽만 경계했다.<br><br>왼쪽 것이 먼저 왔다.<br>소매가 찢기며 옆으로 굴렀다. 일행의 창대가 선봉의 옆구리를 치고서야 셋이 물러났다. 큰 것이 머리라는 법은 사람 동네 법이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 등을 지키며 천천히 물러난다.', k:'steady', dc:25,
      doom:{ title:'반 발', what:'뒤처진 한 사람을 노린 것에게 물려 끌려갑니다', dc:20, sec:40,
        text:`얼굴을 셋에게 준 채 전원이 물러났다. 법대로.<br><br>맨 뒤가 반 발 처졌다. 맨 뒤는 이쪽이었다. 뒤를 봐 주느라.<br>그 반 발을 셋이 안 놓쳤다.<br><br>세 방향에서 한꺼번에 좁혀 든다. 서열은 읽었는데 거리를 못 읽었다.`,
        dieText:`수풀이 닫혔다.<br><br>남은 넷은 등을 맞댄 채 밤까지 서 있었다.<br>셋은 다시 오지 않았다. 올 이유가 없어져서.` },
      ok:`물러나되 한 덩이로 물러났다. 어깨와 어깨를 붙이고.<br><br>처지는 사람이 없게 걸음을 소리 내어 맞췄다. 하나, 둘.<br>셋은 끊어 낼 반 발을 끝내 못 찾았다. 수풀이 시야를 닫아 줄 때까지 스무 걸음이 이백 걸음 같았다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S2', t:'오두막 거울 — 사육사의 버릇',
  x:`사육사 오두막에 거울이 걸려 있다.<br><br>
    매일 보던 거울에는 보던 버릇이 남는다.<br>
    유리 한구석만 뿌옇게 닳아 있다.<br><br>
    매일 같은 자리에 얼굴을 대고 본 것이다.`,
  o:[
    { l:'① 닳은 자리의 높이와 각도를 읽는다.', k:'gaze', dc:25,
      ok:`닳은 자리는 얼굴 높이가 아니다. 목 높이다. 왼쪽으로 기운 각도.<br><br>사육사는 매일 제 목 왼쪽을 확인했다. 물린 자국을.<br>물리고도 산 사람이 있었다는 뜻이다. 서랍의 일지를 뒤지니 있었다. 「긁힌 날 — 잿물로 씻고 마른 풀 묶음을 댈 것. 사흘이면 가라앉음.」 처치법과 함께 그 마른 풀 묶음이 서랍에 남아 있었다. 산 사람의 유산이다.`,
      ng:`닳은 자리에 제 목을 비춰 봤다.<br><br>괜한 짓이었다. 성한 목인데도 자국이 있는 것처럼 보였다.<br>남의 버릇을 제 몸으로 따라 하면 남의 겁까지 따라온다. 거울을 등지고 방을 나왔다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ spirit:-18, mind:-15 } },
    { l:'② 오두막 찬장을 뒤진다.', k:'luck', dc:23,
      ok:`찬장 안쪽에 단지가 하나. 굳은 꿀이 반 넘게 남아 있었다.<br><br>사육사의 단것이다. 한 줌 떴다.<br>단지 옆에 찻잔이 둘 엎어져 있었다. 둘이서 마시던 자리다. 다른 한 사람 몫으로 꿀은 반 넘게 남겨 뒀다.`,
      ng:`찬장 문이 떨어지며 선반째 쏟아졌다.<br><br>깨지는 소리가 벌판으로 퍼졌다.<br>오두막 뒤 수풀이 한 번 크게 흔들렸다. 다들 바닥에 엎드려 한 식경을 보냈다. 찬장에 뭐가 있었는지는 깨진 조각만 안다.`,
      win:{ exp:14, item:'꿀 한 줌' }, lose:{ hp:-25, mind:-14 } }
  ] },

{ at:'S2', t:'큰 것의 낯 — 산의 상',
  x:`양치 위로 큰 것의 머리가 솟아 있다. 이쪽을 봤다.<br><br>
    산 같은 얼굴에도 상은 있다.<br>
    크기에 눌려 못 읽을 뿐이다.<br><br>
    관상가가 눌리면 다섯이 다 눌린다.`,
  o:[
    { l:'① 내공을 눈에 모아 그 상을 끝까지 읽는다.', k:'gaze', dc:26, cost:{ qi:38 }, wake:1,
      ok:`내공을 눈으로 올려 크기를 벗겨 내고 상만 봤다.<br><br>눈가 주름이 깊다. 늙었다. 윗니가 듬성하다. 무른 먹이만 삼키는 입이다.<br>늙고 배부르고 귀찮은 상이다. 위협만 안 하면 안 문다. 그 판독을 일행에게 전하자 다섯의 낯빛이 절반쯤 돌아왔다. 큰 것은 다섯을 구경하다 제 길로 갔다.<br><br>산만 한 상대의 상을 읽어 낸 눈이다. 크기는 상을 가리지 못한다. 이제는.`,
      ng:`내공이 눈에서 흔들렸다. 상이 두 겹으로 보였다.<br><br>읽기를 포기하고 정석대로 했다. 전원 엎드려 바위 되기.<br>큰 것이 한참 내려다보다 갔다. 읽었으면 서서 보낼 수 있던 시간을 진흙에 엎드려 보냈다. 내공은 눈보다 숨이 먼저라는 걸 배웠다.`,
      win:{ exp:25, dream:4 }, lose:{ spirit:-19, hp:-27 } },
    { l:'② 읽지 않고 바위가 된다.', k:'steady', dc:24,
      ok:`크기 앞에서는 읽는 것보다 멈추는 게 빠르다. 전원이 그 자리에 굳었다.<br><br>큰 것의 눈은 움직임을 따라간다. 움직임이 없으면 풍경이다.<br>콧김 두 번 값으로 지나갔다. 풍경 노릇도 할 만했다. 다리가 후들거리는 풍경이긴 했지만.`,
      ng:`굳는 게 반 박자 늦은 사람이 있었다.<br><br>큰 머리가 그 사람 쪽으로 기울었다.<br>전원이 숨을 끊고 버텼다. 머리가 도로 올라갈 때까지. 그 사람은 그날 저녁까지 손이 떨려 숟가락을 못 들었다.`,
      win:{ exp:16, dream:2 }, lose:{ spirit:-18, hp:-26 } }
  ] },

{ at:'S2', t:'물속의 낯 — 겨냥하는 눈',
  x:`물을 건너는데 물밑에서 올려다보는 낯이 있다.<br><br>
    일렁여서 읽을 수가 없다.<br>
    사람인지 아닌지조차.<br><br>
    읽기 전에는 멈추지 않는 게 물의 법이다.`,
  o:[
    { l:'① 일렁임 속에서 상을 읽는다.', k:'gaze', dc:26,
      ok:`걸으면서 읽었다. 눈 사이가 넓다. 사람이 아니다.<br><br>그리고 올려다보는 눈이 아니라 겨냥하는 눈이다. 겨냥은 직선을 좋아한다.<br>직선을 버리고 지그재그로 꺾으며 건넜다. 물가에 오르는 순간 등 뒤 물이 기둥처럼 터졌다. 겨냥이 빗나간 자리는 방금 전까지 걷던 직선 위였다.`,
      ng:`일렁임 속 낯을 사람으로 읽었다. 빠진 사람인가 싶어 반 박자 멈췄다.<br><br>그 반 박자에 발 옆 물이 터졌다.<br>남은 거리를 반쯤 날듯이 건넜다. 물속에서 사람 얼굴로 보이는 것은 사람이 아니다. 그 법을 몸에 새겼다. 젖은 몸에.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, spirit:-17 } },
    { l:'② 내공으로 물낯을 눌러 잔잔하게 한다.', k:'gaze', dc:25, cost:{ qi:33 },
      ok:`손바닥을 수면에 대고 내공을 깔았다. 한 호흡 동안 물이 유리처럼 잔잔해졌다.<br><br>그 한 호흡에 다 읽었다. 크기, 깊이, 머리가 향한 쪽.<br>머리 반대쪽으로 크게 돌아 건넜다. 그것은 끝까지 엉뚱한 직선을 겨냥하고 있었다. 잔잔한 물은 좋은 종이다. 한 호흡짜리 종이지만.`,
      ng:`내공이 과했다. 눌린 물이 가장자리에서 더 크게 출렁였다.<br><br>물밑의 낯이 출렁임을 타고 이쪽으로 미끄러져 왔다.<br>읽기고 뭐고 없이 물러났다. 다른 목으로 돌아가 건넜다. 반나절을 더 써서. 물을 누르는 손은 반만 눌러야 한다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-18, hp:-26 } },
    { l:'③ 읽지 않고 최단으로 건넌다.', k:'evade', dc:24,
      ok:`못 읽는 것과 눈싸움할 시간에 다리를 썼다.<br><br>제일 좁은 목으로, 전원 한 번에, 전력으로.<br>물이 뒤에서 한 번 일렁였지만 따라오지 못했다. 겨냥할 틈을 안 준 것이다. 가끔은 다리가 눈보다 빠르다.`,
      ng:`전력 질주 중에 하나가 물풀에 걸려 넘어졌다.<br><br>물보라가 크게 일었다.<br>둘이 돌아가 끌어 일으키고 끌다시피 건넜다. 물가에 오르자마자 그 자리에 다 쓰러졌다. 물밑의 낯이 어디까지 왔었는지는 아무도 안 돌아봤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S2', t:'매인 짐승 — 겁이 보는 쪽',
  x:`울타리 말뚝에 짐승 한 마리가 매여 있다. 급이용으로 기르던 것이다.<br><br>
    살아 있다. 겁에 질린 상이다.<br>
    겁먹은 눈은 거짓말을 못 한다.<br><br>
    무서운 쪽을 본다.`,
  o:[
    { l:'① 그 눈이 보는 쪽을 읽는다.', k:'gaze', dc:25,
      ok:`매인 짐승의 눈은 이쪽을 안 본다. 이쪽 뒤 수풀을 본다.<br><br>그 수풀에 기다리는 것이 있다. 이 짐승은 미끼다. 사람을 잡는 덫의 미끼.<br>덫을 놓은 건 사람이 아니다. 그것들이 미끼 쓰는 법을 안다는 뜻이다. 덫을 크게 돌아 지났다. 수풀 속 기다림이 길어지는 걸 등으로 느끼면서.`,
      ng:`눈이 보는 쪽을 등지고 섰다. 짐승을 살피느라.<br><br>등진 쪽이 바로 그쪽이었다.<br>수풀이 갈라지는 소리에 옆으로 굴렀다. 덮침이 어깨를 스쳤다. 매인 짐승이 길게 울었다. 경고였는지도 모른다. 아까부터.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, spirit:-17 } },
    { l:'② 줄을 끊어 풀어 준다.', k:'bond', dc:24,
      doom:{ title:'미끼', what:'미끼를 지키던 것에게 물려 끌려갑니다', dc:19, sec:40,
        text:`줄을 끊자 짐승이 크게 울며 내달렸다.<br><br>그 울음을 수풀이 기다리고 있었다.<br>미끼가 울면 덫이 닫힌다. 짐승은 달아나고 덫 안에 선 것은 이쪽이다.<br><br>수풀에서 나온 것에게 물려 끌려간다. 미끼는 바꾸면 그만이니까.`,
        dieText:`말뚝에는 다시 줄이 매여 있다.<br><br>미끼는 새것이다.<br>겁먹은 눈이 수풀 쪽을 본다.` },
      ok:`끊기 전에 짐승의 입을 천으로 감았다. 울음이 방아쇠라는 건 저 눈이 말해 줬다.<br><br>줄을 끊고 안은 채 스무 걸음을 걸어 바람 아래에서 놓았다.<br>짐승은 소리 없이 벌판으로 사라졌다. 미끼 없는 덫 곁을 지나는데 수풀 안쪽에서 길고 실망한 숨이 새어 나왔다. 덫도 허탕이 있다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'승강기 거울 — 등 뒤를 보는 눈',
  x:`승강기 안쪽에 낡은 거울이 붙어 있다.<br><br>
    다섯이 탔다. 관상가는 거울부터 본다. 버릇이다.<br>
    수를 세고 상을 살핀다.<br><br>
    거울은 등 뒤까지 보여 준다.`,
  o:[
    { l:'① 거울 속 수와 상을 점검한다.', k:'gaze', dc:26, wake:1,
      ok:`다섯. 수가 맞다. 상도 다섯 다 제 상이다.<br><br>문이 닫히기 직전, 거울 귀퉁이에 여섯째 것이 비쳤다. 승강기 밖, 등 뒤 사각에서 낮게 달려드는 것.<br>닫아, 소리치며 닫힘 손잡이를 당겼다. 쇠문이 물리는 것과 발톱이 긁는 것이 거의 동시였다. 문 바깥쪽에 긴 자국 세 줄 값으로 다섯이 올라갔다.<br><br>거울로 등 뒤를 읽는 버릇이 목숨을 샀다. 관상가의 눈은 이제 앞뒤를 다 본다.`,
      ng:`수를 세는 데 정신이 팔려 반 박자 늦었다.<br><br>문이 닫히다 발톱에 한 번 튕겼다.<br>온 힘으로 다시 당겨 물렸다. 문 안쪽까지 긁힌 자국이 들어왔다. 손가락 두 마디 차이였다. 올라가는 내내 거울 속 다섯 낯이 하얬다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-28, spirit:-18 } },
    { l:'② 타는 순서와 자리를 미리 정한다.', k:'fix', dc:24,
      ok:`등이 넓은 사람이 문 쪽, 눈 밝은 사람이 거울 쪽. 타기 전에 정했다.<br><br>타는 데 숨 세 번이면 됐다.<br>정해진 자리는 빠르다. 문이 닫히고 나서야 벌판 쪽에서 늦은 발소리가 왔다. 늦은 것은 늦은 것이다.`,
      ng:`자리 정하는 사이가 길었다.<br><br>타는 순서가 입구에서 엉켰다.<br>마지막 사람이 구르듯 타며 문틀에 어깨를 찧었다. 문이 닫히는 소리와 바깥의 발소리가 겹쳤다. 순서는 미리, 짧게. 그게 결론이었다.`,
      win:{ exp:16, hp:5 }, lose:{ hp:-26, mind:-15 } }
  ] }
]);
// ── 탐정 (자원 없음)
kJob('detective', 'S', [

{ at:'S', t:'현장 — 마지막 다섯 호흡',
  x:`앞선 팀의 하나가 쓰러져 있다.<br><br>
    탐정은 시신을 보지 않는다. 현장을 본다.<br>
    자세, 손의 방향, 발밑의 긁힘.<br><br>
    마지막 다섯 호흡이 거기 적혀 있다.`,
  o:[
    { l:'① 자세로 마지막 순간을 되돌린다.', k:'gaze', dc:25, wake:1,
      ok:`발끝은 바위 틈을 향하고 상체는 반대로 꺾였다. 숨으려다 돌아선 것이다.<br><br>숨을 자리를 두고 왜 돌아섰나. 소리가 양쪽에서 났기 때문이다.<br>둘이었다. 하나가 몰고 하나가 받았다. 이 어둠의 사냥은 혼자가 아니다. 그 결론 하나로 일행의 경계 방식을 전부 바꿨다. 앞만 보던 눈 하나를 늘 뒤에 뒀다.<br><br>현장이 말하고 탐정이 받아 적는다. 어느 현장에서든 마지막 다섯 호흡을 되돌리는 눈이 생겼다.`,
      ng:`재구성이 너무 생생했다.<br><br>그의 마지막 자세를 머릿속으로 따라가다 제 몸이 그 각도로 굳어 있는 걸 알았다.<br>일행이 어깨를 쳐서야 풀렸다. 현장에 깊이 들어가면 나오는 길도 챙겨야 한다. 그걸 잊었다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 증거만 적고 빠르게 뜬다.', k:'steady', dc:23,
      ok:`위치, 자세, 상처 방향. 세 줄만 적고 자리를 떴다.<br><br>현장은 사건의 자리이자 사냥의 자리다. 오래 머물면 다음 현장이 된다.<br>세 줄은 그날 밤 야영 배치를 정하는 근거가 됐다. 짧은 기록도 기록이다.`,
      ng:`적는 데 너무 공을 들였다.<br><br>고개를 드니 일행이 벌써 저만치 가 있었다.<br>혼자 남은 걸 깨닫는 순간 어둠이 두 배로 어두워졌다. 뛰어서 따라붙었다. 수첩 글씨가 다 흔들렸다.`,
      win:{ exp:15, mind:5 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'S', t:'핏자국 — 두 방향',
  x:`핏자국이 길에 번져 있다.<br><br>
    떨어진 방울과 끌려간 줄. 방향이 다르다.<br>
    방울은 걸어간 길이고 줄은 끌려간 길이다.<br><br>
    탐정은 두 길을 가른다.`,
  o:[
    { l:'① 두 방향을 갈라 지도에 얹는다.', k:'gaze', dc:25,
      ok:`방울 길은 물가 쪽, 끌린 줄은 바위 지대 쪽이다.<br><br>끌고 간 쪽이 그것의 집 방향이다. 먹이를 집으로 가져가는 건 어디나 같다.<br>바위 지대를 지도에서 지웠다. 물가 길로 돌았다. 지워진 길이 반나절 빠른 길이었지만 아무도 아쉬워하지 않았다.`,
      ng:`번진 데서 두 방향이 섞였다.<br><br>갈라 보려고 너무 오래 쪼그려 앉아 있었다.<br>등 뒤 어둠에서 돌 구르는 소리가 났다. 수첩을 덮고 물러났다. 반만 가른 지도를 들고. 반쪽 지도는 반쪽 안전이다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-16, hp:-26 } },
    { l:'② 끌린 줄을 따라가 사람을 찾는다.', k:'sense', dc:24,
      doom:{ title:'저장고', what:'끌린 자국 끝에서 기다리던 것에게 물려 끌려갑니다', dc:20, sec:40,
        text:`살아 있을지도 모른다. 끌린 줄을 따라갔다.<br><br>줄은 바위 틈으로 이어졌다. 틈 안쪽은 서늘했다. 먹이를 쌓아 두는 자리다.<br>쌓인 것들 사이에서 숨 쉬는 것은 없었다. 숨 쉬는 것은 입구 쪽에 있었다.<br><br>돌아섰을 때 입구가 막혀 있었다. 저장고는 채우라고 있는 것이다.`,
        dieText:`끌린 줄이 하나 늘었다.<br><br>두 줄은 같은 틈으로 이어진다.<br>다음 탐정은 두 줄을 읽게 될 것이다.` },
      ok:`따라가되 줄의 상태부터 봤다. 핏기가 변했고 끌린 깊이가 일정하다.<br><br>버둥거림이 없는 끌림이다. 이미 끝난 뒤의 운반이다.<br>구할 사람이 없는 길은 가지 않는 길이다. 줄 끝 방향만 적고 돌아섰다. 탐정의 일은 가끔 안 가는 것이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'등불 — 꺼진 이유',
  x:`밤중에 등불이 꺼졌다. 바람 없는 자리였다.<br><br>
    다시 켜고 탐정은 심지부터 본다.<br>
    기름은 반 넘게 남았다. 심지는 멀쩡하다.<br><br>
    꺼질 이유가 없는 불이 꺼졌다.`,
  o:[
    { l:'① 심지와 그을음을 조사한다.', k:'gaze', dc:25, wake:1,
      ok:`심지가 한쪽으로 쏠려 굳었다. 그을음도 한 방향으로 쓸렸다.<br><br>한 번의 센 바람. 바람 없는 자리에서의 한 번의 센 바람은 바람이 아니라 입김이다.<br>무언가 등불을 불어 끄고 갔다. 끄고도 아무 일 없었던 건 그때 전원이 깨어 있어서다. 그날부터 등불에 바람막이 통을 씌우고 불 꺼짐을 신호로 정했다. 꺼지면 전원 기상.<br><br>불 꺼진 이유 하나에서 그것들이 불을 안다는 결론까지. 작은 증거가 큰 사실을 연다.`,
      ng:`심지만 보다가 밤을 반 썼다.<br><br>결론은 못 내리고 겁만 늘었다.<br>남은 밤 내내 등불만 쳐다봤다. 불은 다시 안 꺼졌다. 안 꺼지는 불을 지키느라 사람이 먼저 꺼질 뻔했다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 등불을 둘로 늘려 번갈아 켠다.', k:'fix', dc:23,
      ok:`하나가 꺼져도 하나가 남는 체제로 바꿨다.<br><br>기름은 더 들지만 어둠이 통째로 오는 일은 없어졌다.<br>며칠 뒤 정말로 하나가 꺼졌다. 남은 하나의 불빛 가장자리에서 물러가는 꼬리가 보였다. 꺼뜨리고 들어오려던 것이다. 체제가 막았다.`,
      ng:`기름 계산이 어긋났다.<br><br>둘을 켜다 보니 기름이 예정보다 빨리 줄었다.<br>마지막 이틀은 결국 하나로 버텼다. 어둠보다 계산 실수가 더 부끄러웠다.`,
      win:{ exp:15, hp:5 }, lose:{ mind:-15, hp:-25 } }
  ] },

{ at:'S', t:'놓인 고기 — 너무 좋은 자리',
  x:`길 한가운데 짐승 고기 한 덩이가 있다. 성하다.<br><br>
    탐정은 좋은 것부터 의심한다.<br>
    여기서 성한 고기가 길 가운데 있을 이유가 없다.<br><br>
    있다면 누가 둔 것이다.`,
  o:[
    { l:'① 고기 둘레의 흔적을 조사한다.', k:'gaze', dc:25,
      ok:`고기 둘레 한 걸음의 흙이 이상하게 고르다. 쓸어서 지운 것이다.<br><br>발자국을 지우는 사냥. 미끼다.<br>지워진 흙 가장자리에 지우다 만 자국 반 개가 남아 있었다. 발가락 셋. 고기를 두고 크게 돌았다. 돌면서 보니 바위 위에 엎드린 윤곽이 고기 쪽을 내려다보고 있었다. 낚시꾼은 못 본 척해 주는 게 예의다.`,
      ng:`둘레만 보고 위를 안 봤다.<br><br>고기 위쪽 바위에서 작은 돌이 굴러떨어졌다.<br>위에 있던 것이 몸을 뒤척인 것이다. 조사고 뭐고 뒤로 물러났다. 미끼 조사도 낚시터 안에서 하면 입질이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 긴 막대로 고기를 끌어온다.', k:'luck', dc:24,
      ok:`스무 걸음 밖에서 막대 두 개를 이어 고기를 끌었다.<br><br>덮침은 없었다. 미끼가 아니었거나 낚시꾼이 조는 중이었거나.<br>고기는 성했다. 소금 쳐서 챙겼다. 운으로 얻은 고기가 제일 맛있다는 건 비밀이다.`,
      ng:`막대가 짧았다. 세 걸음을 더 들어갔다.<br><br>그 세 걸음에서 수풀이 갈라졌다.<br>막대를 버리고 뛰었다. 고기는 그 자리에 남았다. 다음 미끼 노릇을 하도록. 빈손에 식은땀만 쥐고 돌아왔다.`,
      win:{ exp:16, item:'짐승 고기' }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'울음 — 시간표',
  x:`울음이 돈다. 탐정은 시계 대신 수첩을 꺼낸다.<br><br>
    언제, 어느 쪽에서, 몇 번.<br>
    사흘 치를 적으니 줄이 보인다.<br><br>
    그것들은 같은 길을 같은 때에 돈다. 순찰이다.`,
  o:[
    { l:'① 시간표를 완성해 틈을 찾는다.', k:'gaze', dc:26,
      ok:`울음 지점을 이으니 도는 길이 그려졌다. 한 바퀴에 한 식경.<br><br>길이 겹치지 않는 틈이 두 군데. 순찰과 순찰 사이의 공백이다.<br>그 틈으로만 이동했다. 사흘을 적은 값으로 사흘을 안전하게 움직였다. 수첩이 방패였다.`,
      ng:`사흘 치 기록에 하루가 빠졌다. 피곤해서 적다 만 날이다.<br><br>그날의 울음이 예외였다. 비 오는 날은 길이 바뀐다.<br>비 오는 날 틈이라 믿은 자리에서 울음과 마주쳤다. 빗속을 내달렸다. 기록은 빠진 하루만큼만 지켜 준다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 순찰 바로 뒤를 따라 이동한다.', k:'hide', dc:25,
      doom:{ title:'이중 순찰', what:'두 번째 순찰에 물려 끌려갑니다', dc:19, sec:40,
        text:`순찰이 지나간 직후가 제일 안전하다. 그렇게 계산하고 바로 뒤를 따랐다.<br><br>순찰은 하나가 아니었다. 둘이 반 바퀴 차이로 돈다.<br>첫째 뒤를 따르는 것은 둘째 앞을 걷는 것이다.<br><br>모퉁이에서 둘째와 정면으로 만났다. 계산은 맞았다. 전제가 틀렸을 뿐.`,
        dieText:`순찰은 계속 돈다.<br><br>둘이서, 반 바퀴 차이로.<br>다음에 세는 사람은 둘 다 세기를.` },
      ok:`따르기 전에 하루를 더 써서 셌다. 울음의 목소리가 두 종류였다.<br><br>순찰이 둘이다. 반 바퀴 차이.<br>첫째와 둘째 사이의 반 바퀴 틈에 맞춰 움직였다. 둘 사이에 끼어 걷는 길이 제일 안전한 길이라는 역설을 수첩에 적었다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'일행 — 걷은 적 없는 소매',
  x:`일행 하나가 이상하다.<br><br>
    더운데 소매를 안 걷는다. 물을 남보다 배로 마신다. 밤에 식은땀을 흘린다.<br>
    물어보면 멀쩡하다고 한다.<br><br>
    탐정은 말보다 증거를 믿는다.`,
  o:[
    { l:'① 증거를 모아 조용히 내민다.', k:'gaze', dc:25, wake:1,
      ok:`추궁하지 않았다. 물통 소비량, 식은땀, 소매. 셋을 조용히 늘어놓았다.<br><br>그 사람이 한참 있다 소매를 걷었다. 물린 자국이 곪기 시작하고 있었다.<br>치유 손이 바로 붙었다. 하루만 늦었어도 팔을 못 썼을 거라 했다. 그는 짐이 되기 싫어 숨겼다고 했다. 숨긴 상처가 제일 큰 짐이 된다는 걸 이제 다섯이 다 안다.<br><br>사람도 현장이다. 거짓말은 입에 있고 증거는 몸에 있다. 몸을 읽는 눈이 생겼다.`,
      ng:`증거를 내민다는 게 추궁처럼 나왔다.<br><br>그 사람이 정색하고 부인했다. 소매는 더 단단히 여며졌다.<br>이틀 뒤 열이 나서야 실토했다. 치료가 이틀 늦은 값은 그 사람 몫이 아니라 전원의 걸음 값으로 치러졌다. 증거는 맞았는데 내미는 손이 틀렸다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-17 } },
    { l:'② 치유 담당에게 조용히 귀띔한다.', k:'bond', dc:23,
      ok:`직접 묻지 않고 치유 손에게 증거 셋을 넘겼다.<br><br>치유 손이 저녁에 자연스럽게 전원 상처 점검을 열었다.<br>그 사람 차례에서 물린 자국이 나왔다. 아무도 누구 탓을 안 했다. 점검이니까. 길을 만들어 주면 비밀은 제 발로 나온다.`,
      ng:`귀띔이 얕았다. 치유 손이 대수롭지 않게 넘겼다.<br><br>점검은 열리지 않았다.<br>결국 사흘 뒤 그 사람이 쓰러지고서야 자국이 드러났다. 귀띔은 증거를 다 얹어야 귀띔이다. 반만 얹으면 소문이다.`,
      win:{ exp:15, spirit:6 }, lose:{ spirit:-16, mind:-16 } }
  ] },

{ at:'S', t:'버린 짐 — 거꾸로 된 순서',
  x:`길을 따라 버려진 짐이 점점이 이어진다.<br><br>
    냄비, 담요, 책, 그리고 물통.<br>
    사람은 무거운 것부터 버린다. 그게 정상이다.<br><br>
    이 순서는 거꾸로다. 물통이 마지막이다.`,
  o:[
    { l:'① 버린 순서로 그 사람을 재구성한다.', k:'gaze', dc:25,
      ok:`무게 순이 아니라 소중한 순서의 역순이다. 덜 아까운 것부터 버리며 끝까지 걸은 것이다.<br><br>물통을 버린 지점, 거기서 그는 물이 더 필요 없다는 걸 알았다.<br>그 지점 앞 모퉁이에 뭐가 있는지 보지 않기로 했다. 대신 그가 버틴 거리를 쟀다. 냄비에서 물통까지 이천 걸음. 사람은 그만큼 버틴다. 그 숫자가 이상하게 힘이 됐다.`,
      ng:`순서를 무게순으로 잘못 읽었다.<br><br>그냥 지친 사람이 하나 지나갔구나 하고 그 모퉁이로 들어섰다.<br>모퉁이 안쪽 벽의 자국들을 보고서야 수첩을 다시 폈다. 뒷걸음으로 나왔다. 증거의 순서를 틀리면 길의 순서를 틀린다.`,
      win:{ exp:22, dream:3 }, lose:{ spirit:-18, mind:-16 } },
    { l:'② 버려진 짐을 쓸 만한 것만 거둔다.', k:'luck', dc:23,
      ok:`담요 틈에 기름종이 꾸러미가 말려 있었다. 비상식이다.<br><br>말린 고기가 성했다. 버린 게 아니라 흘린 것이다.<br>담요는 털어서 제일 추위 타는 일행에게 줬다. 물건은 쓰는 사람에게 가야 물건이다.`,
      ng:`냄비를 집다 떨어뜨렸다.<br><br>쇳소리가 길에 길게 울렸다.<br>전원이 그 자리에 얼어붙어 소리의 여운이 다 꺼지기를 기다렸다. 답은 안 왔다. 냄비는 그 자리에 두고 왔다. 소리 나는 물건은 임자가 따로 있다.`,
      win:{ exp:15, item:'말린 고기' }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S', t:'천장 — 위의 사건',
  x:`벽의 긁힌 자국이 띄엄띄엄 이어진다.<br><br>
    바닥 발자국과 안 맞는다. 바닥은 조용한데 벽만 시끄럽다.<br>
    탐정은 고개를 들었다.<br><br>
    사건은 천장에서 났다.`,
  o:[
    { l:'① 자국 간격으로 천장 길을 복원한다.', k:'gaze', dc:25, wake:1,
      ok:`벽 자국은 도약의 디딤 자국이다. 간격을 이으니 천장의 길이 그려졌다.<br><br>그것은 천장 틈과 벽 모서리를 짚으며 다닌다. 길이 정해져 있다.<br>그 길 아래를 피해 걸었다. 천장 길과 바닥 길이 겹치는 교차점 두 곳만 빠르게 지났다. 위에서 내려오는 사냥은 교차점에서만 가능하니까.<br><br>바닥만 보던 눈이 천장의 사건을 읽었다. 현장은 바닥이 아니라 육면이다. 그걸 몸에 새겼다.`,
      ng:`복원하느라 고개를 들고 오래 서 있었다.<br><br>목이 뻣뻣해질 때쯤 천장 틈에서 먼지가 떨어졌다.<br>지금 그 길을 쓰는 중이라는 뜻이다. 복원이고 뭐고 벽에 붙어 구간을 뛰었다. 지도는 머릿속에서 반쯤 흘렸다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-17, hp:-26 } },
    { l:'② 벽에 붙어 모서리로만 걷는다.', k:'steady', dc:23,
      ok:`천장에서 내려오는 것은 가운데가 사정권이다. 벽에 붙으면 각이 안 나온다.<br><br>전원이 벽을 쓸며 걸었다.<br>구간을 다 지날 때까지 위에서 두 번 기척이 따라왔다. 각이 안 나오는 먹이를 포기하는 데 두 번이면 충분했던 모양이다.`,
      ng:`벽에 붙어 걷다 모서리의 구멍을 못 봤다.<br><br>팔이 구멍 가장자리에 긁혔다. 깊지는 않았다.<br>구멍 안쪽에서 비린 바람이 새어 나오고 있었다. 벽도 다 믿을 건 못 된다. 붙되 쓸지는 말 것.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S', t:'어둠 속 울음 — 사람 소리',
  x:`어둠 저쪽에서 사람이 운다.<br><br>
    도와 달라는 소리다. 일행의 발이 그쪽으로 돈다.<br>
    탐정이 손을 들어 막았다.<br><br>
    먼저 조사한다. 그게 순서다.`,
  o:[
    { l:'① 울음의 허점을 찾는다.', k:'gaze', dc:26,
      ok:`수첩에 간격을 적으며 들었다. 같은 간격, 같은 높이, 같은 길이.<br><br>사람의 울음은 흔들린다. 이건 안 흔들린다. 숨도 안 쉰다.<br>외운 소리다. 흉내다. 일행에게 수첩을 보여 줬다. 적힌 간격이 자로 잰 듯한 걸 보고 다들 발을 거뒀다. 울음은 밤새 같은 간격으로 이어지다 새벽에 뚝 그쳤다. 장사를 접은 것이다.`,
      ng:`허점을 찾는 사이 울음에 이름이 섞이기 시작했다.<br><br>일행 하나의 이름이었다.<br>어디서 들었나. 생각할수록 답이 싫어졌다. 그 일행을 가운데 세우고 귀를 막게 했다. 조사가 길어지면 조사당하는 건 이쪽이다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-20, mind:-16 } },
    { l:'② 소리 쪽으로 구조를 나간다.', k:'bond', dc:24,
      doom:{ title:'우는 것', what:'사람 소리를 내던 것에게 물려 끌려갑니다', dc:20, sec:38,
        text:`사람일 가능성이 한 줌이라도 있으면 간다. 그렇게 정하고 나갔다.<br><br>울음이 가까워질수록 또렷해졌다. 너무 또렷했다. 목이 쉬지도 않고.<br>소리의 자리에 사람은 없었다. 소리만 있었다.<br><br>소리를 내던 것이 입을 다물고 이쪽을 문다. 구조는 미끼의 다른 이름이었다.`,
        dieText:`울음이 다시 시작된다.<br><br>목소리가 하나 늘었다.<br>더 그럴듯해졌다.` },
      ok:`가되 탐정의 법대로 갔다. 둘이 남고, 셋이 가고, 빛은 끄고, 소리 지점을 반원으로 돌았다.<br><br>반원의 끝에서 보였다. 소리의 자리에 사람이 없는 것이.<br>있는 것은 바위 그늘의 웅크린 윤곽뿐. 조용히 반원을 되감아 왔다. 구조대가 전원 돌아오는 구조가 제일 좋은 구조다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S', t:'옛 야영지 — 재의 층',
  x:`쓰다 버린 야영지다. 화덕 자리에 재가 쌓여 있다.<br><br>
    탐정은 재를 걷어 층을 본다.<br>
    세 층이다. 세 팀이 거쳐 갔다.<br><br>
    맨 위 층이 제일 얇다.`,
  o:[
    { l:'① 재의 층으로 세 팀의 밤을 읽는다.', k:'gaze', dc:25, wake:1,
      ok:`첫 층은 두껍다. 느긋하게 밤을 났다. 둘째 층은 보통. 셋째 층은 얇고 반쯤 흩어졌다.<br><br>마지막 팀은 불을 피우다 말고 떠났다. 급하게. 흩어진 재가 전부 한 방향으로 쓸렸다. 떠난 방향이다.<br>급하게 떠난 방향은 쫓긴 방향이다. 그 반대쪽이 그들이 버린 안전한 길이다. 반대로 갔다. 길이 맞았다.<br><br>재 한 줌에서 세 팀의 밤을 읽었다. 남이 보면 재고 탐정이 보면 기록이다.`,
      ng:`층을 가르다 재를 너무 헤집었다.<br><br>재 먼지가 올라 기침이 터졌다.<br>기침 소리가 빈 야영지에 크게 울렸다. 층이고 뭐고 다 섞였다. 기록을 읽다가 기록을 지운 셈이다. 그 자리를 떴다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-25, mind:-16 } },
    { l:'② 화덕 돌 밑을 뒤진다.', k:'luck', dc:23,
      ok:`야영꾼의 법이다. 소금은 화덕 돌 밑에 묻는다. 습기를 피해서.<br><br>둘째 팀 것인지 돌 밑에 소금 덩이가 성하게 남아 있었다.<br>받은 자리에는 부싯돌 하나를 묻어 뒀다. 다음 팀의 몫이다. 야영지는 그렇게 이어진다.`,
      ng:`돌을 들추자 밑에서 벌레 떼가 쏟아졌다.<br><br>손등을 물렸다. 독은 없는 놈들이었지만 밤새 가려웠다.<br>소금은 없었다. 셋째 팀이 급한 와중에도 챙겨 간 모양이다. 급해도 소금은 챙긴다. 그게 이 바닥이다.`,
      win:{ exp:14, item:'소금 덩이' }, lose:{ hp:-25, mind:-14 } },
    { l:'③ 야영지를 보강해 다시 쓴다.', k:'fix', dc:24,
      ok:`버린 자리에도 뼈대는 남는다. 바람막이 돌담을 한 층 올리고 트인 쪽에 가시덤불을 쌓았다.<br><br>세 팀이 다진 자리에 네 번째 밤이 얹혔다.<br>전 팀들이 왜 이 자리를 골랐는지 밤이 깊을수록 알 수 있었다. 등 뒤가 바위고 앞이 트였다. 좋은 자리는 물려받는 것이다.`,
      ng:`보강에 해가 다 졌다.<br><br>마지막 덤불을 얹을 때는 이미 캄캄했다.<br>어둠 속 작업 소리가 멀리 갔는지 밤새 둘레에서 기척이 돌았다. 들어오지는 못했다. 보강 값은 한 셈인데 잠은 다 설쳤다.`,
      win:{ exp:16, hp:5 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'사라진 보초 — 소리 없는 밤',
  x:`아침에 보초가 없다.<br><br>
    비명도 없었다. 다툰 자국도 없다. 짐은 그대로다.<br>
    탐정은 그 자리에 쪼그려 앉았다.<br><br>
    현장은 비어 있는 게 아니라 가득 차 있다.`,
  o:[
    { l:'① 이슬과 풀로 밤을 재구성한다.', k:'gaze', dc:26,
      ok:`앉았던 자리의 이슬 마름이 고르다. 오래 앉아 있었다. 그러다 일어선 자국. 끌린 게 아니라 디딘 발자국이 이어진다.<br><br>제 발로 걸어 나갔다. 조용히, 신발까지 신고. 발자국 간격이 고르다. 서두르지도 않았다.<br>무언가를 따라간 걸음이다. 부르는 것을. 발자국이 어둠 속으로 스무 걸음, 거기서 끝났다. 그 너머는 쫓지 않기로 했다. 대신 규칙을 바꿨다. 보초는 둘, 서로 열 걸음 안에. 혼자인 귀가 제일 약하다.`,
      ng:`재구성에 아침을 다 썼다.<br><br>결론은 같았다. 제 발로, 조용히, 따라갔다.<br>아침을 쓴 만큼 낮길이 줄었다. 서두른 낮길에 둘이 발을 접질렸다. 산 사람의 시간으로 죽은 답을 산 셈이다. 수지가 안 맞았다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-19, mind:-16 } },
    { l:'② 발자국 끝 너머를 수색한다.', k:'sense', dc:25,
      doom:{ title:'스무 걸음 너머', what:'보초를 데려간 것에게 물려 끌려갑니다', dc:19, sec:38,
        text:`발자국이 끝난 자리 너머를 뒤졌다. 살아 있을지도 모르니까.<br><br>너머의 어둠은 발자국이 필요 없는 것의 땅이었다.<br>부르는 소리가 들렸다. 이번에는 보초의 목소리로.<br><br>목소리 쪽으로 세 걸음 간 것까지는 기억난다. 넷째 걸음은 바닥이 없었다.`,
        dieText:`야영지에서 발자국이 또 스무 걸음 이어진다.<br><br>나란히는 아니다. 하나가 끝난 데서 하나가 시작된다.<br>줄을 서듯이.` },
      ok:`수색하되 줄을 매고 갔다. 허리에 밧줄, 끝은 일행 셋이 쥐고.<br><br>발자국 끝 너머 다섯 걸음에서 보초의 단추 하나를 찾았다. 그게 다였다.<br>단추를 쥐고 줄을 당겨 돌아왔다. 줄 없이 갔으면 단추가 둘이 됐을 것이다. 수색의 법은 돌아오는 길부터 정하는 것이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'관제실 — 첫날의 동선',
  x:`관제실이다. 의자가 넘어져 있고 컵이 세 개 책상에 그대로다.<br><br>
    탐정은 첫날을 재구성한다. 착륙 당일.<br>
    모든 사건에는 첫 희생자가 있다.<br><br>
    첫 희생자가 사건의 문이다.`,
  o:[
    { l:'① 컵과 의자로 첫 순간을 되돌린다.', k:'gaze', dc:25, wake:1,
      ok:`컵 셋 중 둘은 식은 채 다 남았고 하나만 반쯤 비었다. 마시던 중이었다.<br><br>넘어진 의자는 문 쪽이 아니라 벽 쪽으로 자빠졌다. 문에서 온 게 아니다. 벽 쪽, 환풍구 쪽에서 왔다.<br>첫날부터 환풍구였다. 문을 아무리 잠가도 소용없었던 이유다. 그 결론으로 지금의 경로에서 환풍구 밑 자리를 전부 지웠다.<br><br>수십 일 전의 현장이 오늘을 지킨다. 오래된 사건일수록 식은 증거가 많고, 식은 증거는 안 도망간다.`,
      ng:`재구성 중에 반쯤 빈 컵을 건드려 엎었다.<br><br>마른 얼룩 위에 새 얼룩이 겹쳤다.<br>증거 하나를 제 손으로 지웠다. 결론은 겨우 세웠지만 확신이 한 칸 모자랐다. 모자란 한 칸만큼 밤에 뒤척였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 관제실을 잠가 쉼터로 만든다.', k:'fix', dc:23,
      ok:`관제창은 두꺼운 유리다. 일지에도 유리는 못 뚫는다고 적혀 있었다.<br><br>문을 안에서 걸고 환풍구 덮개에 책상을 세워 막았다.<br>이 건물에서 처음으로 등을 바닥에 다 붙이고 잤다. 관제실은 원래 지키라고 만든 방이다. 그 용도대로 썼다.`,
      ng:`문은 걸었는데 환풍구를 잊었다.<br><br>밤에 덮개 너머에서 쇠 긁는 소리가 나서야 생각났다.<br>어둠 속에서 더듬더듬 책상을 세워 막았다. 소리는 새벽까지 이어지다 그쳤다. 잠은 교대로 반쪽씩 잤다.`,
      win:{ exp:16, hp:5 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'격실 — 안에서 잠긴 문',
  x:`격실 문이 안에서 잠겨 있다.<br><br>
    창으로 들여다보니 안에는 아무도 없다.<br>
    빈방이 안에서 잠겼다.<br><br>
    탐정이 제일 좋아하는 종류의 문제다. 여기만 아니면.`,
  o:[
    { l:'① 밀실을 푼다.', k:'gaze', dc:26,
      ok:`안에 사람이 없는데 안에서 잠겼다면 잠근 사람은 다른 데로 나갔다.<br><br>창에 이마를 대고 천장을 훑었다. 환풍구 덮개가 안쪽으로 열려 있다.<br>문을 잠그고 환풍구로 나간 것이다. 문을 잠근 건 무언가가 문으로 따라 들어오는 중이었다는 뜻이고, 환풍구로 나갔다는 건 그 순간 관이 비어 있었다는 뜻이다. 풀었다. 그리고 이 문은 안 열기로 했다. 이 방은 지금 그 관과 이어진 방이다. 밀실은 풀라고만 있는 게 아니다. 닫아 두라고도 있다.`,
      ng:`밀실에 너무 오래 매달렸다.<br><br>창에 이마를 댄 채 반 식경을 서 있었다.<br>떨어지려는데 창 안쪽, 열린 환풍구에서 먼지가 후두둑 떨어졌다. 안 풀린 문제를 두고 떠나는 발걸음이 그렇게 가벼운 적이 없었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 문을 따고 들어가 보급품을 찾는다.', k:'break', dc:24,
      ok:`경첩 쪽 핀을 뽑아 문을 통째로 들어냈다. 자물쇠는 건드리지도 않았다.<br><br>안쪽 선반에 정수 탱크가 반 넘게 차 있었다. 물통을 전부 채웠다.<br>나올 때 문을 도로 세우고 핀을 박았다. 열린 환풍구 쪽으로는 등을 안 보였다. 물은 얻고 밀실은 밀실로 돌려놨다.`,
      ng:`경첩이 삭아 있었다. 문이 통째로 넘어가며 격실 바닥을 쳤다.<br><br>쇳소리가 복도를 울렸고 열린 환풍구가 그 소리를 받아 삼켰다.<br>관 깊은 데서 되울림이 왔다. 물만 급히 반 통 받고 나왔다. 뒤는 안 돌아봤다.`,
      win:{ exp:16, item:'맑은 물' }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'표본 선반 — 하나만 밖에서',
  x:`깨진 표본 병이 선반 가득이다.<br><br>
    탐정은 깨진 결을 하나씩 본다. 전부 안에서 밖으로 터졌다.<br>
    딱 하나만 밖에서 안으로 깨졌다.<br><br>
    누가 깨서 꺼냈다.`,
  o:[
    { l:'① 꺼낸 자의 흔적을 쫓는다.', k:'gaze', dc:25,
      ok:`그 병 앞 먼지에 신발 자국이 있다. 사람 신발. 연구소 것이 아닌 등산화다.<br><br>앞선 탐사대 누군가가 표본 하나를 꺼내 갔다.<br>살아서 여기까지 왔던 사람이 있고, 그 사람은 뭔가를 가져갈 가치가 있다고 판단했다. 등산화 자국의 방향을 지도에 적었다. 그 사람을 만나게 되면 물을 것이 두 가지다. 뭘 가져갔나. 왜.`,
      ng:`신발 자국을 쫓다가 자국이 이상해지는 지점을 만났다.<br><br>보폭이 갑자기 두 배가 됐다. 전력으로 뛴 것이다.<br>그 지점부터는 병 조각이 복도에 점점이 떨어져 있었다. 꺼낸 것을 쥔 채 뛰었다는 뜻이다. 추적을 접었다. 쫓긴 사람의 길은 쫓는 것의 길이기도 하다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 선반 방을 밀봉하고 지나간다.', k:'steady', dc:23,
      ok:`안에서 터진 병이 쉰이 넘는 방이다. 쉰이 넘는 것이 나갔다는 뜻이다.<br><br>방문을 닫고 문틈을 걸레로 메웠다. 돌아올 놈이 있을지 모르니까.<br>지나가는 길에 방 안에서 유리 구르는 소리가 한 번 났다. 메운 문틈을 보고 돌아섰다. 밀봉 값이다.`,
      ng:`문이 뒤틀려 안 닫혔다.<br><br>반 뼘 틈을 남기고 포기했다.<br>그 반 뼘이 밤새 마음에 걸렸다. 걸린 만큼 자주 뒤를 돌아봤고, 돌아본 만큼 걸음이 늦었다. 못 닫은 문은 등에 업고 가는 문이다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-15 } },
    { l:'③ 성한 병 뒤 약품장을 뒤진다.', k:'luck', dc:24,
      doom:{ title:'선반 뒤', what:'약품장 뒤에 숨어 있던 것에게 물려 끌려갑니다', dc:20, sec:36,
        text:`약품장 문을 당겼다. 열리지 않았다. 더 세게 당겼다.<br><br>장이 통째로 흔들리며 뒤쪽에서 유리 깨지는 소리가 났다.<br>장 뒤 공간에 웅크려 있던 것이 일어선다. 거기가 그놈의 둥지였다.<br><br>장 너머로 끌려 들어간다. 약품 냄새가 비린내로 바뀐다.`,
        dieText:`약품장은 반쯤 열린 채 멈춰 있다.<br><br>안의 약병들은 성하다.<br>꺼낼 사람이 없을 뿐이다.` },
      ok:`당기기 전에 장 밑 먼지를 봤다. 먼지가 문 열리는 반원으로 쓸려 있다.<br><br>최근에 열렸다 닫힌 장이다. 누가. 혹은 무엇이.<br>정면을 피해 옆에서 막대로 문을 열었다. 안에는 약품뿐이었고 장 뒤 벽 틈에서 비린 바람이 샜다. 소독약 몇 병만 집어 그 방을 빠르게 나왔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'산 구멍 — 시간 계산',
  x:`바닥의 산 구멍에서 아직 가는 김이 오른다.<br><br>
    탐정은 구멍 가장자리의 삭은 정도를 본다.<br>
    삭음에는 속도가 있고 속도는 시계다.<br><br>
    언제 지나갔는지 계산할 수 있다.`,
  o:[
    { l:'① 삭은 정도로 지나간 때를 계산한다.', k:'gaze', dc:25,
      ok:`가장자리가 아직 무르다. 한 식경 안쪽이다.<br><br>한 식경이면 멀리 못 갔다. 그리고 피를 흘리는 것은 빨리 못 간다.<br>이 복도는 지금 그것의 반경 안이다. 반대쪽 계단으로 돌았다. 돌아가는 길에 멀리서 쇠 녹는 소리가 한 번 들렸다. 계산 안의 거리였다. 계산 밖이 아니라서 다행이었다.`,
      ng:`삭은 정도를 재려고 구멍에 너무 붙었다.<br><br>김을 들이마셨다. 목이 타는 듯했다.<br>기침을 참느라 눈물이 났다. 계산은 맞았는데 코가 값을 치렀다. 증거와는 거리를 두고 사귈 것.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 구멍 배열로 안전한 바닥을 가른다.', k:'steady', dc:23,
      ok:`구멍들이 몰린 쪽과 성긴 쪽을 갈랐다. 몰린 쪽 아래는 비었을 확률이 높다.<br><br>성긴 쪽 벽면을 따라 한 줄로 건넜다.<br>다 건넌 뒤 몰린 쪽 바닥이 저 혼자 내려앉았다. 늦게 삭은 데가 마저 삭은 것이다. 줄을 세운 보람이 소리로 왔다.`,
      ng:`성긴 쪽이라 믿은 데에 숨은 구멍이 있었다. 재가 덮여 안 보였다.<br><br>일행 하나의 발이 빠졌다.<br>발목까지였고 신발이 산 자국을 받았다. 급히 벗겨 던졌다. 맨발 하나가 생겼다. 남은 길이 두 배로 길어졌다.`,
      win:{ exp:15, hp:5 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'연구자의 시신 — 스스로 닫은 문',
  x:`안에서 책상으로 문을 막은 방이다. 연구자가 책상 앞에 엎드려 있다.<br><br>
    외상이 없다. 약병이 하나 비어 있다.<br>
    제 손으로 끝낸 것이다.<br><br>
    탐정은 이유를 묻는 직업이다. 죽은 사람에게도.`,
  o:[
    { l:'① 책상 위의 기록을 재구성한다.', k:'gaze', dc:26, wake:1,
      ok:`유서가 아니었다. 관찰 기록이었다. 제 몸의.<br><br>날짜별로 적혀 있다. 목 뒤 통증. 식욕 증가. 그리고 마지막 줄. 「내 안에서 소리가 난다. 문은 막았다. 늦기 전에.」<br>그는 제 몸이 둥지가 되기 전에 끝냈다. 문을 막은 건 제가 변한 뒤 나가지 못하게 하기 위해서였다. 기록의 앞 장에 징후 목록이 정리돼 있었다. 그 목록으로 일행 전원을 점검했다. 전원 깨끗했다. 목록은 수첩에 옮겨 적었다.<br><br>가장 아픈 현장이 가장 많은 것을 가르친다. 이유를 끝까지 묻는 눈이 생겼다. 물어 주는 것이 예의인 죽음이 있다.`,
      ng:`기록을 읽다가 마지막 줄에서 멈췄다.<br><br>내 안에서 소리가 난다.<br>그날 밤 제 숨소리가 자꾸 수상하게 들렸다. 가슴에 손을 얹고 몇 번이나 셌다. 남의 기록이 제 귀에 옮는 밤이었다.`,
      win:{ exp:24, dream:4 }, lose:{ spirit:-20, mind:-17 } },
    { l:'② 시신을 수습하고 이름을 적는다.', k:'bond', dc:23,
      ok:`명찰의 이름을 수첩에 옮기고 가운을 덮어 줬다.<br><br>책상은 그대로 뒀다. 그가 막은 문이니까.<br>대신 창 쪽으로 나가며 문틈에 한 줄 적어 끼웠다. 「당신 기록이 다섯을 살렸다.」 읽을 사람은 없지만 적을 이유는 있었다.`,
      ng:`수습하다 비어 있던 약병을 건드렸다.<br><br>병이 구르다 바닥에서 깨졌다.<br>그 소리가 그렇게 클 줄 몰랐다. 조용한 방일수록 소리가 크다. 복도에서 응답처럼 기척이 일었다. 수습을 서둘러 마치고 나왔다.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-17, mind:-15 } }
  ] },

{ at:'S1', t:'환풍구 나사 — 푼 손',
  x:`바닥에 환풍구 덮개가 떨어져 있다. 나사 네 개가 가지런히 그 옆에 놓였다.<br><br>
    탐정은 나사 홈부터 본다.<br>
    공구 자국이 없다. 홈이 닳지 않았다.<br><br>
    손으로 풀었다. 안에서.`,
  o:[
    { l:'① 나사가 놓인 모양을 읽는다.', k:'gaze', dc:25,
      ok:`나사 네 개가 가지런히 모여 있다. 흘린 게 아니라 놓은 것이다.<br><br>도구 없이 풀고, 가지런히 놓는다. 손가락과 차분함이 있는 것이다.<br>힘만 쓰는 짐승이 아니라는 결론이 섰다. 그날부터 모든 덮개의 나사를 두드려 뭉개 놓았다. 못 풀게. 뭉갠 나사 앞에서 그것이 얼마나 차분할지는 두고 볼 일이다. 적어도 시간은 번다.`,
      ng:`나사를 집어 들고 홈만 들여다봤다.<br><br>그 사이 열린 구멍 쪽에 등을 주고 있었다.<br>구멍 안에서 바람이 훅 끼쳤을 때야 자세를 깨달았다. 증거를 쥔 채 뒷걸음으로 물러났다. 증거보다 등이 먼저다. 그 순서를 또 틀렸다.`,
      win:{ exp:23, dream:3 }, lose:{ spirit:-18, mind:-16 } },
    { l:'② 남은 덮개를 미리 다 떼어 확인한다.', k:'break', dc:25,
      doom:{ title:'네 개의 나사', what:'덮개 안쪽에서 기다리던 것에게 물려 관 속으로 끌려갑니다', dc:20, sec:36,
        text:`위험한 덮개라면 미리 떼어 속을 보는 게 낫다. 둘째 덮개에 손을 댔다.<br><br>덮개가 이쪽 손보다 먼저 움직였다. 안에서 밀렸다.<br>안에서 나사를 풀어 두고 기다린 것이다. 덮개는 문이 아니라 뚜껑이었다.<br><br>팔이 물려 관 속으로 끌려 들어간다. 바닥에 나사 네 개가 가지런히 남는다.`,
        dieText:`둘째 덮개가 도로 닫혀 있다.<br><br>나사까지 끼워져 있다.<br>가지런히.` },
      ok:`떼기 전에 덮개마다 귀를 대고 손끝으로 나사를 짚었다. 둘째 덮개의 나사가 헐거웠다.<br><br>이미 안에서 반쯤 풀린 나사다. 그 덮개는 떼지 않고 바깥에서 두 배로 조였다.<br>조이는 동안 안쪽에서 무게가 실렸다 빠지는 기척이 있었다. 문이 뚜껑인 걸 아는 놈과, 뚜껑을 다시 문으로 만드는 손의 싸움이었다. 이번엔 손이 이겼다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'어미 방 — 들어온 길',
  x:`어미의 방 바닥에 먹이 잔해가 쌓여 있다.<br><br>
    탐정은 잔해의 끌린 방향을 읽는다.<br>
    전부 한쪽 문에서 들어왔다.<br><br>
    문이 둘인데 하나만 쓴다.`,
  o:[
    { l:'① 안 쓰는 문의 이유를 추리한다.', k:'gaze', dc:26,
      ok:`먹이가 전부 한 문으로 들어온다면 다른 문은 어미도 안 쓰는 문이다.<br><br>안 쓰는 이유를 잔해가 말해 줬다. 그 문 쪽 바닥만 잔해가 없다. 알을 그쪽에 뒀기 때문이다. 제 길과 알 자리를 가른 것이다.<br>그러나 알 자리 가장자리에 벽을 타는 폭 한 사람의 턱이 있었다. 어미의 길도 알 자리도 아닌 세 번째 길. 그 턱으로 방을 건넜다. 어미가 쓰는 문으로는 그 시각에도 먹이가 들어오고 있었다. 수레처럼 정확하게.`,
      ng:`잔해 방향을 세는데 발밑에서 뼈가 바스러졌다.<br><br>방의 숨이 한 번 멎었다.<br>잔해 더미에 엎드려 긴 시간을 보냈다. 잔해 틈에서 보는 어미의 윤곽은 평생 잊기 어려울 것이다. 숨이 다시 고르게 돌 때 기어서 물러났다.`,
      win:{ exp:24, dream:4 }, lose:{ spirit:-21, hp:-27 } },
    { l:'② 벽 그늘을 따라 반대 문으로 간다.', k:'hide', dc:24,
      ok:`벽의 그늘이 끊기지 않는 쪽을 골라 붙었다.<br><br>그늘에서 그늘로, 숨을 나눠 쉬며 건넜다.<br>반대 문은 안에서 빗장이 삭아 있었다. 밀자 소리 없이 열렸다. 어미가 안 쓰는 문은 경첩도 조용했다. 안 쓰는 데는 이유가 있고 그 이유가 이쪽 편인 날도 있다.`,
      ng:`그늘이 한 군데 끊겨 있었다. 등불 든 손이 먼저 드러났다.<br><br>방 안쪽에서 공기가 쏠리는 기척이 왔다.<br>등불을 끄고 남은 그늘을 뛰다시피 건넜다. 문을 닫고 나서 보니 손등에 땀이 번들거렸다. 등불 든 손부터 숨기는 법을 그날 배웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'울타리 — 시험의 기록',
  x:`울타리에 시험 자국이 줄지어 있다.<br><br>
    긁고, 밀고, 물고. 자국의 종류가 다양하다.<br>
    탐정은 자국에 순서를 매긴다.<br><br>
    이건 짐승의 수사 기록이다.`,
  o:[
    { l:'① 시험의 순서를 재구성한다.', k:'gaze', dc:25, wake:1,
      ok:`오래된 자국은 아무 데나 긁었다. 중간 자국은 기둥만 노렸다. 새 자국은 한 지점에 몰려 있다.<br><br>체계적으로 좁혀 온 것이다. 그리고 몰린 지점의 제일 새 자국 밑에 개구멍이 뚫려 있었다.<br>수사는 끝났고 범행은 시작됐다. 그 지점을 돌무더기로 막고 지나는 동선을 울타리 반대편으로 바꿨다. 뚫은 놈들이 다시 수사를 시작하는 데는 시간이 걸릴 것이다.<br><br>짐승의 수사를 수사하는 눈이 생겼다. 상대도 추리한다. 그걸 아는 추리가 진짜 추리다.`,
      ng:`순서를 매기는 데 해가 기울었다.<br><br>제일 새 자국을 확인할 때는 이미 어스름이었다.<br>개구멍 안쪽에서 이쪽을 보는 눈과 마주쳤다. 수사 기록의 주인이 퇴근길이었다. 서로 못 본 척 물러났다. 다리가 후들거리는 못 본 척이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, spirit:-17 } },
    { l:'② 뚫릴 지점을 미리 막는다.', k:'fix', dc:23,
      ok:`시험 자국이 몰리는 지점에 돌과 가시덤불을 쌓았다.<br><br>다음 날 보니 돌무더기에 새 발톱 자국이 나 있었다.<br>시험이 처음부터 다시 시작된 것이다. 수사를 원점으로 돌리는 것, 그것도 수사 방해의 한 방법이다. 합법적인.`,
      ng:`막은 지점이 하나 어긋났다. 자국이 몰린 곳은 두 군데였다.<br><br>안 막은 쪽이 밤사이 더 깊어졌다.<br>아침에 급히 마저 막았다. 수사 기록은 끝까지 읽어야 한다. 반만 읽은 기록은 안 읽은 것과 같다.`,
      win:{ exp:15, hp:5 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'오두막 일지 — 사라진 열쇠',
  x:`사육사 오두막의 교대 일지다. 마지막 장이 미완성이다.<br><br>
    벽의 열쇠걸이에 고리만 남고 열쇠가 없다.<br>
    걸이 밑 먼지에 열쇠 모양 자국.<br><br>
    마지막 사람이 열쇠를 들고 나갔다.`,
  o:[
    { l:'① 일지로 마지막 사람의 행선지를 좁힌다.', k:'gaze', dc:26,
      ok:`마지막 줄이 이렇다. 「8구획 울타리 점검. 승강기 열쇠 지참. 금방 돌아옴.」<br><br>금방 돌아오지 못했다. 8구획으로 갔다.<br>8구획 울타리 밑에서 그를 찾았다. 오래전에 끝난 모습으로. 허리띠에 열쇠가 그대로 있었다. 승강기 비상 열쇠다. 일지를 찢어 그 위에 덮고 열쇠를 받았다. 일지 마지막 줄은 이쪽이 마저 적었다. 「돌아옴. 늦게.」`,
      ng:`행선지를 좁히다 일지의 다른 장에 빠졌다.<br><br>급이 기록, 날씨, 농담 한 줄. 사람 사는 기록이었다.<br>읽다 보니 한나절이 갔다. 열쇠 수색은 내일로 밀렸다. 증거에도 인정이 묻으면 걸음이 늦는다. 늦은 걸음 값은 내일 치르게 된다.`,
      win:{ exp:24, dream:4 }, lose:{ mind:-17, spirit:-17 } },
    { l:'② 어두워지기 전에 들판을 수색한다.', k:'sense', dc:25,
      doom:{ title:'수색', what:'어스름 속에서 기다리던 무리에게 물려 끌려갑니다', dc:19, sec:40,
        text:`해가 반 넘게 기울었지만 열쇠가 급했다. 들판으로 나갔다.<br><br>어스름은 그것들의 시간이다. 수색하는 눈은 수색당하는 등이기도 하다.<br>수풀 세 군데가 동시에 일어선다.<br><br>포위는 완성된 뒤에야 보인다. 탐정이 제일 잘 아는 법칙에 제가 걸렸다.`,
        dieText:`들판은 다시 조용하다.<br><br>열쇠는 어딘가의 허리띠에 그대로 있다.<br>다음 수색자를 기다리며.` },
      ok:`나가되 수색 범위를 울타리 안쪽 백 걸음으로 끊었다. 어스름 전에 돌아올 수 있는 반경이다.<br><br>그 백 걸음 안에서 점검 가방을 찾았다. 가방 안에 예비 열쇠 꾸러미.<br>본 열쇠는 못 찾았지만 예비면 충분하다. 반경을 끊는 것, 그게 수색과 실종의 차이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S2', t:'물가 — 발자국 시간표',
  x:`물가에 발자국이 겹겹이 찍혀 있다.<br><br>
    탐정은 겹침의 순서를 읽는다. 누가 누구 위에 찍었나.<br>
    겹침이 곧 시간표다.<br><br>
    물은 모두가 와야 하는 곳이다.`,
  o:[
    { l:'① 겹침 순서로 물가 시간표를 짠다.', k:'gaze', dc:25,
      ok:`큰 발자국은 늘 맨 위에 없다. 새벽 작은 자국들이 그 위에 찍혀 있다.<br><br>큰 것은 해 질 녘, 무리는 새벽. 그 사이 한낮이 비어 있다.<br>한낮에만 물을 길었다. 물통 가득, 서두르지 않고. 시간표는 사흘 내내 맞았다. 물가의 평화는 시간표의 평화였다.`,
      ng:`겹침을 거꾸로 읽었다. 위에 찍힌 걸 먼저로 봤다.<br><br>해 질 녘에 물을 길러 갔다.<br>물이 떨리기 시작할 때 물통을 버리고 뛰었다. 다음 날 가 보니 버린 물통이 밟혀 종잇장이 돼 있었다. 겹침의 순서는 아래가 먼저다. 종잇장이 가르쳐 줬다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-28, mind:-15 } },
    { l:'② 물가 웅덩이를 살핀다.', k:'luck', dc:23,
      ok:`큰 것이 디딘 자국에 물이 고여 웅덩이가 됐다. 그 안에 민물고기가 갇혀 있었다.<br><br>맨손으로 두 마리를 건졌다.<br>발자국이 어항이 될 줄은 몰랐다. 이 벌판에서는 재앙의 크기만큼 웅덩이도 크다. 거기 고기가 산다. 그런 셈법도 있다.`,
      ng:`웅덩이에 손을 넣는 순간 물가 전체가 조용해졌다.<br><br>새소리가 끊긴 것이다.<br>고기를 포기하고 덤불로 들어가 엎드렸다. 물가에 긴 그림자가 어른거리다 갔다. 새소리가 돌아온 뒤에야 일어났다. 빈손이 가벼웠다.`,
      win:{ exp:15, item:'민물고기' }, lose:{ hp:-25, spirit:-15 } }
  ] },

{ at:'S2', t:'몰이 — 보이는 한 마리',
  x:`능선에 한 마리가 서 있다. 숨지도 않고.<br><br>
    여태 그렇게 숨던 것들이 갑자기 보인다.<br>
    탐정은 명백한 것부터 의심한다.<br><br>
    보이는 데는 이유가 있다.`,
  o:[
    { l:'① 왜 보이는지를 먼저 푼다.', k:'gaze', dc:26, wake:1,
      ok:`보이라고 서 있는 것이다. 몰이꾼.<br><br>몰이꾼의 일은 겁을 줘서 반대로 뛰게 하는 것이다. 반대쪽이 그물이다.<br>반대도 정면도 아닌, 몰이꾼 쪽으로 비스듬히 질러갔다. 몰이꾼은 제 쪽으로 오는 먹이의 법을 모른다. 능선 밑을 스쳐 지나는 동안 그놈은 어쩔 줄 모르고 제자리만 돌았다. 그물 쪽 수풀에서 기다리다 지친 숨들이 길게 새어 나왔다.<br><br>보이는 것부터 의심하는 눈이 생겼다. 명백한 것이 가장 수상하다. 이 벌판에서도, 어디에서도.`,
      ng:`의심은 했는데 몸이 먼저 반대로 돌았다.<br><br>겁은 추리보다 빠르다.<br>스무 걸음 만에 수풀의 그물 기척을 느끼고 직각으로 꺾었다. 그물 가장자리를 긁듯이 빠져나왔다. 외투 등판이 찢겨 나갔다. 등가죽이 아닌 게 답례품이었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-29, spirit:-17 } },
    { l:'② 보이는 놈만 경계하며 반대로 빠진다.', k:'evade', dc:25,
      ok:`반대로 빠지되 전속력이 아니라 멈춤을 섞었다. 뛰고, 서고, 듣고.<br><br>멈출 때마다 그물 쪽 기척이 저희끼리 어긋났다. 먹이가 박자를 깨니 그물도 박자를 잃었다.<br>어긋난 틈새로 빠져나왔다. 몰이는 뛰는 먹이에게만 완벽하다. 걷다 서는 먹이는 몰이의 셈 밖이다.`,
      ng:`반대로 전속력으로 뛰었다. 몰이꾼이 바라던 그대로.<br><br>그물 한가운데로 들어갔다가 일행의 고함에 가까스로 방향을 꺾었다.<br>왼팔이 길게 긁혔다. 뛰면서 생각하는 건 안 된다. 생각하고 뛰어야 한다. 피가 그 순서를 적어 줬다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-15 } }
  ] },

{ at:'S2', t:'뼈 무더기 — 부러진 방식',
  x:`뼈 무더기가 또 나왔다. 탐정은 부러진 단면을 본다.<br><br>
    눌려 바스러진 것과 비틀려 꺾인 것.<br>
    범인마다 수법이 있다.<br><br>
    수법이 곧 지도다.`,
  o:[
    { l:'① 수법으로 구역의 주인을 가른다.', k:'gaze', dc:26,
      ok:`눌린 뼈는 큰 것의 수법이고 비틀린 뼈는 무리의 수법이다.<br><br>무더기마다 수법을 표시하니 벌판이 두 구역으로 갈라졌다. 그리고 그 사이, 어느 수법도 없는 띠가 있다.<br>양쪽 다 피하는 완충지대다. 서로의 눈치를 보는 땅. 그 띠를 길로 썼다. 두 세력 사이가 이 벌판에서 제일 안전한 길이라는 것. 사람 동네와 똑같다.`,
      ng:`단면을 가르는데 두 수법이 한 무더기에 섞여 있었다.<br><br>구역이 겹치는 땅이다. 전쟁터라는 뜻이다.<br>그 자리가 바로 거기였다. 표시고 뭐고 무더기를 두고 빠르게 벗어났다. 겹치는 구역은 지도에 검게 칠했다. 두 번 칠했다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-18, hp:-26 } },
    { l:'② 뼈 틈의 버섯을 거둔다.', k:'luck', dc:23,
      ok:`오래된 뼈 그늘에 버섯이 무더기로 올라와 있었다.<br><br>아는 종이다. 먹는 것.<br>뼈는 안 건드리고 버섯만 땄다. 죽음 위에서 저녁거리가 자란다. 이 벌판의 순환은 입맛을 안 가린다.`,
      ng:`버섯을 따다 괴어 있던 뼈를 건드렸다.<br><br>무더기 윗단이 와르르 흘렀다.<br>소리가 벌판을 건너갔다. 버섯 반 줌을 쥔 채 덤불에 숨어 한 식경을 보냈다. 저녁거리 값으로는 비쌌다.`,
      win:{ exp:14, item:'야생 버섯' }, lose:{ hp:-25, mind:-14 } },
    { l:'③ 뼈를 건드리지 않고 수만 적는다.', k:'steady', dc:24,
      ok:`무더기는 그대로 두고 종류와 수만 적었다. 짐승 여섯, 큰 짐승 둘.<br><br>사람 뼈가 없다는 것도 적었다.<br>적다 보니 이 무더기가 쌓인 기간이 셈됐다. 오래된 사냥터다. 오래된 사냥터는 주인이 바뀌지 않는 사냥터다. 주인의 식성을 아는 것만으로 밤이 덜 무서워졌다.`,
      ng:`적는 데 집중하다 바람이 바뀐 걸 놓쳤다.<br><br>이쪽 냄새가 벌판 안쪽으로 흘러갔다.<br>수첩을 덮기도 전에 멀리서 응답이 왔다. 긴 울음 하나. 기록은 챙겼고 자리는 버렸다. 바람도 증거물이다. 흐르는 증거물.`,
      win:{ exp:16, mind:5 }, lose:{ mind:-16, spirit:-15 } }
  ] },

{ at:'S2', t:'급이기 — 태엽이 반 남았다',
  x:`기둥에 매달린 급이기다. 태엽식.<br><br>
    태엽이 반 감겨 있다. 아직 작동한다는 뜻이다.<br>
    작동하면 종이 울리고 먹이통이 열린다.<br><br>
    울리면 모두 온다.`,
  o:[
    { l:'① 작동 시각을 계산해 피해 간다.', k:'gaze', dc:25,
      ok:`태엽의 감김과 톱니 간격으로 셈했다. 다음 작동까지 한 식경.<br><br>한 식경 뒤 이 둘레는 저녁 식탁이 된다.<br>그 전에 구역을 벗어났다. 멀리서 종소리가 울리고, 벌판의 기척이 전부 그쪽으로 쏠리는 게 느껴졌다. 남의 저녁 시간이 이쪽의 통행 시간이다. 시간표는 늘 둘로 읽는 것이다.`,
      ng:`톱니 하나를 잘못 셌다. 한 식경이 아니라 반 식경이었다.<br><br>구역을 반쯤 벗어났을 때 종이 울렸다.<br>사방에서 모여드는 기척 사이를 숨죽여 빠져나왔다. 늦게 가는 시계는 차라리 낫다. 빠르게 가는 시계가 사람 잡는다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 태엽을 끝까지 감아 시한 미끼로 쓴다.', k:'break', dc:25,
      doom:{ title:'급이 종', what:'종소리에 먼저 온 것에게 물려 끌려갑니다', dc:20, sec:36,
        text:`태엽을 감는 손잡이가 뻑뻑했다. 힘을 주자 톱니가 미끄러지며 종이 반 박자 울렸다.<br><br>반 박자면 충분했다. 제일 가까이 있던 놈에게는.<br>수풀이 바로 뒤에서 열린다. 종 옆에 서 있는 것은 먹이통 옆에 서 있는 것이다.<br><br>통이 열리기도 전에 첫 손님에게 물려 끌려간다. 급이기는 정직하게 제 일을 했다.`,
        dieText:`태엽은 끝까지 감겨 있다.<br><br>한 식경 뒤 종이 울리고 통이 열렸다.<br>모인 것들 몫은 통 안의 것만이 아니었다.` },
      ok:`감되 종 망치부터 헝겊으로 감쌌다. 소리 없이 태엽만 끝까지 감고 떠났다.<br><br>한 식경 뒤 멀리서 헝겊 너머의 둔한 종소리가 울렸다.<br>둔한 소리에도 벌판의 기척이 그쪽으로 몰렸다. 그 사이 이쪽은 반대쪽 경계를 공짜로 건넜다. 시한 미끼는 설치가 반, 철수가 반이다. 철수를 먼저 정하고 설치했다.`,
      win:{ exp:23, dream:4 } }
  ] },

{ at:'S2', t:'승강기 — 왜 위에 있나',
  x:`승강기 통로 밑에 다섯이 모였다. 함이 꼭대기에 있다.<br><br>
    안내판에는 비상 시 최하층 대기라 적혀 있다.<br>
    규정과 다르다. 누가 타고 올라갔다.<br><br>
    탐정은 마지막 사건을 푼다.`,
  o:[
    { l:'① 호출반의 흔적으로 마지막 밤을 푼다.', k:'gaze', dc:26, wake:1,
      ok:`호출 단추에 마른 핏자국. 그 옆 벽에 숯으로 눌러쓴 글씨. 「먼저 올려 보냄. 나는 남아서 보냄.」<br><br>다친 사람을 태워 올리고 한 사람이 남아 단추를 지켰다. 함이 위에 있는 건 규정 위반이 아니라 구조의 증거다.<br>남은 사람의 자리도 찾았다. 통로 옆 비품실, 안에서 잠긴. 문틈으로 수동 윈치 손잡이가 보였다. 그는 끝까지 윈치 옆을 지켰다. 문을 열고 그 윈치로 함을 내렸다. 그의 일을 마저 끝내 준 것이다.<br><br>기계 하나에서 두 사람의 마지막 밤을 읽었다. 사건의 끝이 늘 비극만은 아니다. 하나는 올라갔다. 그걸 읽어 낸 눈이 오늘 다섯을 올린다.`,
      ng:`핏자국에서 추리가 엉켰다. 싸움으로 읽은 것이다.<br><br>함을 내릴 생각을 못 하고 통로 벽을 반나절 뒤졌다.<br>해 질 녘에야 비품실의 윈치를 찾았다. 반나절 값이 어스름이었다. 어스름 속에서 윈치를 감는 손이 바빴다. 추리가 어두우면 길도 어두워진다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 남은 자의 자리에 돌 하나를 얹고 떠난다.', k:'bond', dc:24,
      ok:`비품실 앞에 돌 하나를 얹었다. 이름은 모른다. 한 일은 안다.<br><br>다섯이 차례로 돌을 하나씩 보탰다.<br>다섯 개짜리 돌무더기가 섰다. 함이 내려오는 동안 아무도 말을 안 했다. 올라가는 길이 그 사람 덕인 걸 다섯이 다 알아서였다.`,
      ng:`돌을 얹는데 비품실 문이 삐걱 울렸다.<br><br>그 소리가 벌판 쪽까지 간 모양이었다.<br>수풀 기척이 가까워지기 전에 서둘러 함에 올랐다. 예는 차렸고 발은 급했다. 그 사람도 이해할 것이다. 급한 발을 제일 잘 아는 사람이니까.`,
      win:{ exp:16, spirit:6 }, lose:{ spirit:-16, hp:-26 } }
  ] }
]);
